  const BACKUP_IMPORT_MAX_SIZE = 100 * 1024 * 1024;
  /** ZIP 内 IndexedDB 附加资源清单（TTS 语音缓存等；剧情 narrativeV1 与 userFont 单独处理） */
  const BACKUP_IDB_ASSETS_MANIFEST = "idb-assets/manifest.json";
