  function normalizeYouDogUserProfile(raw) {
    const o = raw && typeof raw === "object" ? raw : {};
    return {
      nickname: String(o.nickname || "").trim().slice(0, 24),
      realName: String(o.realName || "").trim().slice(0, 24),
      avatarUrl: String(o.avatarUrl || "").trim(),
      persona: String(o.persona || "").trim().slice(0, 800),
      anonAlias: normalizeYouDogAnonAlias(o.anonAlias || ""),
    };
  }

  function ensureYouDogUserProfile() {
    youDogUserProfile = normalizeYouDogUserProfile(youDogUserProfile);
    if (!youDogUserProfile.anonAlias) {
      const suffix = Math.floor(Math.random() * 9000 + 1000);
      youDogUserProfile.anonAlias = "@嗅友" + suffix;
    }
    return youDogUserProfile;
  }

  function isYouDogUserProfileReady() {
    const p = ensureYouDogUserProfile();
    return !!(p.nickname && p.persona);
  }

  function getYouDogUserDisplayNickname() {
    const p = ensureYouDogUserProfile();
    return p.nickname || "用户";
  }

  function getYouDogUserRealName() {
    const p = ensureYouDogUserProfile();
    return p.realName || p.nickname || "用户";
  }

  function getYouDogUserAvatarUrl() {
    return ensureYouDogUserProfile().avatarUrl || "";
  }

  function buildYouDogUserProfilePromptBlock() {
    const p = ensureYouDogUserProfile();
    const lines = [
      "【用户（群友/活动区主角，角色仅按以下信息理解用户，不可引用剧情库「我的形象」）】",
      "昵称：" + (p.nickname || "未设置"),
      "真名：" + (p.realName || p.nickname || "未设置") + "（角色在平行世界互不相识，不可直呼真名）",
      "人设：" + (truncateCharsWithEllipsis(p.persona, YOU_DOG_PROMPT_PROFILE_MAX_CHARS) || "未设定"),
    ];
    return lines.join("\n");
  }

  function saveYouDogUserProfileFromDom() {
    const nickEl = document.getElementById("you-dog-profile-nickname");
    const realEl = document.getElementById("you-dog-profile-realname");
    const personaEl = document.getElementById("you-dog-profile-persona");
    const aliasEl = document.getElementById("you-dog-profile-alias-input");
    const nickname = nickEl ? String(nickEl.value || "").trim() : "";
    const realName = realEl ? String(realEl.value || "").trim() : "";
    const persona = personaEl ? String(personaEl.value || "").trim() : "";
    if (!nickname) {
      showToast("请填写昵称。", "warning");
      return false;
    }
    if (!persona) {
      showToast("请填写人设。", "warning");
      return false;
    }
    youDogUserProfile.nickname = nickname.slice(0, 24);
    youDogUserProfile.realName = realName.slice(0, 24);
    youDogUserProfile.persona = persona.slice(0, 800);
    if (aliasEl) {
      const alias = normalizeYouDogAnonAlias(aliasEl.value);
      if (alias && alias.replace(/^@/, "").length >= 2) {
        youDogUserProfile.anonAlias = alias;
      }
    }
    ensureYouDogUserProfile();
    schedulePersistNarrative();
    return true;
  }

  function sanitizeYouDogActivityState() {
    if (!youDogActivityData || typeof youDogActivityData !== "object") {
      youDogActivityData = { dmSessions: {}, surveys: {}, surveyResponses: {} };
    }
    if (!youDogActivityData.dmSessions || typeof youDogActivityData.dmSessions !== "object") {
      youDogActivityData.dmSessions = {};
    }
    if (!youDogActivityData.surveys || typeof youDogActivityData.surveys !== "object") {
      youDogActivityData.surveys = {};
    }
    if (!youDogActivityData.surveyResponses || typeof youDogActivityData.surveyResponses !== "object") {
      youDogActivityData.surveyResponses = {};
    }
    if (
      youDogActivityScreen !== "hub" &&
      youDogActivityScreen !== "dm" &&
      youDogActivityScreen !== "compose"
    ) {
      youDogActivityScreen = "hub";
    }
    if (youDogActivityHubTab !== "dm-list" && youDogActivityHubTab !== "forum") {
      youDogActivityHubTab = "dm-list";
    }
    ensureYouDogActivityBundle();
    sanitizeYouDogActivityDmSessions();
  }

  function sanitizeYouDogActivityDmSessions() {
    if (!isYouDogChatReady()) {
      if (youDogActivityData && youDogActivityData.dmSessions) {
        youDogActivityData.dmSessions = {};
      }
      return;
    }
    const validSet = new Set(getYouDogActivityMemberRefs());
    Object.keys(youDogActivityData.dmSessions || {}).forEach(function (ref) {
      if (!validSet.has(ref)) delete youDogActivityData.dmSessions[ref];
    });
    if (
      youDogActivityDmRef &&
      !validSet.has(youDogActivityDmRef)
    ) {
      youDogActivityDmRef = null;
      if (youDogActivityScreen === "dm") youDogActivityScreen = "hub";
      clearYouDogActivityDmInteractionState();
    }
    Object.keys(youDogActivityData.dmSessions || {}).forEach(function (ref) {
      const session = youDogActivityData.dmSessions[ref];
      if (!session || !Array.isArray(session.messages)) return;
      session.messages.forEach(function (m) {
        if (!m || !m.text) return;
        const cleaned = stripYouDogBracketEmoji(m.text);
        if (cleaned) m.text = cleaned.slice(0, YOU_DOG_ACTIVITY_DM_TEXT_MAX);
      });
    });
  }

  function ensureYouDogActivityBundle() {
    const key = YOU_DOG_ACTIVITY_BUNDLE_KEY;
    if (!youDogTwitterData[key]) {
      youDogTwitterData[key] = { posts: [], anonIdMap: {}, userPersonaMap: {} };
    }
    const bundle = youDogTwitterData[key];
    if (!Array.isArray(bundle.posts)) bundle.posts = [];
    if (!bundle.anonIdMap || typeof bundle.anonIdMap !== "object") bundle.anonIdMap = {};
    (bundle.posts || []).forEach(function (p) {
      if (!p) return;
      if (p.text) p.text = stripYouDogBracketEmoji(p.text);
      if (Array.isArray(p.comments)) {
        p.comments.forEach(function (c) {
          if (c && c.text) c.text = stripYouDogBracketEmoji(c.text);
        });
      }
    });
    return bundle;
  }

  function getYouDogActivityPosts() {
    const bundle = ensureYouDogActivityBundle();
    return (bundle.posts || [])
      .slice()
      .sort(function (a, b) {
        const ta = a && typeof a.createdAt === "number" ? a.createdAt : 0;
        const tb = b && typeof b.createdAt === "number" ? b.createdAt : 0;
        return tb - ta;
      });
  }

  function getYouDogActivityMemberRefs() {
    if (!isYouDogChatReady()) return [];
    return (ensureYouDogChatData().members || [])
      .map(function (m) {
        return m && m.memberRef;
      })
      .filter(Boolean);
  }

  function getYouDogActivityDmSession(memberRef) {
    const ref = String(memberRef || "").trim();
    if (!ref) return { messages: [], lastReadAt: 0 };
    sanitizeYouDogActivityState();
    if (!youDogActivityData.dmSessions[ref]) {
      youDogActivityData.dmSessions[ref] = { messages: [], lastReadAt: 0 };
    }
    if (!Array.isArray(youDogActivityData.dmSessions[ref].messages)) {
      youDogActivityData.dmSessions[ref].messages = [];
    }
    if (typeof youDogActivityData.dmSessions[ref].lastReadAt !== "number") {
      youDogActivityData.dmSessions[ref].lastReadAt = 0;
    }
    return youDogActivityData.dmSessions[ref];
  }

  function hasYouDogActivityDmUnread(memberRef) {
    const session = getYouDogActivityDmSession(memberRef);
    const msgs = session.messages || [];
    if (!msgs.length) return false;
    const lastReadAt = typeof session.lastReadAt === "number" ? session.lastReadAt : 0;
    return msgs.some(function (m) {
      if (!m || m.role !== "char") return false;
      const t = Number(m.time);
      return Number.isFinite(t) && t > lastReadAt;
    });
  }

  function markYouDogActivityDmRead(memberRef) {
    const ref = String(memberRef || "").trim();
    if (!ref) return;
    const session = getYouDogActivityDmSession(ref);
    session.lastReadAt = Date.now();
    schedulePersistNarrative();
  }

  function syncYouDogActivityDmReadIfViewing(memberRef) {
    const ref = String(memberRef || "").trim();
    if (!ref || youDogActivityScreen !== "dm" || youDogActivityDmRef !== ref) return;
    markYouDogActivityDmRead(ref);
  }

  function getYouDogActivityMemberLabel(memberRef) {
    return isYouDogChatReady()
      ? getYouDogChatMemberDisplayName(memberRef).split(" · ")[0]
      : String(memberRef || "未知");
  }

  function formatYouDogActivityDmListTime(ts) {
    const n = Number(ts);
    if (!n || !Number.isFinite(n)) return "";
    const diff = Date.now() - n;
    if (diff < 60000) return "刚刚";
    if (diff < 3600000) return Math.floor(diff / 60000) + "分钟前";
    if (diff < 86400000) return Math.floor(diff / 3600000) + "小时前";
    const d = new Date(n);
    return (d.getMonth() + 1) + "/" + d.getDate();
  }

  function getYouDogActivityDmPreview(memberRef) {
    const session = getYouDogActivityDmSession(memberRef);
    const msgs = session.messages || [];
    if (!msgs.length) return "点击开始聊天";
    const last = msgs[msgs.length - 1];
    const prefix = last && last.role === "user" ? "我: " : "";
    if (last && last.kind === "survey") {
      const survey = getYouDogSurvey(last.surveyId);
      return truncateCharsWithEllipsis(prefix + (survey ? buildYouDogSurveyDisplayText(survey) : "📋 问卷"), 42);
    }
    if (last && last.kind === "survey_reply") return truncateCharsWithEllipsis(prefix + "📋 问卷回复", 42);
    return truncateCharsWithEllipsis(prefix + String((last && last.text) || ""), 42);
  }

  function getYouDogActivityPostListTitle(text) {
    const first = String(text || "")
      .trim()
      .split(/\n/)[0];
    if (!first) return "无标题";
    return first.length > 28 ? truncateCharsWithEllipsis(first, 28) : first;
  }

  function getYouDogActivityPostListPreview(text) {
    const trimmed = String(text || "").trim();
    if (trimmed.length <= 28) return "";
    return truncateCharsWithEllipsis(trimmed, 72);
  }

  function capYouDogActivityDmText(text) {
    return sanitizeChatBracketEmojiText(text)
      .replace(/[ \t]{2,}/g, " ")
      .trim()
      .slice(0, YOU_DOG_ACTIVITY_DM_TEXT_MAX);
  }

  function ensureYouDogSurveysStore() {
    sanitizeYouDogActivityState();
    return youDogActivityData.surveys;
  }

  function parseYouDogSurveyQuestionsFromText(text) {
    return String(text || "")
      .split(/\n/)
      .map(function (line) {
        return truncateCharsWithEllipsis(
          String(line || "")
            .replace(/^\s*\d+[\.\)、]\s*/, "")
            .trim(),
          YOU_DOG_SURVEY_QUESTION_MAX
        );
      })
      .filter(Boolean)
      .slice(0, YOU_DOG_SURVEY_MAX_QUESTIONS);
  }

  function normalizeYouDogSurvey(raw) {
    if (!raw || typeof raw !== "object") return null;
    const questions = Array.isArray(raw.questions)
      ? raw.questions
          .map(function (q) {
            return truncateCharsWithEllipsis(String(q || "").trim(), YOU_DOG_SURVEY_QUESTION_MAX);
          })
          .filter(Boolean)
          .slice(0, YOU_DOG_SURVEY_MAX_QUESTIONS)
      : [];
    if (!questions.length) return null;
    const title = truncateCharsWithEllipsis(String(raw.title || "问卷").trim() || "问卷", YOU_DOG_SURVEY_TITLE_MAX);
    return {
      id: String(raw.id || uid("yds")).trim(),
      title: title,
      questions: questions,
      createdAt: typeof raw.createdAt === "number" ? raw.createdAt : Date.now(),
      scope: String(raw.scope || "group").trim() === "dm" ? "dm" : "group",
      dmTargetRef: String(raw.dmTargetRef || "").trim(),
    };
  }

  function getYouDogSurvey(surveyId) {
    const id = String(surveyId || "").trim();
    if (!id) return null;
    sanitizeYouDogActivityState();
    const hit = youDogActivityData.surveys[id];
    return hit ? normalizeYouDogSurvey(hit) : null;
  }

  function createYouDogSurvey(title, questionsText, opts) {
    opts = opts && typeof opts === "object" ? opts : {};
    const questions = parseYouDogSurveyQuestionsFromText(questionsText);
    if (!questions.length) return null;
    const survey = normalizeYouDogSurvey({
      title: title,
      questions: questions,
      scope: opts.scope || "group",
      dmTargetRef: opts.dmTargetRef || "",
    });
    if (!survey) return null;
    ensureYouDogSurveysStore()[survey.id] = survey;
    schedulePersistNarrative();
    return survey;
  }

  function buildYouDogSurveyDisplayText(survey) {
    if (!survey) return "📋 问卷";
    return "📋 " + survey.title + "（" + survey.questions.length + " 题）";
  }

  function normalizeYouDogSurveyAnswers(survey, rawAnswers) {
    if (!survey || !Array.isArray(survey.questions)) return [];
    const list = Array.isArray(rawAnswers) ? rawAnswers : [];
    return survey.questions.map(function (q, idx) {
      const item = list[idx];
      let answer = "";
      if (item && typeof item === "object") answer = String(item.a || item.answer || item.text || "").trim();
      else answer = String(item || "").trim();
      return {
        q: q,
        a: truncateCharsWithEllipsis(answer || "…", YOU_DOG_SURVEY_ANSWER_MAX),
      };
    });
  }

  function formatYouDogSurveyReplyText(survey, answers) {
    if (!survey) return "📋 问卷回复";
    const lines = ["【" + survey.title + " · 已填写】"];
    (answers || []).forEach(function (row, idx) {
      lines.push(idx + 1 + ". " + (row.q || "?"));
      lines.push("   答：" + (row.a || "…"));
    });
    return lines.join("\n");
  }

  function buildYouDogSurveyCardInnerHtml(survey, opts) {
    opts = opts && typeof opts === "object" ? opts : {};
    if (!survey) return "";
    const isReply = opts.mode === "reply";
    const answers = Array.isArray(opts.answers) ? opts.answers : [];
    if (isReply) {
      const qaHtml = answers
        .map(function (row, idx) {
          return (
            '<div class="you-dog-survey-card__qa">' +
            '<div class="you-dog-survey-card__q">' +
            escapeHtml(String(idx + 1) + ". " + (row.q || "")) +
            "</div>" +
            '<div class="you-dog-survey-card__a">' +
            escapeHtml(String(row.a || "…")) +
            "</div></div>"
          );
        })
        .join("");
      return (
        '<div class="you-dog-survey-card you-dog-survey-card--reply">' +
        '<div class="you-dog-survey-card__head">' +
        '<span class="you-dog-survey-card__icon" aria-hidden="true">📋</span>' +
        '<span class="you-dog-survey-card__title">' +
        escapeHtml(survey.title) +
        " · 已填写</span></div>" +
        '<div class="you-dog-survey-card__qa-list">' +
        qaHtml +
        "</div></div>"
      );
    }
    const listHtml = survey.questions
      .map(function (q, idx) {
        return (
          '<li class="you-dog-survey-card__item">' +
          '<span class="you-dog-survey-card__num">' +
          escapeHtml(String(idx + 1)) +
          ".</span>" +
          '<span class="you-dog-survey-card__qtext">' +
          escapeHtml(q) +
          "</span></li>"
        );
      })
      .join("");
    const hintHtml = opts.showHint
      ? '<p class="you-dog-survey-card__hint">角色填写后将通过私聊发回给你，不会出现在群里</p>'
      : opts.showDmHint
        ? '<p class="you-dog-survey-card__hint">请填写后发送问卷回复</p>'
        : "";
    return (
      '<div class="you-dog-survey-card">' +
      '<div class="you-dog-survey-card__head">' +
      '<span class="you-dog-survey-card__icon" aria-hidden="true">📋</span>' +
      '<span class="you-dog-survey-card__title">' +
      escapeHtml(survey.title) +
      "</span>" +
      '<span class="you-dog-survey-card__count">' +
      escapeHtml(String(survey.questions.length) + " 题") +
      "</span></div>" +
      '<ol class="you-dog-survey-card__list">' +
      listHtml +
      "</ol>" +
      hintHtml +
      "</div>"
    );
  }

  function buildYouDogSurveyComposerBtnHtml(target, disabled) {
    return (
      '<button type="button" class="you-dog-composer__survey-btn" data-you-dog-survey-open="' +
      escapeHtml(target) +
      '" aria-label="发问卷" title="发问卷"' +
      (disabled ? " disabled" : "") +
      '><svg class="icon-linear" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" aria-hidden="true"><path d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2"/><rect x="9" y="3" width="6" height="4" rx="1"/><path d="M9 12h6M9 16h4"/></svg></button>'
    );
  }

  function appendYouDogChatUserSurvey(surveyId) {
    const survey = getYouDogSurvey(surveyId);
    const data = ensureYouDogChatData();
    if (!survey || !isYouDogUserProfileReady()) return false;
    const msg = normalizeYouDogChatMessage(
      {
        id: uid("ydcm"),
        kind: "survey",
        memberRef: YOU_DOG_USER_PROFILE_REF,
        surveyId: survey.id,
        text: buildYouDogSurveyDisplayText(survey),
        time: "刚刚",
      },
      data
    );
    if (!msg) return false;
    data.messages.push(msg);
    schedulePersistNarrative();
    return true;
  }

  function appendYouDogActivityDmUserSurvey(memberRef, surveyId) {
    const ref = String(memberRef || "").trim();
    const survey = getYouDogSurvey(surveyId);
    if (!ref || !survey) return false;
    const session = getYouDogActivityDmSession(ref);
    session.messages.push({
      id: uid("ydadm"),
      role: "user",
      kind: "survey",
      surveyId: survey.id,
      text: buildYouDogSurveyDisplayText(survey),
      time: Date.now(),
    });
    schedulePersistNarrative();
    return true;
  }

  function appendYouDogSurveyDmCharReply(memberRef, surveyId, rawAnswers) {
    const ref = String(memberRef || "").trim();
    const survey = getYouDogSurvey(surveyId);
    if (!ref || !survey) return false;
    const answers = normalizeYouDogSurveyAnswers(survey, rawAnswers);
    sanitizeYouDogActivityState();
    if (!youDogActivityData.surveyResponses[surveyId]) {
      youDogActivityData.surveyResponses[surveyId] = {};
    }
    youDogActivityData.surveyResponses[surveyId][ref] = {
      answers: answers,
      respondedAt: Date.now(),
    };
    const session = getYouDogActivityDmSession(ref);
    session.messages.push({
      id: uid("ydadm"),
      role: "char",
      kind: "survey_reply",
      surveyId: survey.id,
      surveyAnswers: answers,
      text: formatYouDogSurveyReplyText(survey, answers),
      time: Date.now(),
    });
    schedulePersistNarrative();
    return true;
  }

  function buildYouDogSurveyResponsePrompt(survey, memberRefs) {
    const refs = Array.isArray(memberRefs) ? memberRefs.filter(Boolean) : [];
    const lines = [
      "请让以下角色分别填写用户问卷，并以 JSON 返回每人的答案。",
      YOU_DOG_PARALLEL_WORLD_RULE,
      YOU_DOG_GROUP_DM_SYNC_RULE,
      YOU_DOG_ACTIVITY_DM_FRIEND_RULE,
      "",
      buildYouDogUserProfilePromptBlock(),
      "",
      "【问卷】",
      "标题：" + survey.title,
    ];
    survey.questions.forEach(function (q, idx) {
      lines.push(idx + 1 + ". " + q);
    });
    lines.push("");
    lines.push("【须填写的角色（memberRef 须来自此列表）】");
    refs.forEach(function (ref) {
      const parsed = parseYouDogChatMemberRef(ref);
      if (!parsed) return;
      const plot = plots.find(function (p) {
        return p.id === parsed.plotId;
      });
      if (!plot) return;
      lines.push("════ " + getYouDogActivityMemberLabel(ref) + "（memberRef=" + ref + "）════");
      lines.push(buildYouDogChatPlotContextBlock(plot, parsed.charId));
      appendYouDogGroupDmSyncForMember(lines, ref);
    });
    lines.push(
      "要求：每人按人设真诚填写，口语自然，每题 1~3 句；答案须与角色性格、剧情一致。" +
        "禁止在群里回复，只输出私聊问卷结果。" +
        '\n只输出 JSON：{"responses":[{"memberRef":"plotId:charId","answers":[{"q":"题目原文","a":"回答"}]}]}'
    );
    return lines.join("\n");
  }

  function buildYouDogSurveyDmResponsePrompt(survey, memberRef) {
    const ref = String(memberRef || "").trim();
    const parsed = parseYouDogChatMemberRef(ref);
    const plot = parsed
      ? plots.find(function (p) {
          return p.id === parsed.plotId;
        })
      : null;
    const lines = [
      "请让该角色填写用户私聊发来的问卷，并以 JSON 返回答案。",
      YOU_DOG_PARALLEL_WORLD_RULE,
      YOU_DOG_GROUP_DM_SYNC_RULE,
      YOU_DOG_ACTIVITY_DM_FRIEND_RULE,
      "",
      buildYouDogUserProfilePromptBlock(),
      "",
      "【问卷】",
      "标题：" + survey.title,
    ];
    survey.questions.forEach(function (q, idx) {
      lines.push(idx + 1 + ". " + q);
    });
    lines.push("");
    if (plot && parsed) {
      lines.push("════ " + getYouDogActivityMemberLabel(ref) + " · 性格参考 ════");
      lines.push(buildYouDogChatPlotContextBlock(plot, parsed.charId));
      lines.push("");
      appendYouDogGroupDmSyncForMember(lines, ref);
    }
    lines.push(
      "要求：按人设真诚填写，口语自然，每题 1~3 句。" +
        '\n只输出 JSON：{"answers":[{"q":"题目原文","a":"回答"}]}'
    );
    return lines.join("\n");
  }

  async function generateYouDogSurveyGroupResponses(slot, surveyId) {
    const survey = getYouDogSurvey(surveyId);
    if (!survey || youDogSurveyGenerating) return;
    const refs = getYouDogChatSpeakerPoolRefs();
    if (!refs.length) {
      showToast("请先在身份设置里勾选参与发言的角色。", "warning");
      openYouDogChatPersonaModal();
      return;
    }
    youDogSurveyGenerating = true;
    renderYouDogScreen(slot || els.youDogContentSlot());
    try {
      showToast("角色正在填写问卷，完成后会私发给你…", "info");
      const _genCtx = beginGenCall("you-dog-survey-group", { slot: slot, surveyId: surveyId });
      const raw = await callChatCompletion(
        [
          {
            role: "system",
            content:
              "你是中文互动叙事助手。生成角色填写问卷的 JSON。\n" +
              YOU_DOG_ACTIVITY_DM_FRIEND_RULE +
              "\n只输出一个 JSON 对象，不要用 markdown 代码围栏。",
          },
          { role: "user", content: buildYouDogSurveyResponsePrompt(survey, refs) },
        ],
        0.86,
        8192,
        chatApiOptsFromGen(_genCtx)
      );
      const parsed = parseAssistantJsonObject(raw);
      const list = parsed && Array.isArray(parsed.responses) ? parsed.responses : [];
      const allowed = new Set(refs);
      let added = 0;
      list.forEach(function (item) {
        const ref = resolveYouDogChatPoolMemberRef(item && item.memberRef, refs);
        if (!ref || !allowed.has(ref)) return;
        if (appendYouDogSurveyDmCharReply(ref, surveyId, item && item.answers)) added++;
      });
      if (!added) throw new Error("未能生成有效的问卷回复");
      showToast("已有 " + added + " 位角色通过私聊发回问卷", "success");
    } catch (err) {
      console.error(err);
      showToast(err && err.message ? err.message : "问卷回复生成失败", "error", 4200);
    } finally {
      clearGenCallContext();
      youDogSurveyGenerating = false;
      renderYouDogScreen(slot || els.youDogContentSlot());
    }
  }

  async function generateYouDogSurveyDmResponse(slot, surveyId, memberRef) {
    const survey = getYouDogSurvey(surveyId);
    const ref = String(memberRef || "").trim();
    if (!survey || !ref || youDogSurveyGenerating) return;
    youDogSurveyGenerating = true;
    renderYouDogScreen(slot || els.youDogContentSlot());
    try {
      showToast("对方正在填写问卷…", "info");
      const _genCtx = beginGenCall("you-dog-survey-dm", { slot: slot, surveyId: surveyId, memberRef: ref });
      const raw = await callChatCompletion(
        [
          {
            role: "system",
            content:
              "你是中文互动叙事助手。生成角色填写问卷的 JSON。\n" +
              YOU_DOG_ACTIVITY_DM_FRIEND_RULE +
              "\n只输出一个 JSON 对象。",
          },
          { role: "user", content: buildYouDogSurveyDmResponsePrompt(survey, ref) },
        ],
        0.85,
        4096,
        chatApiOptsFromGen(_genCtx)
      );
      const parsed = parseAssistantJsonObject(raw);
      if (!appendYouDogSurveyDmCharReply(ref, surveyId, parsed && parsed.answers)) {
        throw new Error("未能生成问卷回复");
      }
      showToast("已收到问卷回复", "success");
    } catch (err) {
      console.error(err);
      showToast(err && err.message ? err.message : "问卷回复生成失败", "error", 4200);
    } finally {
      clearGenCallContext();
      youDogSurveyGenerating = false;
      renderYouDogScreen(slot || els.youDogContentSlot());
      scrollYouDogActivityDmToEnd(slot || els.youDogContentSlot());
      scheduleYouDogChatThreadsScrollToEnd(slot || els.youDogContentSlot());
    }
  }

  function openYouDogSurveyModal(target) {
    youDogSurveyModalTarget = target === "dm" ? "dm" : "group";
    youDogSurveyComposeDraft = { title: "", questions: "" };
    const modal = els.modalYouDogSurvey();
    const titleEl = els.youDogSurveyTitle();
    const questionsEl = els.youDogSurveyQuestions();
    if (titleEl) titleEl.value = "";
    if (questionsEl) questionsEl.value = "";
    if (modal) modal.hidden = false;
  }

  function closeYouDogSurveyModal() {
    const modal = els.modalYouDogSurvey();
    if (modal) modal.hidden = true;
    youDogSurveyComposeDraft = { title: "", questions: "" };
  }

  async function submitYouDogSurveyFromModal(slot) {
    if (youDogSurveyGenerating) return;
    if (!isYouDogUserProfileReady()) {
      showToast("请先完善你的身份（昵称与人设）。", "warning");
      openYouDogPersonaModal();
      return;
    }
    const titleEl = els.youDogSurveyTitle();
    const questionsEl = els.youDogSurveyQuestions();
    const title = titleEl ? String(titleEl.value || "").trim() : "";
    const questionsText = questionsEl ? String(questionsEl.value || "").trim() : "";
    if (!questionsText) {
      showToast("请至少输入一个问题（每行一题）", "warning");
      return;
    }
    const target = youDogSurveyModalTarget === "dm" ? "dm" : "group";
    const dmRef = youDogActivityDmRef;
    if (target === "dm" && !dmRef) {
      showToast("请先进入私聊", "warning");
      return;
    }
    if (target === "group" && !isYouDogChatReady()) {
      showToast("请先建立群聊", "warning");
      openYouDogChatSetupModal();
      return;
    }
    const survey = createYouDogSurvey(title, questionsText, {
      scope: target,
      dmTargetRef: target === "dm" ? dmRef : "",
    });
    if (!survey) {
      showToast("问卷格式无效", "warning");
      return;
    }
    closeYouDogSurveyModal();
    const root = slot || els.youDogContentSlot();
    if (target === "group") {
      appendYouDogChatUserSurvey(survey.id);
      renderYouDogScreen(root);
      scrollYouDogChatThreadToEnd(root);
      await generateYouDogSurveyGroupResponses(root, survey.id);
    } else {
      appendYouDogActivityDmUserSurvey(dmRef, survey.id);
      renderYouDogScreen(root);
      scrollYouDogActivityDmToEnd(root);
      await generateYouDogSurveyDmResponse(root, survey.id, dmRef);
    }
  }

  function pickYouDogActivityProactiveDmRefs() {
    const refs = getYouDogActivityMemberRefs();
    if (!refs.length) return [];
    const shuffled = shuffleYouDogArray(refs);
    const count =
      shuffled.length >= YOU_DOG_ACTIVITY_PROACTIVE_DM_MIN
        ? YOU_DOG_ACTIVITY_PROACTIVE_DM_MIN
        : shuffled.length;
    return shuffled.slice(0, count);
  }

  function buildYouDogActivityDmHistoryBlock(memberRef, limit) {
    const session = getYouDogActivityDmSession(memberRef);
    const cap = typeof limit === "number" ? limit : 8;
    return (session.messages || [])
      .slice(-cap)
      .map(function (m) {
        const who =
          m.role === "user" ? getYouDogUserDisplayNickname() : getYouDogActivityMemberLabel(memberRef);
        return who + "：" + truncateCharsWithEllipsis(m.text || "", 100);
      })
      .join("\n");
  }

  function buildYouDogMemberGroupSaysBlock(memberRef, limit) {
    const ref = String(memberRef || "").trim();
    if (!ref) return "";
    const data = ensureYouDogChatData();
    const cap = typeof limit === "number" ? limit : YOU_DOG_GROUP_DM_SYNC_GROUP_SELF_LIMIT;
    const msgs = (data.messages || [])
      .filter(function (m) {
        return m && m.kind !== "system" && m.memberRef === ref;
      })
      .slice(-cap);
    if (!msgs.length) return "";
    return msgs
      .map(function (m) {
        const tag = m.tagName ? "「" + m.tagName + "」" : "";
        return "- 我" + tag + "（群聊）：" + truncateCharsWithEllipsis(m.text || "", 120);
      })
      .join("\n");
  }

  function buildYouDogMemberDmSaysBlock(memberRef, limit) {
    const ref = String(memberRef || "").trim();
    if (!ref) return "";
    const session = getYouDogActivityDmSession(ref);
    const cap = typeof limit === "number" ? limit : YOU_DOG_GROUP_DM_SYNC_DM_LIMIT;
    const msgs = (session.messages || [])
      .filter(function (m) {
        return m && m.role === "char" && m.kind !== "survey_reply";
      })
      .slice(-cap);
    if (!msgs.length) return "";
    return msgs
      .map(function (m) {
        return "- 我（私聊对用户）：" + truncateCharsWithEllipsis(m.text || "", 100);
      })
      .join("\n");
  }

  function appendYouDogGroupDmSyncForMember(lines, memberRef) {
    const ref = String(memberRef || "").trim();
    if (!ref) return false;
    const label = getYouDogActivityMemberLabel(ref);
    const groupSays = buildYouDogMemberGroupSaysBlock(ref);
    const dmSays = buildYouDogMemberDmSaysBlock(ref);
    if (!groupSays && !dmSays) return false;
    lines.push("【" + label + " · 群聊/私聊记忆（生成该角色发言时须一致，不可失忆或张冠李戴）】");
    if (groupSays) {
      lines.push("该角色自己在群聊说过：");
      lines.push(groupSays);
    }
    if (dmSays) {
      lines.push("该角色自己在私聊对用户说过（群友不知道，但该角色本人记得）：");
      lines.push(dmSays);
    }
    lines.push("");
    return true;
  }

  function buildYouDogActivityProactiveDmTopicRule() {
    return (
      "每条消息主题从以下类型中自然选取（不同角色可不同类型，不必统一）：\n" +
      "1) 衔接群聊最近话题，像私下找朋友唠两句；\n" +
      "2) 轻提各自剧情/近况，口语带过不讲大道理；\n" +
      "3) 向朋友请教、问用户意见或建议（工作学习生活均可）；\n" +
      "4) 纯闲聊：摸鱼、段子、游戏、外卖、天气等日常。"
    );
  }

  function buildYouDogActivityProactiveDmBatchPrompt(selectedRefs) {
    const refs = (selectedRefs || []).filter(Boolean);
    const data = ensureYouDogChatData();
    const poolLabels = refs
      .map(function (ref) {
        return getYouDogActivityMemberLabel(ref) + "（memberRef=" + ref + "）";
      })
      .filter(Boolean);
    const lines = [
      "请为「你才是狗·活动私聊」生成一批角色主动找用户私聊的消息 JSON。",
      YOU_DOG_PARALLEL_WORLD_RULE,
      YOU_DOG_GROUP_DM_SYNC_RULE,
      YOU_DOG_ACTIVITY_DM_FRIEND_RULE,
      YOU_DOG_CHAT_TONE_RULE,
      "",
      buildYouDogUserProfilePromptBlock(),
      "",
      "【本批须发私聊的角色（memberRef 只能来自下列；每人至少 " +
      YOU_DOG_ACTIVITY_PROACTIVE_MSGS_PER_CHAR +
      " 条，同一角色可连发短句）】",
      poolLabels.join("\n"),
      "",
      buildYouDogActivityProactiveDmTopicRule(),
      "",
    ];
    const groupHistory = buildYouDogChatHistoryBlock(data, 24);
    if (groupHistory) {
      lines.push("【群聊最近记录（须衔接，勿照搬；各角色须记得自己在群里的原话）】");
      lines.push(groupHistory);
      lines.push("");
    }
    refs.forEach(function (memberRef) {
      const parsed = parseYouDogChatMemberRef(memberRef);
      if (!parsed) return;
      const plot = plots.find(function (p) {
        return p.id === parsed.plotId;
      });
      if (!plot) return;
      lines.push("════ " + getYouDogActivityMemberLabel(memberRef) + " · 性格参考 ════");
      lines.push(buildYouDogChatPlotContextBlock(plot, parsed.charId));
      appendYouDogGroupDmSyncForMember(lines, memberRef);
      const dmHistory = buildYouDogActivityDmHistoryBlock(memberRef, 6);
      if (dmHistory) {
        lines.push("【与该用户已有私聊（须衔接，勿重复）】");
        lines.push(dmHistory);
      }
      lines.push("");
    });
    lines.push(
      "角色主动开口找用户私聊，不要求用户先说话；每条口语 1~3 句，8~120 字；" +
        "同一角色多条消息须按发送顺序排列，像连发几句。" +
        "\n只输出 JSON：{\"messages\":[{\"memberRef\":\"plotId:charId\",\"text\":\"...\"}, ...]}",
      "\n本批共 " +
        refs.length +
        " 位角色，合计至少 " +
        refs.length * YOU_DOG_ACTIVITY_PROACTIVE_MSGS_PER_CHAR +
        " 条消息。"
    );
    return lines.join("\n");
  }

  function buildYouDogActivitySingleProactiveDmPrompt(memberRef) {
    const parsed = parseYouDogChatMemberRef(memberRef);
    if (!parsed) return "";
    const plot = plots.find(function (p) {
      return p.id === parsed.plotId;
    });
    if (!plot) return "";
    const data = ensureYouDogChatData();
    const lines = [
      "请为「你才是狗·活动私聊」生成角色主动找用户私聊的一条消息 JSON。",
      YOU_DOG_PARALLEL_WORLD_RULE,
      YOU_DOG_GROUP_DM_SYNC_RULE,
      YOU_DOG_ACTIVITY_DM_FRIEND_RULE,
      YOU_DOG_CHAT_TONE_RULE,
      "",
      buildYouDogUserProfilePromptBlock(),
      "",
      "【发私聊的角色 memberRef=" + memberRef + "】",
      buildYouDogChatPlotContextBlock(plot, parsed.charId),
      "",
      buildYouDogActivityProactiveDmTopicRule(),
      "",
    ];
    appendYouDogGroupDmSyncForMember(lines, memberRef);
    const groupHistory = buildYouDogChatHistoryBlock(data, 20);
    if (groupHistory) {
      lines.push("【群聊最近记录（须衔接，勿照搬；该角色须记得自己在群里的原话）】");
      lines.push(groupHistory);
      lines.push("");
    }
    const dmHistory = buildYouDogActivityDmHistoryBlock(memberRef, 10);
    if (dmHistory) {
      lines.push("【与该用户已有私聊（须衔接，勿重复）】");
      lines.push(dmHistory);
      lines.push("");
    }
    lines.push(
      "角色主动开口找用户私聊，不要求用户先说话；须生成 " +
        YOU_DOG_ACTIVITY_PROACTIVE_MSGS_PER_CHAR +
        " 条，按发送顺序排列，每条口语 1~3 句，8~120 字。" +
        '\n只输出 JSON：{"messages":[{"text":"..."},{"text":"..."},{"text":"..."}]}'
    );
    return lines.join("\n");
  }

  function appendYouDogActivityDmCharMessages(memberRef, rawTexts, baseTime) {
    const ref = String(memberRef || "").trim();
    if (!ref) return 0;
    const session = getYouDogActivityDmSession(ref);
    const list = Array.isArray(rawTexts) ? rawTexts : rawTexts != null ? [rawTexts] : [];
    const t0 = typeof baseTime === "number" ? baseTime : Date.now();
    let added = 0;
    list.forEach(function (item, idx) {
      const text = capYouDogActivityDmText(typeof item === "string" ? item : item && item.text);
      if (!text) return;
      session.messages.push({
        id: uid("ydadm"),
        role: "char",
        text: text,
        time: t0 + idx * 4,
      });
      added++;
    });
    if (added) schedulePersistNarrative();
    return added;
  }

  function appendYouDogActivityProactiveDmMessages(parsed, allowedRefs) {
    const allowed = new Set((allowedRefs || []).filter(Boolean));
    const list = parsed && Array.isArray(parsed.messages) ? parsed.messages : [];
    const perChar = {};
    allowed.forEach(function (ref) {
      perChar[ref] = 0;
    });
    let msgCount = 0;
    const baseTime = Date.now();
    list.forEach(function (raw, idx) {
      const ref = String((raw && raw.memberRef) || "").trim();
      if (!allowed.has(ref)) return;
      const text = capYouDogActivityDmText(raw && raw.text);
      if (!text) return;
      const session = getYouDogActivityDmSession(ref);
      session.messages.push({
        id: uid("ydadm"),
        role: "char",
        text: text,
        time: baseTime + idx * 4,
      });
      perChar[ref] = (perChar[ref] || 0) + 1;
      msgCount++;
    });
    const charCount = Object.keys(perChar).filter(function (ref) {
      return perChar[ref] > 0;
    }).length;
    if (msgCount) schedulePersistNarrative();
    return { msgCount: msgCount, charCount: charCount, perChar: perChar };
  }

  function youDogOnChatTab() {
    return youDogMainTab === "messages" && youDogMessagesSegment === "group";
  }

  function syncYouDogLegacyChatSubScreen() {
    youDogChatSubScreen = youDogOnChatTab() ? "chat" : "feed";
  }

  /** 将旧版四 Tab（群聊/树洞/活动/我的）迁移为首页+消息+我的 */
  function normalizeYouDogMainTabLayout() {
    const tab = String(youDogMainTab || "").trim();
    if (tab === "home" || tab === "messages" || tab === "profile") {
      /* 已是新结构 */
    } else if (tab === "feed") {
      youDogMainTab = "home";
      youDogHomeSegment = "feed";
    } else if (tab === "chat") {
      youDogMainTab = "messages";
      youDogMessagesSegment = "group";
    } else if (tab === "activity" || tab === "playground") {
      if (youDogActivityScreen === "compose" || youDogActivityHubTab === "forum") {
        youDogMainTab = "home";
        youDogHomeSegment = "forum";
      } else if (youDogActivityScreen === "dm") {
        youDogMainTab = "messages";
        youDogMessagesSegment = "dm";
      } else if (youDogActivityHubTab === "forum") {
        youDogMainTab = "home";
        youDogHomeSegment = "forum";
      } else {
        youDogMainTab = "messages";
        youDogMessagesSegment = "dm";
      }
    } else {
      youDogMainTab = "home";
      youDogHomeSegment = "feed";
    }
    if (youDogHomeSegment !== "feed" && youDogHomeSegment !== "forum") {
      youDogHomeSegment = "feed";
    }
    if (youDogMessagesSegment !== "group" && youDogMessagesSegment !== "dm") {
      youDogMessagesSegment = "group";
    }
  }

