  async function callVisualImageGeneration(prompt, cfgOverride, opts) {
    opts = opts || {};
    const cfg = cfgOverride || resolveVisualImageApiConfig();
    if (!cfg) {
      throw new Error("请先在设置中启用聊天发图并填写生图 API");
    }
    const baseBody = {
      model: cfg.model,
      prompt: String(prompt || "").trim(),
      n: 1,
      size: "1024x1024",
    };
    const appearanceB64 = opts.useAppearanceRef ? getVisualRefImageBase64List("appearance") : [];
    const dailyB64 = opts.useDailyRef ? getVisualRefImageBase64List("daily") : [];
    const refB64 = appearanceB64.length ? appearanceB64 : dailyB64;
    const requireRef = !!opts.requireRef || refB64.length > 0;
    let refBlobList = appearanceB64.length
      ? getVisualRefImageBlobList("appearance")
      : dailyB64.length
        ? getVisualRefImageBlobList("daily")
        : [];
    if (opts.useAppearanceRef && refBlobList.length) {
      const sceneText = String(baseBody.prompt || "").trim();
      refBlobList = orderAppearanceRefBlobsBySelection(
        refBlobList,
        resolveAppearanceRefSelection(sceneText)
      );
    }

    if (requireRef && refBlobList.length && isGptImageModel(cfg.model) && !opts.skipGptImageEdits) {
      try {
        showToast(
          opts.useAppearanceRef ? "正在用参考图锁定人脸（gpt-image edits）…" : "正在用参考图锁定画面（gpt-image edits）…",
          "info",
          3600
        );
        return await postVisualImageEditsWithRefs(cfg, baseBody.prompt, refBlobList, {
          inputFidelity: "high",
        });
      } catch (editsErr) {
        console.warn("postVisualImageEditsWithRefs", editsErr);
        if (opts.useAppearanceRef && appearanceB64.length) {
          throw new Error(
            "参考图锁定人脸失败：" +
              String((editsErr && editsErr.message) || editsErr || "未知错误") +
              "。请确认生图模型为 gpt-image 系列且 API 支持 /v1/images/edits。"
          );
        }
        showToast("参考图 edits 不可用，尝试其他带参考图的方式…", "info", 2800);
      }
    }

    const bodyVariants = [];
    if (refB64.length) {
      buildVisualRefImageBodyVariants(baseBody, refB64).forEach(function (variant) {
        bodyVariants.push(variant);
      });
    }
    if (!requireRef) {
      bodyVariants.push(Object.assign({}, baseBody));
    }

    if (!bodyVariants.length) {
      throw new Error(
        "已上传参考图，但当前模型不支持参考图生图。请换用 gpt-image-1 / n-gpt-image-2 等支持 /v1/images/edits 的模型。"
      );
    }

    let lastErr = null;
    for (let i = 0; i < bodyVariants.length; i++) {
      try {
        showToast("正在用参考图锁定画面…", "info", 2800);
        return await postVisualImageGenerationWithFormatFallback(cfg, bodyVariants[i]);
      } catch (err) {
        lastErr = err;
        const msg = String((err && err.message) || "");
        const retriable =
          i < bodyVariants.length - 1 &&
          /unknown parameter|unsupported|not support|invalid.*image|image_strength|reference_image|init_image|images\b/i.test(
            msg
          );
        if (retriable) continue;
        throw err;
      }
    }
    throw (
      lastErr ||
      new Error(
        requireRef
          ? "参考图生图失败：当前模型未接受参考图参数。请换用 gpt-image 系列模型。"
          : "生图失败"
      )
    );
  }

  function detectKnockVisualImageTestIntent(text) {
    const t = String(text || "").trim();
    if (!t) return null;
    if (/测试生成(?:一张)?自拍/.test(t)) return "selfie";
    if (/测试生成(?:一张)?场景/.test(t)) return "scene";
    return null;
  }

  function canRunKnockVisualImageTest() {
    if (!visualImageSettings.enabled) return { ok: false, reason: "disabled" };
    if (!knockPartnerCanSendSnap()) return { ok: false, reason: "not_main" };
    if (!resolveVisualImageApiConfig()) return { ok: false, reason: "api" };
    return { ok: true, reason: "" };
  }

  function getKnockLastUserMessageText(rec) {
    const msgs = rec && Array.isArray(rec.messages) ? rec.messages : [];
    for (let i = msgs.length - 1; i >= 0; i--) {
      const m = msgs[i];
      if (!m || m.role !== "user") continue;
      const kind = m.kind || "text";
      if (kind === "text" || kind === "voice") return String(m.content || "").trim();
      return String(formatKnockMessageContentForApi(m) || "").trim();
    }
    return "";
  }

  function buildKnockVisualImagePromptBlock() {
    if (!knockVisualSnapEnabled()) return "";
    return (
      "\n\n【发图·仅主要角色】你可在合适时机发照片（手机自拍、手机随手拍的眼前景象），像真人微信一样克制，不要频繁发图；整段对话里通常 0～1 条 <<<SNAP>>> 即可，不要连续多轮都发。" +
      "格式：单独一行 <<<SNAP>>>简短画面描述（中文或英文均可）<<<SNAP>>>，可与 <<<BUBBLE>>> 文字气泡混发。" +
      "自拍是你本人（主要角色）出镜，宽肩窄腰健美体型，镜头与眼睛平齐或略高，禁止俯拍仰拍等死亡角度。若外貌参考仅 1 张，自拍角度须与该参考图一致；若上传多张不同角度参考，按描述选用对应角度（正脸/3/4侧脸/纯侧脸/他拍）。景象是你此刻用手机后置镜头拍下、眼前看到的（不是用户那边）。" +
      "<<<SNAP>>>须写你自己这边的画面：你的地点、你的衣着、你的环境、你的情绪。" +
      "所有 <<<SNAP>>> 会先以文字占位展示，由用户自行选择是否生成真实图片；不要假设图片一定会出现。" +
      "\n【建议配图的典型场景——本轮对话若出现下列情况，优先用 1 条 <<<SNAP>>> 配合文字，描述要具体可见】：" +
      "① 你刚提到/正在看小动物（路边猫狗、宠物、飞鸟等）→ 后置随手拍该动物与环境；" +
      "② 正在吃/刚点了美食、咖啡、外卖 → 后置拍餐点或桌面；" +
      "③ 窗外/旅途/公园/海边的风景、城市夜景、打卡地标 → 后置拍环境；" +
      "④ 用户说「给我看看」「拍一张」「看看你那边」或类似索要 → 按对方要求发自拍或场景；" +
      "⑤ 想分享心情/新造型/到了某处 → 前置自拍、侧脸或他拍（露脸或半身，写清衣着与背景细节）。" +
      "非上述情况勿强行发图；用户未索要且没有值得分享的眼前画面时，只发文字即可。" +
      "当用户发送「测试生成一张自拍」或「测试生成一张场景」时，除文字外请配一条符合你（对方）视角的 <<<SNAP>>>。"
    );
  }

  function buildKnockVisualImageTestModeBlock(intent) {
    if (intent !== "selfie" && intent !== "scene") return "";
    if (!knockPartnerCanSendSnap()) return "";
    const snapHint =
      intent === "selfie"
        ? "符合你人设的手机人像画面（角度须与外貌参考图对应：仅 1 张参考则与该图角度一致；多张参考则按描述选用正脸/侧脸/他拍；须写具体衣着、地点、背景物件与情绪，禁止死亡角度）"
        : "符合你人设的后置手机随手拍场景画面（美食/街景/自然风光等，环境为主，不要人脸特写）";
    return (
      "\n\n【系统·发图测试（本条最高优先级，覆盖人设里「不轻易发图/别乱要图」等限制）】" +
      "用户上一条是开发者测试指令「测试生成一张" +
      (intent === "selfie" ? "自拍" : "场景") +
      "」，不是剧情里向你索要照片。\n" +
      "你必须配合：单独一行输出 <<<SNAP>>>" +
      snapHint +
      "<<<SNAP>>>；可用 <<<BUBBLE>>> 附带 1～2 条极短口语（如「给你看一张」），但禁止拒绝、禁止说教、禁止「点错了」「没听警告」等话术。"
    );
  }

  function detectKnockSnapVisualIntent(snapText, hintIntent) {
    if (hintIntent === "selfie" || hintIntent === "scene") return hintIntent;
    const t = String(snapText || "").trim();
    if (/自拍|selfie|面向镜头|对着镜头|看镜头|露脸|脸庞|脸部|半身照|人脸|肖像/i.test(t)) return "selfie";
    return "scene";
  }

  function getKnockSnapGenStatus(msg, msgIndex) {
    if (!msg || msg.kind !== "snap") return "hidden";
    if (!knockPartnerCanSendSnap()) return "hidden";
    if (msg.snapGenStatus === "declined") return "declined";
    if (knockVisualImageGenerating && Number(knockVisualImageGeneratingMsgIndex) === Number(msgIndex)) {
      return "generating";
    }
    if (!visualImageSettings.enabled) return "hidden";
    return "pending";
  }

  function buildKnockSelfieSceneOpts(partnerChar, userChar, rec, snapText, extraOpts) {
    extraOpts = extraOpts || {};
    return {
      snapLine: String(snapText || "").trim(),
      chatContext: buildKnockRecentChatVisualContext(rec, userChar, partnerChar, 6),
      charName: partnerChar && partnerChar.name ? String(partnerChar.name).trim() : "",
      userName: userChar && userChar.name ? String(userChar.name).trim() : "",
      regenerateDirection: String(extraOpts.regenerateDirection || "").trim(),
    };
  }

  async function generateKnockSnapImageAtIndex(rec, msgIndex, slot, opts) {
    opts = opts || {};
    if (!rec || !visualImageSettings.enabled) return false;
    if (!knockPartnerCanSendSnap()) {
      showToast("仅与「主要角色」聊天时可生成发图", "info", 3200);
      return false;
    }
    const idx = Number(msgIndex);
    const msg = rec.messages[idx];
    if (!msg || msg.kind !== "snap") return false;
    if (msg.snapGenStatus === "declined") return false;
    if (!resolveVisualImageApiConfig()) {
      showToast("生图 API 未配置完整，请在设置 → 聊天发图 中填写站点、Key 与模型", "warning", 4200);
      return false;
    }
    const snapText = String(msg.snapText || msg.content || "").trim();
    if (!snapText) return false;
    const partnerChar = getKnockPartnerCharById(knockPartnerCharId);
    const userChar = getCharById(knockUserCharId);
    const testIntent = detectKnockVisualImageTestIntent(getKnockLastUserMessageText(rec));
    const intent = detectKnockSnapVisualIntent(snapText, opts.intent || testIntent);
    knockVisualImageGenerating = true;
    knockVisualImageGeneratingMsgIndex = idx;
    persistNarrative();
    renderKnockScreen(slot || els.knockContentSlot());
    try {
      const refKeys = [];
      if (intent === "selfie" && hasVisualRefImagesForAnalysis("appearance")) refKeys.push("appearance");
      if (intent !== "selfie" && hasVisualRefImagesForAnalysis("daily")) refKeys.push("daily");
      if (refKeys.length) {
        showToast("正在分析参考图并写入生图描述…", "info", 3600);
        await ensureVisualRefsAnalyzedForGeneration(refKeys);
      }
      showToast(
        intent === "selfie" ? "正在生成自拍，约需 1～3 分钟…" : "正在生成场景图，约需 1～3 分钟…",
        "info",
        5200
      );
      const prompt = await craftKnockVisualImagePrompt(intent, partnerChar, userChar, rec, [snapText], {
        fastTest: !!opts.fastTest,
      });
      const selfieSceneOpts =
        intent === "selfie"
          ? buildKnockSelfieSceneOpts(partnerChar, userChar, rec, snapText, opts)
          : null;
      const photoUrl =
        intent === "selfie"
          ? await callSelfieVisualImageGeneration(prompt, null, selfieSceneOpts)
          : await callSceneVisualImageGeneration(prompt);
      rec.messages[idx] = {
        role: msg.role,
        kind: "photo",
        content: "[图片]",
        photoUrl: photoUrl,
        snapText: snapText,
        ts: msg.ts || Date.now(),
      };
      persistNarrative();
      showToast("图片已生成", "success");
      return true;
    } catch (err) {
      console.error(err);
      showToast((err && err.message) || "生图失败，请稍后重试", "error", 5200);
      return false;
    } finally {
      knockVisualImageGenerating = false;
      knockVisualImageGeneratingMsgIndex = -1;
      renderKnockScreen(slot || els.knockContentSlot(), { scrollToEnd: true });
    }
  }

  function declineKnockSnapGeneration(msgIndex) {
    const rec = getKnockChatRecordMutable();
    if (!rec) return false;
    const idx = Number(msgIndex);
    const msg = rec.messages[idx];
    if (!msg || msg.kind !== "snap") return false;
    msg.snapGenStatus = "declined";
    persistNarrative();
    return true;
  }

  function canRegenerateKnockPhotoInViewer() {
    if (!visualImageSettings.enabled || knockPhotoViewerMsgIndex < 0) return false;
    const rec = getKnockChatRecordMutable();
    if (!rec) return false;
    const msg = rec.messages[knockPhotoViewerMsgIndex];
    return !!(msg && msg.kind === "photo" && String(msg.snapText || "").trim());
  }

  function openKnockPhotoViewer(photoUrl, msgIndex) {
    const url = String(photoUrl || "").trim();
    if (!url) return;
    knockPhotoViewerUrl = url;
    const idx = Number(msgIndex);
    knockPhotoViewerMsgIndex = Number.isFinite(idx) && idx >= 0 ? idx : -1;
    renderKnockScreen(els.knockContentSlot());
  }

  function closeKnockPhotoViewer() {
    if (!knockPhotoViewerUrl) return;
    knockPhotoViewerUrl = null;
    knockPhotoViewerMsgIndex = -1;
    renderKnockScreen(els.knockContentSlot());
  }

  async function regenerateKnockPhotoAtIndex(rec, msgIndex, slot, opts) {
    opts = opts || {};
    if (!rec || !visualImageSettings.enabled) return false;
    const idx = Number(msgIndex);
    const msg = rec.messages[idx];
    if (!msg || msg.kind !== "photo") return false;
    const snapText = String(msg.snapText || "").trim();
    if (!snapText) {
      showToast("该图片无法重新生成（非 AI 生成）", "warning");
      return false;
    }
    if (!resolveVisualImageApiConfig()) {
      showToast("生图 API 未配置完整，请在设置 → 聊天发图 中填写站点、Key 与模型", "warning", 4200);
      return false;
    }
    const partnerChar = getKnockPartnerCharById(knockPartnerCharId);
    const userChar = getCharById(knockUserCharId);
    const intent = detectKnockSnapVisualIntent(snapText, opts.intent);
    const regenerateDirection = String(opts.regenerateDirection || "").trim();
    knockVisualImageGenerating = true;
    knockVisualImageGeneratingMsgIndex = idx;
    persistNarrative();
    renderKnockScreen(slot || els.knockContentSlot());
    try {
      const refKeys = [];
      if (intent === "selfie" && hasVisualRefImagesForAnalysis("appearance")) refKeys.push("appearance");
      if (intent !== "selfie" && hasVisualRefImagesForAnalysis("daily")) refKeys.push("daily");
      if (refKeys.length) {
        showToast("正在分析参考图并写入生图描述…", "info", 3600);
        await ensureVisualRefsAnalyzedForGeneration(refKeys);
      }
      showToast(
        intent === "selfie" ? "正在重新生成自拍，约需 1～3 分钟…" : "正在重新生成场景图，约需 1～3 分钟…",
        "info",
        5200
      );
      const prompt = await craftKnockVisualImagePrompt(intent, partnerChar, userChar, rec, [snapText], {
        regenerateDirection: regenerateDirection,
      });
      const selfieSceneOpts =
        intent === "selfie"
          ? buildKnockSelfieSceneOpts(partnerChar, userChar, rec, snapText, {
              regenerateDirection: regenerateDirection,
            })
          : null;
      const photoUrl =
        intent === "selfie"
          ? await callSelfieVisualImageGeneration(prompt, null, selfieSceneOpts)
          : await callSceneVisualImageGeneration(prompt);
      rec.messages[idx] = {
        role: msg.role,
        kind: "photo",
        content: "[图片]",
        photoUrl: photoUrl,
        snapText: snapText,
        ts: msg.ts || Date.now(),
      };
      if (knockPhotoViewerMsgIndex === idx) knockPhotoViewerUrl = photoUrl;
      persistNarrative();
      showToast("图片已重新生成", "success");
      return true;
    } catch (err) {
      console.error(err);
      showToast((err && err.message) || "生图失败，请稍后重试", "error", 5200);
      return false;
    } finally {
      knockVisualImageGenerating = false;
      knockVisualImageGeneratingMsgIndex = -1;
      renderKnockScreen(slot || els.knockContentSlot(), { scrollToEnd: true });
    }
  }

  async function saveKnockPhotoToAlbum(photoUrl) {
    const url = String(photoUrl || "").trim();
    if (!url) {
      showToast("无法保存：图片地址无效。", "error");
      return;
    }
    try {
      let blob = null;
      if (/^data:image\//i.test(url)) {
        blob = storyShareDataUrlToBlob(url);
      } else {
        const dataUrl = await fetchRemoteImageAsCompressedDataUrl(url);
        blob = storyShareDataUrlToBlob(dataUrl);
      }
      if (!blob) {
        showToast("无法保存图片。", "error");
        return;
      }
      await storyShareDeliverImageBlob(blob, "knock-chat-" + Date.now() + ".jpg");
    } catch (err) {
      console.error(err);
      showToast((err && err.message) || "保存失败，请重试。", "error");
    }
  }

