    youDogHolderModalMode = opts.mode === "settings" ? "settings" : "first";
    youDogHolderModalStep = "plot";
    youDogHolderModalPlotId = youDogPlotIds.length ? youDogPlotIds[0] : null;
    renderYouDogHolderModal();
    modal.hidden = false;
