  const FANWORK_JJWXC_CATEGORY_NONE = "__uncategorized__";
  const FANWORK_JJWXC_COMMISSION_HINT_MAX = 480;

  /** 小狗饭默认分区：同人文常见题材，首次选 CP 时预填，可编辑/删除 */
