  function buildPhoneHomeHtml() {
    const timeText = formatClockTime(new Date());
    const appsHtml = PHONE_HOME_APPS.map(function (app) {
      return (
        '<button type="button" class="phone-home__app" data-phone-app="' +
        escapeHtml(app.id) +
        '" aria-label="' +
        escapeHtml(app.name) +
        '">' +
        '<span class="phone-home__icon">' +
        phoneHomeAppIconSvg(app.id) +
        "</span>" +
        '<span class="phone-home__label">' +
        escapeHtml(app.name) +
        "</span>" +
        "</button>"
      );
    }).join("");
    return (
      '<div class="phone-home" aria-label="手机桌面">' +
      '<div class="phone-home__wallpaper" aria-hidden="true"></div>' +
      '<div class="phone-home__top">' +
      '<time class="phone-home__clock" datetime="' +
      escapeHtml(timeText) +
      '">' +
      escapeHtml(timeText) +
      "</time>" +
      '<p class="phone-home__owner">' +
      escapeHtml(getPhoneHolderOwnerText()) +
      "</p>" +
      "</div>" +
      '<div class="phone-home__dock">' +
      '<div class="phone-home__grid" role="list">' +
      appsHtml +
      "</div>" +
      "</div>" +
      "</div>"
    );
  }

  function renderPhoneView() {
    renderPhoneScreen(els.phoneContentSlot());
  }

  function closeStoryPhoneModal() {
    const modal = els.modalStoryPhone();
    if (!modal) return;
    modal.hidden = true;
    syncStoryPlaySideBtnActive();
  }

  function openStoryPhoneModal() {
    closeStoryFanworkModal();
    const modal = els.modalStoryPhone();
    if (!modal) return;
    modal.hidden = false;
    renderPhoneScreen(els.storyPhoneSlot());
    syncStoryPlaySideBtnActive();
  }

  function closeStoryFanworkModal() {
    const modal = els.modalStoryFanwork();
    if (!modal) return;
    modal.hidden = true;
    syncStoryPlaySideBtnActive();
  }

  function openStoryFanworkModal() {
    closeStoryPhoneModal();
    const modal = els.modalStoryFanwork();
    if (!modal) return;
    modal.hidden = false;
    const routePlot = getPlayModeStoryPlotFromRoute() || getCurrentStoryPlot();
    if (routePlot && fanworkPlotHasCp(routePlot)) {
      fanworkPlotId = routePlot.id;
      const sups = getFanworkPlotSupportingIds(routePlot);
      if (!fanworkCpPartnerId || sups.indexOf(fanworkCpPartnerId) < 0) {
        fanworkCpPartnerId = sups.length ? sups[0] : null;
      }
      schedulePersistNarrative();
    }
    renderFanworkScreen(els.storyFanworkSlot());
    syncStoryPlaySideBtnActive();
  }

  function resolveGenSlotId(slot, fallbackId) {
    return slot && slot.id ? slot.id : fallbackId || "phone-content-slot";
  }

  function navigateToFanworkView(slotId, patch) {
    let slot;
    if (String(slotId) === "story-fanwork-slot") {
      reopenStoryLayerIfHidden();
      openStoryFanworkModal();
      slot = document.getElementById("story-fanwork-slot");
    } else {
      dismissStoryLayerForOverview();
      openOverviewSubView("fanwork");
      slot = document.getElementById("fanwork-content-slot");
    }
    if (!slot) return;
    const nav = getFanworkNav(slot);
    Object.keys(patch || {}).forEach(function (k) {
      nav[k] = patch[k];
    });
    renderFanworkScreen(slot);
  }

  function navigateToPhoneView(slotId, patch) {
    let slot;
    if (String(slotId) === "story-phone-slot") {
      reopenStoryLayerIfHidden();
      openStoryPhoneModal();
      slot = document.getElementById("story-phone-slot");
    } else {
      dismissStoryLayerForOverview();
      openOverviewSubView("phone");
      slot = document.getElementById("phone-content-slot");
    }
    if (!slot) return;
    const nav = getPhoneNav(slot);
    Object.keys(patch || {}).forEach(function (k) {
      nav[k] = patch[k];
    });
    renderPhoneScreen(slot);
    if (nav.screen === "wechat-chat") scrollPhoneWechatThreadToEndDeferred(slot);
  }

  function buildGenCallOptsCore(kind, params) {
    params = params || {};
    const slot = params.slot;
    const slotId = resolveGenSlotId(
      slot,
      kind.indexOf("fanwork") >= 0
        ? "fanwork-content-slot"
        : kind.indexOf("collect") >= 0
          ? "collect-content-slot"
          : "phone-content-slot"
    );

    if (kind === "collect-pack") {
      return {
        genReady: {
          message: "收取已完成",
          navigate: function () {
            openOverviewSubView("collect");
          },
        },
      };
    }

    if (kind === "fanwork-jjwxc-chapter") {
      const hit = findFanworkJjwxcNovel(params.novelId);
      const chapter = hit
        ? (hit.novel.chapters || []).find(function (c) {
            return c && c.id === params.chapterId;
          })
        : null;
      const chapterTitle = chapter ? String(chapter.title || "").trim() || "章节" : "章节";
      const novelTitle = hit ? String(hit.novel.title || "").trim() : "";
      const label = novelTitle ? "《" + novelTitle + "》" + chapterTitle : chapterTitle;
      return {
        genReady: {
          message: label + " 已生成好",
          navigate: function () {
            navigateToFanworkView(slotId, {
              screen: "jjwxc-chapter",
              jjwxcNovelId: params.novelId,
              jjwxcChapterId: params.chapterId,
            });
          },
        },
      };
    }

    if (kind === "fanwork-jjwxc-novel") {
      const hit = findFanworkJjwxcNovel(params.novelId);
      const title = hit ? String(hit.novel.title || "").trim() || "同人文" : "同人文";
      return {
        genReady: {
          message: "《" + title + "》已生成好",
          navigate: function () {
            navigateToFanworkView(slotId, {
              screen: "jjwxc-novel",
              jjwxcNovelId: params.novelId,
              jjwxcChapterId: null,
            });
          },
        },
      };
    }

    if (kind === "fanwork-jjwxc-catalog") {
      return {
        genReady: {
          message: "小狗饭书单已生成好",
          navigate: function () {
            navigateToFanworkView(slotId, { screen: "jjwxc", jjwxcNovelId: null, jjwxcChapterId: null });
          },
        },
      };
    }

    if (kind === "fanwork-jjwxc-append") {
      const hit = findFanworkJjwxcNovel(params.novelId);
      const title = hit ? String(hit.novel.title || "").trim() || "同人文" : "同人文";
      const chTitle = params.chapterTitle ? String(params.chapterTitle).trim() : "新章节";
      return {
        genReady: {
          message: "《" + title + "》" + chTitle + " 已生成好",
          navigate: function () {
            navigateToFanworkView(slotId, {
              screen: "jjwxc-novel",
              jjwxcNovelId: params.novelId,
              jjwxcChapterId: null,
            });
          },
        },
      };
    }

    if (kind === "fanwork-jjwxc-regen") {
      const hit = findFanworkJjwxcNovel(params.novelId);
      const chapter = hit
        ? (hit.novel.chapters || []).find(function (c) {
            return c && c.id === params.chapterId;
          })
        : null;
      const chapterTitle = chapter ? String(chapter.title || "").trim() || "最新章" : "最新章";
      const novelTitle = hit ? String(hit.novel.title || "").trim() : "";
      const label = novelTitle ? "《" + novelTitle + "》" + chapterTitle : chapterTitle;
      return {
        genReady: {
          message: label + " 已重新生成",
          navigate: function () {
            navigateToFanworkView(slotId, {
              screen: "jjwxc-chapter",
              jjwxcNovelId: params.novelId,
              jjwxcChapterId: params.chapterId,
            });
          },
        },
      };
    }

    if (kind === "phone-jjwxc-chapter") {
      const hit = findPhoneJjwxcNovel(params.novelId);
      const title = hit ? String(hit.novel.title || "").trim() || "作品" : "作品";
      return {
        genReady: {
          message: "《" + title + "》目录已更新",
          navigate: function () {
            navigateToPhoneView(slotId, {
              screen: "jjwxc-novel",
              jjwxcNovelId: params.novelId,
              jjwxcChapterId: null,
            });
          },
        },
      };
    }

    if (kind === "phone-jjwxc-novel") {
      const hit = findPhoneJjwxcNovel(params.novelId);
      const title = hit ? String(hit.novel.title || "").trim() || "作品" : "作品";
      return {
        genReady: {
          message: "《" + title + "》已生成好",
          navigate: function () {
            navigateToPhoneView(slotId, {
              screen: "jjwxc-novel",
              jjwxcNovelId: params.novelId,
              jjwxcChapterId: null,
            });
          },
        },
      };
    }

    if (kind === "phone-jjwxc-catalog") {
      return {
        genReady: {
          message: "晋江书单已生成好",
          navigate: function () {
            navigateToPhoneView(slotId, { screen: "jjwxc", jjwxcNovelId: null, jjwxcChapterId: null });
          },
        },
      };
    }

    if (kind === "phone-wechat-chat") {
      const chat = params.chat;
      const chatName = chat ? String(chat.name || "").trim() || "微信会话" : "微信会话";
      return {
        genReady: {
          message: "「" + chatName + "」有新消息",
          navigate: function () {
            navigateToPhoneView(slotId, { screen: "wechat-chat", chatId: params.chatId });
          },
        },
      };
    }

    if (kind === "phone-wechat-list") {
      return {
        genReady: {
          message: "微信内容已生成好",
          navigate: function () {
            navigateToPhoneView(slotId, { screen: "wechat-list", chatId: null });
          },
        },
      };
    }

    const phoneScreenLabels = {
      "phone-moments": "朋友圈内容已生成好",
      "phone-music": "音乐列表已生成好",
      "phone-album": "相册内容已生成好",
      "phone-forum-list": "论坛帖子已生成好",
      "phone-forum-section": "本分区帖子已生成好",
      "phone-forum-post": "论坛帖子详情已生成好",
      "phone-browser": "浏览器内容已生成好",
      "phone-browser-section": "本分类浏览记录已生成好",
      "phone-memo": "备忘录已生成好",
      "phone-memo-section": "本分类备忘录已生成好",
      "phone-diary": "日记已生成好",
      "phone-bill": "账单已生成好",
      "phone-weread": "微信读书已生成好",
    };

    if (kind === "phone-forum-post" && params.postId) {
      const postId = params.postId;
      return {
        genReady: {
          message: phoneScreenLabels[kind],
          navigate: function () {
            navigateToPhoneView(slotId, { screen: "forum-post", forumPostId: postId });
          },
        },
      };
    }

    if (kind === "phone-forum-section" && params.sectionId) {
      const sectionId = params.sectionId;
      return {
        genReady: {
          message: phoneScreenLabels[kind],
          navigate: function () {
            navigateToPhoneView(slotId, { screen: "forum", forumSectionId: sectionId });
          },
        },
      };
    }

    if (phoneScreenLabels[kind]) {
      let screen = kind.replace("phone-", "");
      if (screen === "forum-list" || screen === "forum-section") screen = "forum";
      if (screen === "browser-section") screen = "browser";
      const patch = { screen: screen };
      if (kind === "phone-weread" && params.bookId) {
        patch.screen = "weread-book";
        patch.wereadBookId = params.bookId;
      }
      return {
        genReady: {
          message: phoneScreenLabels[kind],
          navigate: function () {
            navigateToPhoneView(slotId, patch);
          },
        },
      };
    }

    if (kind === "story-play") {
      const plot = params.plot;
      const title = plot ? String(plot.title || "").trim() || "剧情" : "剧情";
      return {
        genReady: {
          message: "《" + title + "》有新剧情",
          navigate: function () {
            if (!plot) return;
            openStoryLayer(plot, "play");
            requestAnimationFrame(function () {
              requestAnimationFrame(function () {
                scrollStoryPlayToLatest(false);
              });
            });
          },
        },
      };
    }

    if (kind === "story-setup") {
      const plot = params.plot;
      const title = plot ? String(plot.title || "").trim() || "剧情" : "剧情";
      return {
        genReady: {
          message: "《" + title + "》开场已生成好",
          navigate: function () {
            if (plot) openStoryLayer(plot, "setup");
          },
        },
      };
    }

    return {};
  }

  function isBackgroundGenCallKind(kind) {
    const k = String(kind || "");
    if (!k || k.indexOf("story") === 0) return false;
    return (
      k.indexOf("knock") === 0 ||
      k.indexOf("collect") === 0 ||
      k.indexOf("phone") === 0 ||
      k.indexOf("fanwork") === 0 ||
      k.indexOf("radio") === 0 ||
      k.indexOf("todo") === 0 ||
      k.indexOf("you-dog") === 0
    );
  }

  function withGenCallRouting(kind, payload) {
    return payload && typeof payload === "object" ? payload : {};
  }

  function buildGenCallOpts(kind, params) {
    return withGenCallRouting(kind, buildGenCallOptsCore(kind, params));
  }

  function truncateStorySearchText(text, maxLen) {
    const s = String(text || "").trim();
    if (!s) return "";
    if (s.length <= maxLen) return s;
    return s.slice(0, Math.max(0, maxLen - 1)) + "…";
  }

  /** 以关键词在正文中的位置为中心截取片段，并输出可放入 innerHTML 的安全字符串（关键词加粗） */
  function buildStorySearchHitHtml(lineText, keyword) {
    const raw = String(lineText || "");
    const q = String(keyword || "").trim();
    if (!q) return escapeHtml(truncateStorySearchText(raw, 86));
    const lower = raw.toLowerCase();
    const qi = lower.indexOf(q.toLowerCase());
    if (qi < 0) return escapeHtml(truncateStorySearchText(raw, 86));
    const matchLen = q.length;
    const beforeN = 26;
    const afterN = 34;
    let start = Math.max(0, qi - beforeN);
    let end = Math.min(raw.length, qi + matchLen + afterN);
    const leftEll = start > 0 ? "…" : "";
    const rightEll = end < raw.length ? "…" : "";
    const before = raw.slice(start, qi);
    const match = raw.slice(qi, qi + matchLen);
    const after = raw.slice(qi + matchLen, end);
    return (
      leftEll +
      escapeHtml(before) +
      '<strong class="story-search-kw">' +
      escapeHtml(match) +
      "</strong>" +
      escapeHtml(after) +
      rightEll
    );
  }

  function buildStorySearchContextHtml(itemText, keyword, prevText, nextText) {
    const parts = [];
    const prev = String(prevText || "").trim();
    if (prev) {
      const tail = prev.length > 16 ? "…" + escapeHtml(prev.slice(-16)) : escapeHtml(prev);
      parts.push('<span class="story-search-item__adj">' + tail + "</span>");
    }
    parts.push('<span class="story-search-item__hit">' + buildStorySearchHitHtml(itemText, keyword) + "</span>");
    const next = String(nextText || "").trim();
    if (next) {
      const head = next.length > 16 ? escapeHtml(next.slice(0, 16)) + "…" : escapeHtml(next);
      parts.push('<span class="story-search-item__adj">' + head + "</span>");
    }
    return parts.join('<span class="story-search-item__sep" aria-hidden="true"> · </span>');
  }

  function buildStorySearchMatches(plot, keyword) {
    const qLower = String(keyword || "").trim().toLowerCase();
    if (!plot || !qLower) return [];
    const keywordRaw = String(keyword || "").trim();
    ensureStoryLineIds(plot);
    const flat = [];
    (plot.playTurns || []).forEach(function (turn, turnIndex) {
      (turn && turn.lines ? turn.lines : []).forEach(function (line, lineIndex) {
        if (!line) return;
        const lineText = String(line.text || "").trim();
        if (!lineText) return;
        flat.push({
          lineId: String(line.id || "").trim(),
          turnIndex: turnIndex,
          lineIndex: lineIndex,
          text: lineText,
        });
      });
    });
    const out = [];
    flat.forEach(function (item, idx) {
      if (item.text.toLowerCase().indexOf(qLower) < 0) return;
      const prev = idx > 0 ? flat[idx - 1].text : "";
      const next = idx < flat.length - 1 ? flat[idx + 1].text : "";
      out.push({
        lineId: item.lineId,
        meta: "第 " + (item.turnIndex + 1) + " 轮",
        contextHtml: buildStorySearchContextHtml(item.text, keywordRaw, prev, next),
      });
    });
    return out.slice(0, 80);
  }

  function renderStorySearchList(plot, initialKeywordFromInput) {
    const list = els.storySearchList();
    if (!list) return;
    const input = els.storySearchInput();
    const q = input && typeof input.value === "string" ? input.value : String(initialKeywordFromInput || "").trim();
    const qTrim = String(q || "").trim();
    list.innerHTML = "";
    if (!qTrim) {
      list.innerHTML = '<div class="story-search-empty">输入关键词后，将在当前剧情中搜索并显示上下文。</div>';
      return;
    }
    const matches = buildStorySearchMatches(plot, qTrim);
    if (!matches.length) {
      list.innerHTML = '<div class="story-search-empty">没有找到相关剧情条目，换个关键词试试。</div>';
      return;
    }
    matches.forEach(function (m) {
      const btn = document.createElement("button");
      btn.type = "button";
      btn.className = "story-search-item";
      btn.setAttribute("data-story-search-line", m.lineId);
      btn.innerHTML =
        '<div class="story-search-item__meta">' +
        escapeHtml(m.meta) +
        '</div><div class="story-search-item__ctx">' +
        m.contextHtml +
        "</div>";
      list.appendChild(btn);
    });
  }

  function jumpToStoryLineById(plot, lineId) {
    if (!plot || !lineId) return;
    renderStoryPlay(plot);
    requestAnimationFrame(function () {
      const selector = '[data-story-line-id="' + String(lineId) + '"]';
      const target = document.querySelector(selector);
      if (!target) {
        showToast("没有定位到该剧情条目。", "info");
        return;
      }
      target.scrollIntoView({ behavior: "smooth", block: "center", inline: "nearest" });
      target.classList.add("story-search-hit");
      if (storySearchHighlightTimer) clearTimeout(storySearchHighlightTimer);
      storySearchHighlightTimer = setTimeout(function () {
        storySearchHighlightTimer = null;
        target.classList.remove("story-search-hit");
      }, 1800);
    });
  }

  function openStorySearchModal(plot) {
    if (!plot) return;
    const modal = els.modalStorySearch();
    const input = els.storySearchInput();
    if (!modal || !input) return;
    input.value = "";
    renderStorySearchList(plot, "");
    modal.hidden = false;
    requestAnimationFrame(function () {
      input.focus();
      input.select();
    });
  }

  function renderStorySummaryTags(p) {
    const wrap = document.getElementById("story-summary-tags");
    if (!wrap) return;
    const tagsNow = Array.isArray(p.summaryTags)
      ? p.summaryTags.map(function (t) {
        return String(t == null ? "" : t).trim();
      }).filter(Boolean)
      : [];
    if (tagsNow.length === 0) {
      const fallback = deriveStoryTagsFromSections(
        p.eraBackground,
        composeStoryIdentityText(p.characterIdentitySelf, p.characterIdentityOthers, p.characterIdentities),
        p.storyStart
      );
      if (fallback.length) p.summaryTags = fallback;
    }
    wrap.innerHTML = "";
    const tags = Array.isArray(p.summaryTags) ? p.summaryTags : [];
    const n = 3;
    for (let i = 0; i < n; i++) {
      const raw = tags[i];
      const t = raw != null ? String(raw).trim() : "";
      const span = document.createElement("span");
      span.className =
        "story-tag-chip" + (t ? " story-tag-chip--filled" : " story-tag-chip--empty");
      span.textContent = t || "\u00A0";
      wrap.appendChild(span);
    }
  }

  function splitSetupDisplayParagraphs(text) {
    const s = String(text || "").trim();
    if (!s) return [];
    const byBlank = s
      .split(/\n\s*\n+/)
      .map(function (x) {
        return x.trim();
      })
      .filter(Boolean);
    if (byBlank.length > 1) return byBlank;
    return s
      .split(/\n+/)
      .map(function (x) {
        return x.trim();
      })
      .filter(Boolean);
  }

  function updateStorySetupViews(p) {
    if (!p || storySetupEditing) return;
    const rows = [
      { viewId: "story-field-era-view", text: p.eraBackground },
      { viewId: "story-field-self-view", text: p.characterIdentitySelf },
      { viewId: "story-field-others-view", text: p.characterIdentityOthers },
      { viewId: "story-field-start-view", text: p.storyStart },
    ];
    rows.forEach(function (row) {
      const view = document.getElementById(row.viewId);
      if (!view) return;
      const ph = view.getAttribute("data-placeholder") || "";
      view.innerHTML = "";
      const parts =
        row.viewId === "story-field-self-view" || row.viewId === "story-field-others-view"
          ? splitStoryIdentitiesForBlocks(row.text, p)
          : splitSetupDisplayParagraphs(row.text);
      if (parts.length === 0) {
        const emptyP = document.createElement("p");
        emptyP.className = "story-setup-card__para story-setup-card__para--placeholder";
        emptyP.textContent = ph;
        view.appendChild(emptyP);
        return;
      }
      parts.forEach(function (chunk) {
        const para = document.createElement("p");
        para.className = "story-setup-card__para";
        para.textContent = chunk;
        view.appendChild(para);
      });
    });
  }

  function syncStorySetupFieldVisibility() {
    const editing = storySetupEditing;
    [
      ["story-field-era", "story-field-era-view"],
      ["story-field-self", "story-field-self-view"],
      ["story-field-others", "story-field-others-view"],
      ["story-field-start", "story-field-start-view"],
    ].forEach(function (pair) {
      const ta = document.getElementById(pair[0]);
      const v = document.getElementById(pair[1]);
      if (ta) {
        ta.readOnly = !editing;
        ta.hidden = !editing;
      }
      if (v) {
        v.hidden = editing;
        v.setAttribute("aria-hidden", editing ? "true" : "false");
      }
    });
  }

  function renderStorySetup(p) {
    const era = document.getElementById("story-field-era");
    const self = document.getElementById("story-field-self");
    const others = document.getElementById("story-field-others");
    const st = document.getElementById("story-field-start");
    if (era) era.value = p.eraBackground || "";
    if (self) self.value = p.characterIdentitySelf || "";
    if (others) others.value = p.characterIdentityOthers || "";
    if (st) st.value = p.storyStart || "";
    updateStorySetupViews(p);
    syncStorySetupFieldVisibility();
    if (storySetupEditing) autoResizeStorySetupInputs();
    renderStorySummaryTags(p);
  }

  function syncPlotFromSetupFields(p) {
    const era = document.getElementById("story-field-era");
    const self = document.getElementById("story-field-self");
    const others = document.getElementById("story-field-others");
    const st = document.getElementById("story-field-start");
    if (era) p.eraBackground = era.value;
    if (self) p.characterIdentitySelf = self.value;
    if (others) p.characterIdentityOthers = others.value;
    p.characterIdentities = composeStoryIdentityText(p.characterIdentitySelf, p.characterIdentityOthers, p.characterIdentities);
    if (st) p.storyStart = st.value;
    if (!p.playIntro || typeof p.playIntro !== "object") {
      p.playIntro = { era: "", identities: "", myImage: "", otherRoles: "", opening: "" };
    }
    p.playIntro.era = String(p.eraBackground || "");
    p.playIntro.myImage = String(p.characterIdentitySelf || "");
    p.playIntro.otherRoles = String(p.characterIdentityOthers || "");
    p.playIntro.identities = String(p.characterIdentities || "");
    p.playIntro.opening = String(p.storyStart || "");
  }

  function setStorySetupEditing(on) {
    const panel = document.getElementById("story-panel-setup");
    const cur = plots.find(function (x) {
      return x.id === lastStoryPlotId;
    });
    if (storySetupEditing && !on && cur) syncPlotFromSetupFields(cur);
    storySetupEditing = on;
    if (panel) panel.classList.toggle("story-setup--editing", on);
    const editBtn = document.getElementById("story-btn-edit");
    if (editBtn) editBtn.textContent = on ? "完成" : "编辑";
    if (cur) {
      updateStorySetupViews(cur);
    }
    syncStorySetupFieldVisibility();
    if (on) autoResizeStorySetupInputs();
  }

  function extractStoryTagsLine(rawText) {
    const text = String(rawText || "");
    const line = text.match(
      /(?:^|\n)\s*(?:[*#>\s]*)(?:概要标签|摘要标签|剧情标签|标签|关键词)\s*[：:]\s*([^\n]+)/im
    );
    return line ? String(line[1] || "").trim() : "";
  }

  function extractPlotTitleLine(rawText) {
    const text = String(rawText || "");
    const line = text.match(
      /(?:^|\n)\s*(?:[*#>\s]*)(?:剧情标题|剧情题目|列表标题)\s*[：:]\s*([^\n]+)/im
    );
    return line ? String(line[1] || "").trim() : "";
  }

  function sanitizeBriefPlotTitle(raw) {
    let s = String(raw || "").trim();
    s = s.replace(/^标题\s*[：:]\s*/i, "").trim();
    s = s.replace(/^["'「『]|["'」』]+$/g, "").trim();
    s = s.replace(/^《\s*/, "").replace(/\s*》$/, "").trim();
    const maxTitleChars = 28;
    if (storyBriefCharCount(s) > maxTitleChars) s = truncateStoryBriefText(s, maxTitleChars, false);
    if (storyBriefCharCount(s) < 2) return "";
    if (
      /^(新剧情|未命名|无标题|剧情$|叙事$|^开始$|第[一二三四五六七八九十\d]+章|一段关于|关于.+的故事|某某的奇妙)/i.test(
        s
      )
    )
      return "";
    if (/[，,、；;：:]/.test(s)) return "";
    return s;
  }

  function normalizeStoryTags(rawLine) {
    return String(rawLine || "")
      .split(/[、,，|/]/)
      .map(function (s) {
        return s.trim();
      })
      .filter(Boolean)
      .slice(0, 3);
  }

  function deriveStoryTagsFromSections(eraText, identText, startText) {
    const seeds = [eraText, identText, startText];
    const list = [];
    seeds.forEach(function (text) {
      const first = String(text || "")
        .split(/[。！？!?\n]/)[0]
        .split(/[，,；;、]/)
        .map(function (s) {
          return s.trim();
        })
        .filter(Boolean);
      first.forEach(function (chunk) {
        const normalized = chunk.replace(/[“”"'《》【】（）()]/g, "").trim();
        if (!normalized) return;
        const short = normalized.length > 10 ? normalized.slice(0, 10) : normalized;
        if (short.length >= 2) list.push(short);
      });
    });
    return Array.from(new Set(list)).slice(0, 3);
  }

  function normalizeStoryBriefRawText(rawText) {
    let t = String(rawText || "").trim();
    t = t.replace(/\uFEFF/g, "");
    t = t.replace(/\r\n/g, "\n").replace(/\r/g, "\n");
    if (/^```/.test(t)) {
      t = t.replace(/^```(?:[\w-]*\n)?/, "");
      t = t.replace(/\n```\s*$/, "");
    }
    return t.trim();
  }

  /** 行首小节标题：允许 #、**、>、空白 */
  function storyBriefHeaderLineRe() {
    return "^(?:\\s|[>*#\\-\\s])*\\*{0,2}\\s*";
  }

  function parseStoryBriefResponse(rawText) {
    const text = normalizeStoryBriefRawText(rawText);
    const head = storyBriefHeaderLineRe();
    const eraMatch = text.match(
      new RegExp(
        "(?:" +
          head +
          ")(?:时代与场景|时代背景|背景设定|时代场景)\\s*\\*{0,2}\\s*[：:]\\s*([\\s\\S]+?)(?=" +
          head +
          "(?:角色身份|人物身份|角色设定)\\s*\\*{0,2}\\s*[：:]|$)",
        "im"
      )
    );
    const selfMatch = text.match(
      new RegExp(
        "(?:" +
          head +
          ")(?:我的形象|主角形象|我的身份|角色身份|人物身份|角色设定)\\s*\\*{0,2}\\s*[：:]\\s*([\\s\\S]+?)(?=" +
          head +
          "(?:其他角色|配角身份|他人身份|故事开端|故事开篇|开端|开场)\\s*\\*{0,2}\\s*[：:]|$)",
        "im"
      )
    );
    const othersMatch = text.match(
      new RegExp(
        "(?:" +
          head +
          ")(?:其他角色|配角身份|他人身份)\\s*\\*{0,2}\\s*[：:]\\s*([\\s\\S]+?)(?=" +
          head +
          "(?:故事开端|故事开篇|开端|开场)\\s*\\*{0,2}\\s*[：:]|$)",
        "im"
      )
    );
    const startMatch = text.match(
      new RegExp(
        "(?:" +
          head +
          ")(?:故事开端|故事开篇|开端|开场)\\s*\\*{0,2}\\s*[：:]\\s*([\\s\\S]+?)(?=" +
          head +
          "(?:概要标签|摘要标签|剧情标签|标签|关键词)\\s*\\*{0,2}\\s*[：:]|$)",
        "im"
      )
    );
    let eraText = eraMatch ? String(eraMatch[1] || "").trim() : "";
    let selfText = selfMatch ? String(selfMatch[1] || "").trim() : "";
    let othersText = othersMatch ? String(othersMatch[1] || "").trim() : "";
    let startText = startMatch ? String(startMatch[1] || "").trim() : "";
    let tagLine = extractStoryTagsLine(text);
    let tags = normalizeStoryTags(tagLine);
    let plotTitle = extractPlotTitleLine(text);

    if (!eraText || !selfText || !othersText || !startText || tags.length === 0 || !plotTitle) {
      const fb = parseStoryBriefResponseLineFallback(text);
      if (!eraText && fb.eraText) eraText = fb.eraText;
      if (!selfText && fb.selfText) selfText = fb.selfText;
      if (!othersText && fb.othersText) othersText = fb.othersText;
      if ((!selfText || !othersText) && fb.identText) {
        const mixed = String(fb.identText || "").trim();
        if (!selfText) selfText = mixed;
      }
      if (!startText && fb.startText) startText = fb.startText;
      if (tags.length === 0 && fb.tags.length) tags = fb.tags;
      if (!tagLine && fb.tagLineRaw) tagLine = fb.tagLineRaw;
      if (!plotTitle && fb.plotTitle) plotTitle = fb.plotTitle;
    }

    return {
      eraText: eraText,
      selfText: selfText,
      othersText: othersText,
      startText: startText,
      tags: tags,
      plotTitle: plotTitle,
    };
  }

  /** 按行扫描小节标题，兼容无 Markdown、或标题与正文同一行 */
  function parseStoryBriefResponseLineFallback(text) {
    const lines = String(text || "").split("\n");
    const stripMd = function (s) {
      return String(s || "")
        .replace(/^\s*#+\s*/, "")
        .replace(/^\s*>\s*/, "")
        .replace(/^\*{1,2}\s*/, "")
        .replace(/\s*\*{1,2}\s*$/, "")
        .trim();
    };
    const classify = function (line) {
      const L = stripMd(line);
      const m = L.match(
        /^(时代与场景|时代背景|背景设定|时代场景|我的形象|主角形象|我的身份|其他角色|配角身份|他人身份|角色身份|人物身份|角色设定|故事开端|故事开篇|开端|开场|概要标签|摘要标签|剧情标签|标签|关键词|剧情标题|剧情题目|列表标题)\s*[：:]\s*(.*)$/i
      );
      if (!m) return null;
      const titlePart = String(m[1] || "").trim();
      const rest = String(m[2] != null ? m[2] : "").trim();
      let key = null;
      if (/时代与场景|时代背景|背景设定|时代场景/i.test(titlePart)) key = "era";
      else if (/我的形象|主角形象|我的身份/i.test(titlePart)) key = "self";
      else if (/其他角色|配角身份|他人身份/i.test(titlePart)) key = "others";
      else if (/角色身份|人物身份|角色设定/i.test(titlePart)) key = "ident";
      else if (/故事开端|故事开篇|开端|开场/i.test(titlePart)) key = "start";
      else if (/概要标签|摘要标签|剧情标签|^标签$/i.test(titlePart) || /^关键词$/i.test(titlePart)) key = "tags";
      else if (/剧情标题|剧情题目|列表标题/i.test(titlePart)) key = "title";
      return key ? { key: key, sameLineRest: rest } : null;
    };

    const buf = { era: [], self: [], others: [], ident: [], start: [] };
    let tagLineRaw = "";
    let titleLineRaw = "";
    let cur = null;
    for (let i = 0; i < lines.length; i++) {
      const rawLine = lines[i];
      const info = classify(rawLine);
      if (info) {
        cur = info.key;
        if (info.key === "tags") {
          tagLineRaw = info.sameLineRest || extractStoryTagsLine(rawLine) || "";
          cur = null;
          continue;
        }
        if (info.key === "title") {
          titleLineRaw = info.sameLineRest || extractPlotTitleLine(rawLine) || "";
          cur = null;
          continue;
        }
        if (info.sameLineRest) buf[info.key].push(info.sameLineRest);
        continue;
      }
      if (cur && cur !== "tags" && cur !== "title") buf[cur].push(rawLine);
    }
    return {
      eraText: buf.era.join("\n").trim(),
      selfText: buf.self.join("\n").trim(),
      othersText: buf.others.join("\n").trim(),
      identText: buf.ident.join("\n").trim(),
      startText: buf.start.join("\n").trim(),
      tags: normalizeStoryTags(tagLineRaw),
      tagLineRaw: tagLineRaw,
      plotTitle: String(titleLineRaw || "").trim(),
    };
  }

  function autoResizeStorySetupInputs() {
    if (!storySetupEditing) return;
    ["story-field-era", "story-field-self", "story-field-others", "story-field-start"].forEach(function (id) {
      const el = document.getElementById(id);
      if (!el || el.hidden) return;
      el.style.height = "auto";
      const minH = 40;
      const next = Math.max(minH, el.scrollHeight);
      el.style.height = next + "px";
    });
  }

  async function regenerateStoryBrief(plot, opts) {
    opts = opts || {};
    if (!opts.skipPlayGuard && plotHasRecordedInteractivePlay(plot)) {
      const ok = await showConfirm(
        "本条剧情已有正文回合。重新生成将只更新「时代与场景 / 形象 / 故事开端」等概要，不会清空已玩进度；新概要可能与现有正文不一致。是否继续？\n\n若需从零开局，请新建剧情。",
        "重新生成概要"
      );
      if (!ok) return;
    }
    const protagonist = getCharById(plot.protagonistId);
    const supporting = (plot.supportingIds || [])
      .map(function (id) {
        return getCharById(id);
      })
      .filter(Boolean);
    const supportingMain = supporting.filter(function (c) {
      return String(c.categoryId || "").trim() !== CHAR_CATEGORY_EXTRA_ID;
    });
    const supportingExtra = supporting.filter(function (c) {
      return String(c.categoryId || "").trim() === CHAR_CATEGORY_EXTRA_ID;
    });
    const wbs = getWorldBooksForPlot(plot);

    const povLine = normalizeNarrativePov(plot && plot.pov ? plot.pov : "第三人称");
    const povConstraintOpen = buildPovHardConstraint(povLine, protagonist && protagonist.name ? protagonist.name : "");
    const systemPrompt =
      "你是一个专业的叙事AI助手，擅长沉浸式剧情与长篇小说式开篇。请根据提供的信息一次性写完整套「剧情开场概要」，包含下列六个小节，缺一不可。\n" +
      "1. 时代与场景：写清时间、地点、氛围、关键环境细节；**允许多段**，段与段之间空一行；以讲清楚为准，**不要为了压短而删掉必要信息**。\n" +
      "2. 我的形象：只写主视角角色一段，必须以「姓名，」开头。**硬性上限**：整段从首字到句末标点总共不得超过 " +
      STORY_BRIEF_IDENTITY_EACH_HINT_CHARS +
      " 个字符（每个汉字、字母、数字、标点、空格均计 1；与程序截断规则一致）。不得超过此数；必须在不超限的前提下写成**完整一句**并以「。」收束；若篇幅将超，应主动删繁就简、提前收束，**禁止**写到一半戛然而止。\n" +
      "3. 其他角色：优先覆盖「主要角色」名单中的每位角色；每位单独一段，每段以「姓名，」开头；**每位**同样不得超过 " +
      STORY_BRIEF_IDENTITY_EACH_HINT_CHARS +
      " 字符，须为完整一句并以「。」收束；段与段之间空一行。若提供了「配角与NPC」名单，仅在开场确有必要时再简短提及，可不逐一覆盖，且总篇幅不得喧宾夺主。\n" +
      "4. 故事开端：开场动作、对峙或悬念，画面感强；**允许多段**（段间空一行）；把冲突/处境立住即可，**不要人为压缩成一句**。\n" +
      "5. 概要标签：恰好三个短语，概括题材/场景/基调，用顿号「、」分隔。\n" +
      "6. 剧情标题：必须放在**全篇最后一行**，格式「剧情标题：……」；要像**出版小说的书名**——短、好记，带意象或关系张力（地名、物候、身体感、对峙之一即可），4～16 个汉字为佳（最多不超过 18 字）；不要书名号《》与引号；标题内不要用逗号、顿号、分号、冒号；不要写成剧情摘要长句。**禁止**空泛词：新剧情、未命名、开始、第X章、某某的奇妙一天、一段关于……的故事。\n\n" +
      "要求：\n" +
      "- 用中文；风格贴合题材与世界观\n" +
      "- " + povConstraintOpen + "\n" +
      "- 五个小节都要写满（其中「我的形象」「其他角色」必须在各自字数硬上限内写完整句）\n" +
      "- 必须按下列行首标题输出（单独成行，标题后用中文冒号「：」）；小节正文内部如需分段，仅用空行，不要加「1.」等编号小标题\n" +
      "- 故事开端可多行多段，直到「概要标签：」\n" +
      "- **最后一行只能是「剧情标题：……」**（该行不要再夹杂其他小节）\n" +
      "- 概要标签行：恰好三个短语，勿加序号\n" +
      "- 【文风与修辞（六个小节全文贯彻）】" +
      STORY_PROSE_STYLE_GUIDE +
      "\n\n若用户消息开头提供了「世界书」条目：须在六个小节中贯彻其中的禁令、硬性规则及文风世界观，并与下方人物信息对齐；若有冲突，按下方【采信层级】裁决。" +
      "\n\n" +
      STORY_PERSONA_PRIORITY_GUIDE;

    const themeSpecific = plotHasSpecificTheme(plot);
    let rosterMainSuffix = "";
    if (protagonist) {
      if (themeSpecific) {
        const h = buildCharAppearancePersonaHint(protagonist, 200);
        if (h) rosterMainSuffix = "，可参考人设（外貌气质与性格等）：" + h;
      } else if (protagonist.style) {
        rosterMainSuffix = "，可参考外貌及性格：" + String(protagonist.style).trim().slice(0, 200);
      }
    }
    const rosterMain = (protagonist ? protagonist.name : "未知") + rosterMainSuffix;
    const rosterOthersMain = supportingMain.length
      ? supportingMain
          .map(function (c) {
            const hintRaw = themeSpecific
              ? buildCharAppearancePersonaHint(c, 120)
              : String(c.style || "").trim();
            const hint = hintRaw ? String(hintRaw).trim().slice(0, 120) : "";
            return c.name + (hint ? "（" + hint + "）" : "");
          })
          .join("，")
      : "无";
    const rosterOthersExtra = supportingExtra.length
      ? supportingExtra
          .map(function (c) {
            const hintRaw = themeSpecific
              ? buildCharAppearancePersonaHint(c, 120)
              : String(c.style || "").trim();
            const hint = hintRaw ? String(hintRaw).trim().slice(0, 120) : "";
            return c.name + (hint ? "（" + hint + "）" : "");
          })
          .join("，")
      : "无";
    const wbBlockOpen = formatWorldBooksPromptBlock(wbs);
    const userPrompt =
      (wbBlockOpen ? wbBlockOpen + "\n" : "") +
      "题材方向：" +
      (plot.theme || "无特定题材") +
      "\n\n【角色名单（仅供你把握人物；写入「我的形象 / 其他角色」小节时不要写「主角」「参与角色」等词，每段用「姓名，」起笔）】\n" +
      "主视角：" + rosterMain +
      "\n主要角色：" + rosterOthersMain +
      "\n配角与NPC（按需调用，可不展开）：" + rosterOthersExtra +
      "\n\n输出：严格按 system 规定的六个小节标题依次成文（时代与场景→我的形象→其他角色→故事开端→概要标签→剧情标题）；最后一行仅限「剧情标题：…」，小节内的字数与格式要求以 system 为准。";

    const messages = [
      { role: "system", content: systemPrompt },
      { role: "user", content: userPrompt },
    ];

    function buildStoryBriefFieldsFromParsed(parsed) {
      let eraText = normalizeStoryBriefSectionText(parsed.eraText);
      const parsedIdentMerged = composeStoryIdentityText(parsed.selfText, parsed.othersText, parsed.identText);
      let identText = finalizeStoryBriefIdentityParagraphs(parsedIdentMerged, plot);
      identText = reorderIdentityParagraphsByRoster(identText, plot);
      let identitySections = splitStoryIdentitySections(identText, plot);
      let selfText = truncateStoryBriefIdentityParagraph(
        identitySections.selfText,
        STORY_BRIEF_IDENTITY_EACH_HINT_CHARS
      );
      const othersParts = splitStoryIdentitiesForBlocks(identitySections.othersText, plot).map(function (x) {
        return truncateStoryBriefIdentityParagraph(x, STORY_BRIEF_IDENTITY_EACH_HINT_CHARS);
      });
      let othersText = othersParts.join("\n\n").trim();
      identText = composeStoryIdentityText(selfText, othersText, identText);
      let startText = normalizeStoryBriefSectionText(parsed.startText);
      const plotTitleSan = sanitizeBriefPlotTitle(parsed.plotTitle || "");
      const tagArr = parsed.tags && parsed.tags.length ? parsed.tags : [];
      return {
        eraText: eraText,
        selfText: selfText,
        othersText: othersText,
        identText: identText,
        startText: startText,
        plotTitleSan: plotTitleSan,
        tagArr: tagArr,
      };
    }

    try {
      showToast("正在生成剧情标题与开场概要…", "info");
      const _genCtx = beginGenCall("story-setup", { plot: plot });
      const storyBriefApiOpts = chatApiOptsFromGen(_genCtx, { skipGenReady: true });
      let response = await callChatCompletion(messages, 0.8, storyBriefMaxTokens(), storyBriefApiOpts);
      let parsed = parseStoryBriefResponse(response);
      let fields = buildStoryBriefFieldsFromParsed(parsed);
      let missingRoles = getMissingRoleNamesForIdentityText(fields.identText, plot);

      if (missingRoles.length > 0) {
        showToast("检测到角色身份未覆盖主导角色，正在自动重试一次…", "info", 3200);
        response = await callChatCompletion(messages, 0.72, storyBriefMaxTokens(), storyBriefApiOpts);
        parsed = parseStoryBriefResponse(response);
        fields = buildStoryBriefFieldsFromParsed(parsed);
        missingRoles = getMissingRoleNamesForIdentityText(fields.identText, plot);
      }
      if (missingRoles.length > 0) {
        fields.identText = appendMissingIdentityPlaceholders(fields.identText, plot, missingRoles);
        const fixedSections = splitStoryIdentitySections(fields.identText, plot);
        fields.selfText = fixedSections.selfText;
        fields.othersText = fixedSections.othersText;
      }

      const eraText = fields.eraText;
      const identText = fields.identText;
      const startText = fields.startText;
      const plotTitleSan = fields.plotTitleSan;

      const rawLen = String(response || "").trim().length;
      const allEmpty = !eraText && !identText && !startText && (!fields.tagArr.length && !parsed.tags.length);

      if (!plot.playIntro || typeof plot.playIntro !== "object") plot.playIntro = { era: "", identities: "", myImage: "", otherRoles: "", opening: "" };
      if (plotTitleSan) {
        plot.title = plotTitleSan;
      }
      if (eraText) {
        plot.eraBackground = eraText;
        plot.playIntro.era = eraText;
      }
      if (identText) {
        plot.characterIdentitySelf = fields.selfText || "";
        plot.characterIdentityOthers = fields.othersText || "";
        plot.characterIdentities = identText;
        plot.playIntro.myImage = plot.characterIdentitySelf;
        plot.playIntro.otherRoles = plot.characterIdentityOthers;
        plot.playIntro.identities = identText;
      }
      if (startText) {
        plot.storyStart = startText;
        plot.playIntro.opening = startText;
      }

      const finalTags = fields.tagArr.length
        ? fields.tagArr
        : parsed.tags.length
          ? parsed.tags
          : deriveStoryTagsFromSections(eraText, identText, startText);
      if (finalTags.length) {
        plot.summaryTags = finalTags.slice(0, 3);
        while (plot.summaryTags.length < 3) plot.summaryTags.push("");
      }
      plot.lastGeneratedAt = Date.now();

      const missingParts = [];
      if (!eraText) missingParts.push("时代与场景");
      if (!fields.selfText) missingParts.push("我的形象");
      if (!fields.othersText) missingParts.push("其他角色");
      if (!startText) missingParts.push("故事开端");
      if (!finalTags.length) missingParts.push("概要标签");
      if (!plotTitleSan) missingParts.push("剧情标题");

      const layer = els.layerStory();
      if (!layer.hidden && lastStoryPlotId === plot.id) {
        const titleEl = els.storyTitle();
        if (titleEl) titleEl.textContent = plot.title || "";
        renderStorySummaryTags(plot);
        const setupPanel = document.getElementById("story-panel-setup");
        if (setupPanel && !setupPanel.hidden) renderStorySetup(plot);
        const playPanel = document.getElementById("story-panel-play");
        if (playPanel && !playPanel.hidden) {
          renderStoryPlay(plot);
          fillStoryComposerAvatar(plot);
        }
      }
      renderDynamic();
      if (allEmpty && rawLen > 30) {
        showToast("已收到回复但无法识别小节格式，请点「重新生成」或检查模型输出", "error", 5200);
      } else {
        const setupReady = buildGenCallOpts("story-setup", { plot: plot }).genReady;
        if (setupReady) stashGenReadyNotice(setupReady);
        if (missingParts.length) {
          if (missingParts.length === 1 && missingParts[0] === "剧情标题") {
            showToast(
              "开场概要已生成；未识别「剧情标题」行，列表标题仍为占位。可点「重新生成」或到剧情编辑里改标题。",
              "info",
              5000
            );
          } else {
            showToast(
              "剧情概要已生成，但未完整识别：" + missingParts.join("、") + "。可再点「重新生成」或手动编辑。",
              "info",
              4800
            );
          }
        } else {
          showToast("剧情标题与开场概要生成成功", "success");
        }
      }
    } catch (err) {
      console.error("生成剧情概要失败:", err);
      showToast("生成失败：" + (err && err.message ? err.message : String(err)), "error", 4500);
    } finally {
      clearGenCallContext();
    }
  }

  function fillStoryComposerAvatar(plot) {
    const el = document.getElementById("story-composer-avatar");
    const view = getPlotCharacterView(plot, plot && plot.protagonistId);
    fillAvatarElement(el, view);
    const rawName = view && view.name != null ? String(view.name).trim() : "";
    if (el) el.title = rawName ? rawName + " · 主视角" : "主视角";
  }

  function shouldAutoRequestFirstStoryTurn(plot) {
    if (!plot || plot.playSealed || plot.playTurnInFlight || plot.playChoicesRegenerateInFlight || plot.playChoiceExpandInFlight)
      return false;
    const turns = Array.isArray(plot.playTurns) ? plot.playTurns : [];
    if (turns.length === 0) return true;
    const hasAnyChoices = turns.some(function (turn) {
      const chs = Array.isArray(turn && turn.choices) ? turn.choices : [];
      return chs.length > 0;
    });
    if (!hasAnyChoices) return true;
    const last = turns[turns.length - 1] || {};
    const lastChoices = Array.isArray(last.choices) ? last.choices : [];
    if (lastChoices.length > 0) return false;
    const lastLines = Array.isArray(last.lines) ? last.lines : [];
    return lastLines.length === 0;
  }

  function cleanStoryLine(line) {
    return String(line || "")
      .replace(/^\s*[>\-*•·▸▹▻▶▷►▲△]+\s*/, "")
      .replace(/^\s*\d+[.．、)\]]\s*/, "")
      .trim();
  }

  /** 单行去掉行首「旁白 / narrator」发言标记（支持冒号、空格或紧贴汉字） */
  function stripLeadingNarratorMarkerOneLine(trim) {
    let t = String(trim || "").trim();
    if (!t) return "";
    let next = t.replace(/^(?:旁白|narrator)\s*[：:]\s*/i, "").trim();
    if (next !== t) return next;
    next = t.replace(/^(?:旁白|narrator)\s+/i, "").trim();
    if (next !== t) return next;
    if (/^(?:旁白|narrator)(?=[\u4e00-\u9fff])/i.test(t))
      return t.replace(/^(?:旁白|narrator)/i, "").trim();
    if (/^(?:旁白|narrator)$/i.test(t)) return "";
    return t;
  }

  function lineOpensExplicitNarratorSpeaker(trim) {
    const t = String(trim || "").trim();
    if (!t) return false;
    return stripLeadingNarratorMarkerOneLine(t) !== t;
  }

  /** 去掉「：。」后接弯引号对白等非法连用（模型偶发；亦勿与 ensureEndingPunctuation 叠加出伪影） */
  function fixColonPeriodBeforeCurlyQuote(s) {
    return String(s || "").replace(/：。\s*(\u201c)/g, "：$1");
  }

  /** 叙事气泡末：模型或按句拆分时常丢掉句末标点，仅在明显缺失时补「。」 */
  function ensureEndingPunctuation(raw) {
    let s = String(raw || "").trim();
    if (!s) return s;

    // 若以冒号收束，多为引出下段对白或列举，补「。」会破坏「是：\n“……」类结构
    if (/：\s*$/.test(s)) return s;

    // 如果以引号结尾（对话），不再额外加句号
    if (/[」”]$/.test(s)) return s;

    // 常见结尾标点
    if (/[。！？!?…．]$/.test(s)) return s;
    if (/…$/.test(s)) return s;
    if (/\.{2,}$/.test(s)) return s;

    // 如果是对话类（包含引号），不加句号
    if (/[「“].*[」”]/.test(s)) return s;

    // 如果整段只剩标点或空，彻底清理
    if (/^[。！？!?…\s]+$/.test(s)) return "";

    return s + "。";
  }

  function escapeRegExpLiteral(raw) {
    return String(raw || "").replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  }

  function stripCharacterPrefix(line, knownNames) {
    let out = cleanStoryLine(line);
    if (!out) return "";
    const ord = "(?:\\d+|[一二三四五六七八九十百千两〇零]+)";
    out = out
      .replace(new RegExp("^\\s*[▸▹▻▶▷►▲△]?\\s*第\\s*" + ord + "\\s*条\\s*[｜|/\\\\]?\\s*", "m"), "")
      .replace(new RegExp("\\s*第\\s*" + ord + "\\s*条\\s*[｜|/\\\\]?\\s*$", "m"), "");
    out = out.replace(/^\s*[▸▹▻▶▷►▲△]+\s*/, "");
    out = out.replace(/^\s*[（(]\s*(?:旁白|我|[^)）]{1,20})\s*[)）]\s*/, "");
    out = stripLeadingNarratorMarkerOneLine(out);
    out = out.replace(/^我\s*[：:]\s*/i, "我");
    (knownNames || []).forEach(function (name) {
      const nm = String(name || "").trim();
      if (!nm) return;
      const reg = new RegExp("^" + escapeRegExpLiteral(nm) + "\\s*[：:]\\s*");
      out = out.replace(reg, "");
    });
    return cleanStoryLine(out);
  }

  /** 识别模型英文思考/推理前言（如 Gemini thinking、Extended thinking 等） */
  function looksLikeModelThinkingPreamble(text) {
    const t = String(text || "").trim();
    if (!t) return false;
    const cjk = (t.match(/[\u4e00-\u9fff]/g) || []).length;
    const latin = (t.match(/[A-Za-z]/g) || []).length;
    if (latin > 60 && cjk < 16) return true;
    if (
      /\b(?:I am|I'm|I've|Analyzing|Observing|Focusing|Processing|Integrating|Considering)\b/i.test(t)
    )
      return true;
    if (/\*\*\.?\s*$/m.test(t) || /\*\*\.\s+/m.test(t)) return true;
    if (/(?:^|\n)\s*[A-Z][A-Za-z\s]{2,48}\*\*\.\s/m.test(t)) return true;
    return false;
  }

  /** 去掉首个【说话块】之前的英文推理前言，保留正文与无【】块时的原名起段格式 */
  function stripStoryPlayModelThinkingPreamble(raw) {
    const s = String(raw || "");
    const blockRe = /(?:^|\n)\s*【\s*(?!选项|选择支)[^】]{1,40}\s*】/;
    const m = s.match(blockRe);
    if (!m || typeof m.index !== "number" || m.index <= 0) return s;
    const preamble = s.slice(0, m.index);
    if (!looksLikeModelThinkingPreamble(preamble)) return s;
    return s.slice(m.index).replace(/^\s+/, "");
  }

  /** 规整模型常见问题：围栏、前缀寒暄、Markdown 星号包住【】标题等（利于 Gemini / 多端点）。 */
  function preprocessStoryPlayModelRaw(raw) {
    let s = String(raw || "")
      .replace(/\r\n/g, "\n")
      .replace(/\r/g, "\n")
      .trim();
    s = s.replace(/^```[\w+-]*\s*\n?/i, "").replace(/\n?```\s*$/i, "").trim();
    s = s.replace(/^\s*(?:好的[，,]|我明白了[！!。]?|当然可以[：:]?|没问题[：:]?|以下为|以下是|接下来是|续写如下|根据要求(?:如下)?)[：:]?\s*\n*/gi, "");
    s = s.replace(/^\s*\*{0,2}【/gm, "【");
    s = s.replace(/【\s*([^】]{1,48})\s*】/g, function (_whole, inner) {
      return "【" + String(inner || "").replace(/\*+/g, "").trim() + "】";
    });
    s = stripStoryPlayModelThinkingPreamble(s);
    return s.trim();
  }

  /** 截取用于选项识别的正文（去掉末尾选项区常见标题行，避免误判）。 */
  function sliceStoryRawBeforeChoicesHeader(src) {
    const s = sliceStoryRawBeforeTurnDigestHeader(src);
    const m = s.match(/\n\s*#{0,6}\s*(?:※\s*)?(?:【\s*)?(?:选项|选择支|玩家选项)/i);
    if (m && typeof m.index === "number") return s.slice(0, m.index).trim();
    const m2 = s.match(/\n\s*【\s*(?:选项|选择支)\s*】/i);
    if (m2 && typeof m2.index === "number") return s.slice(0, m2.index).trim();
    const m3 = s.match(/\n-{3,}\s*\n/);
    if (m3 && typeof m3.index === "number") return s.slice(0, m3.index).trim();
    return s.trim();
  }

  /** 去掉文末「本轮概要」区，避免选项解析误读概要正文。 */
  function sliceStoryRawBeforeTurnDigestHeader(src) {
    const s = String(src || "");
    const m = s.match(/\n\s*【\s*(?:本轮概要|内部概要|轮概要)\s*】/i);
    if (m && typeof m.index === "number") return s.slice(0, m.index).trim();
    const m2 = s.match(/\n#{1,6}\s*(?:本轮概要|内部概要|轮概要)\s*[：:]?\s*\n/i);
    if (m2 && typeof m2.index === "number") return s.slice(0, m2.index).trim();
    return s.trim();
  }

  /** 从续写 API 全文末尾解析「本轮概要」（仅存内部，界面不展示）。 */
  function parseTurnInternalDigestBlock(raw) {
    const s = preprocessStoryPlayModelRaw(String(raw || ""));
    if (!s) return "";
    const patterns = [
      /(?:^|\n)\s*【\s*(?:本轮概要|内部概要|轮概要)\s*】\s*\n?([\s\S]*)$/i,
      /(?:^|\n)#{1,6}\s*(?:本轮概要|内部概要|轮概要)\s*[：:]?\s*\n?([\s\S]*)$/i,
    ];
    for (let i = 0; i < patterns.length; i++) {
      const m = s.match(patterns[i]);
      if (!m || !m[1]) continue;
      let text = String(m[1] || "").trim();
      text = text.replace(/\n?```\s*$/i, "").trim();
      if (!text) continue;
      if (Array.from(text).length > TURN_DIGEST_STORE_MAX_CHARS) {
        text = Array.from(text).slice(0, TURN_DIGEST_STORE_MAX_CHARS).join("").trim();
      }
      return text;
    }
    return "";
  }

  /** 花名册外客串角色：稳定 id（同显示名同回合可合并），界面用 speakerName + 首字头像。 */
  var EPHEMERAL_NPC_PREFIX = "ephe_npc_";

  function isEphemeralStoryNpcId(characterId) {
    return String(characterId || "").indexOf(EPHEMERAL_NPC_PREFIX) === 0;
  }

  function normalizeEphemeralSpeakerKey(title) {
    let t = String(title || "")
      .trim()
      .replace(/\*+/g, "")
      .replace(/\s+/g, "");
    t = t.replace(/[（(][^)）]{0,16}[)）]\s*$/u, "");
    return t.slice(0, 40);
  }

  function ephemeralNpcCharacterIdFromTitle(title) {
    const key = normalizeEphemeralSpeakerKey(title);
    if (!key) return EPHEMERAL_NPC_PREFIX + uid("x");
    let h = 2166136261;
    for (let i = 0; i < key.length; i++) {
      h ^= key.charCodeAt(i);
      h = Math.imul(h, 16777619);
    }
    return EPHEMERAL_NPC_PREFIX + (h >>> 0).toString(36);
  }

  function displayNameFromEphemeralBlockTitle(title) {
    let t = String(title || "")
      .trim()
      .replace(/\*+/g, "")
      .trim();
    if (!t) return "角色";
    const arr = Array.from(t);
    if (arr.length > 20) return arr.slice(0, 20).join("") + "…";
    return t;
  }

  /** 去掉块标题首尾引号、空白与零碎标点，用语义判断是否在「起名」而非旁白对白碎片 */
  function stripEdgeSpeakerTitleNoise(s) {
    let t = String(s || "").trim();
    for (let n = 0; n < 16; n++) {
      const u = t
        .replace(/^[\s\u3000"'「」『』〈〉《》【】[\]()（）\u201c\u201d\u2018\u2019\u00b7.,，。．!！?？:：;；···…\-—_=＿]+/u, "")
        .replace(/[\s\u3000"'「」『』〈〉《》【】[\]()（）\u201c\u201d\u2018\u2019\u00b7.,，。．!！?？:：;；···…\-—_=＿]+$/u, "");
      if (u === t) break;
      t = u.trim();
    }
    return t;
  }

  /** 整块标题长得像「对白一句」而非人名（如 “遵命。”），不当成客串头像行 */
  function looksQuotedDialogFragmentTitle(raw) {
    const t = String(raw || "").trim();
    if (t.length < 2 || t.length > 36) return false;
    const first = t[0];
    const lastCh = t[t.length - 1];
    const openOk = /^[\u201c\u2018"'「『“]/.test(first);
    if (!openOk && first !== "(" && first !== "（") return false;
    const tailOk = /[。！？!?…⋯」』\u201d"']$/u.test(lastCh);
    return tailOk && /[，。．…！？;；、]/.test(t);
  }

  /**
   * 花名册外客串：避免出现【"】、对白碎片误当姓名等。
   * 未通过时 resolveLineSpeaker 会退回旁白合并。
   */
  function acceptableEphemeralStorySpeakerTitle(title) {
    const raw = String(title || "").trim().replace(/\*+/g, "").trim();
    if (!raw || raw === "\u65c1\u767d" || /^narrator$/i.test(raw)) return false;
    if (/^(?:我|主角)$/i.test(raw)) return false;
    if (/^[\s\u201c\u201d\u2018\u2019"'「」『』〈〉]+$/.test(raw)) return false;
    if (looksQuotedDialogFragmentTitle(raw)) return false;
    const keyGuess = normalizeEphemeralSpeakerKey(raw);
    let core = stripEdgeSpeakerTitleNoise(keyGuess || "");
    if (!core) core = stripEdgeSpeakerTitleNoise(raw);
    if (!core) return false;
    if (/^[\d\s,.，。\-\—_]+$/.test(core)) return false;
    const hasNameChar = /[\u4e00-\u9fff\u3400-\u4dbfA-Za-z]/.test(core);
    if (!hasNameChar) return false;
    const glyphs = Array.from(core);
    if (glyphs.length < 2) return false;
    if (/^[，。！？、；：·…]+$/.test(core)) return false;
    if (/^(此时|此刻|转念|转念间|转念一想|转念之间|话音)$/u.test(core)) return false;
    if (/^(话音未落|话音刚落|话锋一转|话音甫落|未及他|未及她|未及两人|未及众人)$/u.test(core)) return false;
    if (/^(这一|那一次|那一瞬间|一转眼|一转眼儿|一转眼功夫)/u.test(core)) return false;
    return true;
  }

  function finalizeStoryBlocks(blocks, resolveLineSpeaker) {
    const out = [];
    (blocks || []).forEach(function (blk) {
      const text = String((blk.chunks || []).join("\n") || "").trim();
      if (!text) return;
      const paras = text
        .split(/\n\s*\n+/)
        .map(function (seg) {
          return ensureEndingPunctuation(cleanStoryLine(seg));
        })
        .filter(Boolean);
      if (!paras.length) return;
      const res = resolveLineSpeaker(blk.titleHint);
      const row = {
        characterId: res.characterId,
        text: fixColonPeriodBeforeCurlyQuote(paras.join("\n\n")),
      };
      if (res.speakerName) row.speakerName = res.speakerName;
      out.push(row);
    });
    return out;
  }

  function parseTurnByCharacterBlocksStrict(lines, resolveLineSpeaker) {
    const blocks = [];
    let current = null;
    lines.forEach(function (ln) {
      const line = String(ln || "");
      const trim = line.trim();
      let m = trim.match(/^【\s*([^】]{1,40})\s*】$/);
      let tail = "";
      if (!m) {
        const m2 = trim.match(/^【\s*([^】]{1,40})\s*】\s*(.*)$/);
        if (m2) {
          m = m2;
          tail = String(m2[2] || "").trim();
        }
      }
      if (m) {
        const title = String(m[1] || "").trim();
        if (/^(?:选项|选择支)$/i.test(title)) {
          current = null;
          return;
        }
        current = { titleHint: title, chunks: [] };
        blocks.push(current);
        if (tail) current.chunks.push(tail);
        return;
      }
      if (!current) return;
      const lnClean = cleanStoryLine(line);
      if (lineOpensExplicitNarratorSpeaker(lnClean)) {
        const rest = stripLeadingNarratorMarkerOneLine(lnClean);
        current = { titleHint: "\u65c1\u767d", chunks: rest ? [rest] : [] };
        blocks.push(current);
        return;
      }
      current.chunks.push(line);
    });
    return finalizeStoryBlocks(blocks, resolveLineSpeaker);
  }

  /** 独占一行且与花名册完全一致的发言者标记（常见小说体：姓名单独一行，下一行起接对白或描写）。 */
  function normalizeStandaloneSpeakerLabel(raw) {
    let t = String(raw || "").trim();
    if (!t) return "";
    const bold = t.match(/^\*{1,2}\s*([^*]+?)\s*\*{1,2}$/);
    if (bold) t = String(bold[1] || "").trim();
    return t;
  }

  /**
   * 将【块标题】或独占行姓名匹配到花名册（允许：带括号后缀、标题比全名更长、略写等）。
   * 无法唯一确定时返回 null，避免误绑头像。
   */
  function findCastIdBySpeakerTitle(title, cast) {
    let tt = normalizeStandaloneSpeakerLabel(String(title || "")).trim().replace(/\s+/g, "");
    if (!tt) return null;
    tt = tt.replace(/[（(][^)）]*[)）]\s*$/u, "").trim().replace(/\s+/g, "");
    if (!tt) return null;
    if (/^(?:旁白|narrator)$/i.test(tt)) return null;

    const list = (cast || []).filter(function (c) {
      return c && c.id && String(c.name || "").trim();
    });
    if (!list.length) return null;

    for (let i = 0; i < list.length; i++) {
      const nmRaw = String(list[i].name).trim();
      const nm = nmRaw.replace(/\s+/g, "");
      if (nm === tt) return list[i].id;
      if (/[a-zA-Z]/.test(nm) && nm.toLowerCase() === tt.toLowerCase()) return list[i].id;
    }

    const byExtend = [];
    const byPrefix = [];
    for (let i = 0; i < list.length; i++) {
      const nm = String(list[i].name).trim().replace(/\s+/g, "");
      if (!nm.length) continue;
      if (tt.startsWith(nm)) byExtend.push({ c: list[i], nm: nm, len: nm.length });
      if (nm.startsWith(tt) && (tt.length >= 2 || nm.length === tt.length))
        byPrefix.push({ c: list[i], nm: nm, len: nm.length });
    }
    byExtend.sort(function (a, b) {
      return b.len - a.len;
    });
    if (byExtend.length) {
      const top = byExtend[0].len;
      const tops = byExtend.filter(function (x) {
        return x.len === top;
      });
      if (tops.length === 1 && tops[0].nm.length >= 2) return tops[0].c.id;
    }
    byPrefix.sort(function (a, b) {
      return b.len - a.len;
    });
    if (byPrefix.length === 1) return byPrefix[0].c.id;
    if (byPrefix.length > 1) {
      const top = byPrefix[0].len;
      const tops = byPrefix.filter(function (x) {
        return x.len === top;
      });
      if (tops.length === 1) return tops[0].c.id;
    }
    return null;
  }

  function tryMatchStandaloneCastSpeaker(trim, nameList, cast, protagonist) {
    const t = normalizeStandaloneSpeakerLabel(trim);
    if (!t) return null;
    if (protagonist && protagonist.id && /^(?:我|主角)$/i.test(t)) {
      return { titleHint: /^主角$/i.test(t) ? "主角" : "我" };
    }
    for (let i = 0; i < nameList.length; i++) {
      const nm = nameList[i];
      if (nm && t === nm) return { titleHint: nm };
    }
    const looseId = findCastIdBySpeakerTitle(t, cast);
    if (looseId) {
      for (let j = 0; j < cast.length; j++) {
        if (cast[j].id === looseId && cast[j].name) return { titleHint: String(cast[j].name).trim() };
      }
    }
    if (/^(?:旁白|narrator)$/i.test(t)) return null;
    if (!acceptableEphemeralStorySpeakerTitle(t)) return null;
    const charCount = Array.from(t).length;
    if (
      charCount >= 2 &&
      t.length <= 32 &&
      !/^[\d\s._·…《》「」:【】]+$/.test(t) &&
      !/^(?:第.{1,12}章|第.{1,12}节|序章|楔子)/.test(t)
    ) {
      return { titleHint: t };
    }
    return null;
  }

  /** 适配「张明：台词」单行起块（名册中的全名）。 */
  function parseTurnByCharacterBlocksNameColon(lines, cast, protagonist, resolveLineSpeaker) {
    const nameList = (cast || [])
      .filter(function (c) {
        return c && String(c.name || "").trim();
      })
      .map(function (c) {
        return String(c.name).trim();
      });
    nameList.sort(function (a, b) {
      return (b.length || 0) - (a.length || 0);
    });
    function tryMatchNameColon(trim) {
      if (/^(?:旁白|narrator)\s*[：:]/i.test(trim)) {
        return {
          nm: "\u65c1\u767d",
          rest: trim.replace(/^(?:旁白|narrator)\s*[：:]\s*/i, "").trim(),
        };
      }
      if (/^(?:旁白|narrator)\s+/i.test(trim)) {
        return {
          nm: "\u65c1\u767d",
          rest: trim.replace(/^(?:旁白|narrator)\s+/i, "").trim(),
        };
      }
      if (/^(?:旁白|narrator)(?=[\u4e00-\u9fff])/i.test(trim)) {
        return {
          nm: "\u65c1\u767d",
          rest: trim.replace(/^(?:旁白|narrator)/i, "").trim(),
        };
      }
      for (let i = 0; i < nameList.length; i++) {
        const nm = nameList[i];
        if (!nm) continue;
        if (!(trim.startsWith(nm + "\uff1a") || trim.startsWith(nm + ":"))) continue;
        const rest = trim.slice(nm.length).replace(/^[：:]\s*/, "").trim();
        return { nm: nm, rest: rest };
      }
      const colonLoose = trim.match(/^([^:：\n]{1,16})([：:])([\s\S]*)$/);
      if (colonLoose) {
        const head = String(colonLoose[1] || "").trim();
        const restPart = String(colonLoose[3] || "").trim();
        const hid = findCastIdBySpeakerTitle(head, cast);
        if (hid) {
          for (let k = 0; k < cast.length; k++) {
            if (cast[k].id === hid && cast[k].name) {
              return { nm: String(cast[k].name).trim(), rest: restPart };
            }
          }
        }
        if (head && acceptableEphemeralStorySpeakerTitle(head) && head.length <= 20) {
          return { nm: head, rest: restPart };
        }
      }
      return null;
    }
    const blocks = [];
    let current = null;
    const pendingPrelude = [];
    function flushPreludeIfAny() {
      const t = pendingPrelude.join("\n").trim();
      pendingPrelude.length = 0;
      if (!t || /【\s*(?:选项|选择支)/.test(t)) return;
      blocks.push({ titleHint: "\u65c1\u767d", chunks: [t] });
    }
    lines.forEach(function (ln) {
      const trim = cleanStoryLine(String(ln || ""));
      if (/^【/.test(trim)) {
        pendingPrelude.push(String(ln || ""));
        return;
      }
      const standalone = tryMatchStandaloneCastSpeaker(trim, nameList, cast, protagonist);
      if (standalone) {
        flushPreludeIfAny();
        current = { titleHint: standalone.titleHint, chunks: [] };
        blocks.push(current);
        return;
      }
      const mc = tryMatchNameColon(trim);
      if (mc) {
        if (mc.nm === "\u65c1\u767d") {
          flushPreludeIfAny();
          current = { titleHint: "\u65c1\u767d", chunks: [] };
          blocks.push(current);
          if (mc.rest) current.chunks.push(mc.rest);
          return;
        }
        flushPreludeIfAny();
        current = { titleHint: mc.nm, chunks: [] };
        blocks.push(current);
        if (mc.rest) current.chunks.push(mc.rest);
        return;
      }
      if (!trim) return;
      if (current) {
        current.chunks.push(String(ln || ""));
        return;
      }
      pendingPrelude.push(String(ln || ""));
    });
    flushPreludeIfAny();
    return finalizeStoryBlocks(blocks, resolveLineSpeaker);
  }

  function parseTurnByFallbackNarrator(src) {
    let body = sliceStoryRawBeforeChoicesHeader(src);
    body = body.replace(/\n\s*【\s*(?:选项|选择支)\s*】[\s\S]*$/i, "").trim();
    if (body.length < 24) return [];
    return [
      {
        characterId: "narrator",
        text: fixColonPeriodBeforeCurlyQuote(
          ensureEndingPunctuation(cleanStoryLine(body)).replace(/\n{3,}/g, "\n\n")
        ),
      },
    ];
  }

  function parseTurnByCharacterBlocks(raw, protagonist, supporting) {
    const src = preprocessStoryPlayModelRaw(raw);
    if (!src) return [];
    const cast = []
      .concat(protagonist ? [protagonist] : [])
      .concat(supporting || [])
      .filter(function (c) {
        return c && c.id && c.name;
      });
    function resolveLineSpeaker(title) {
      const t = String(title || "").trim();
      if (!t) return { characterId: "narrator" };
      if (/^(?:旁白|narrator)$/i.test(t)) return { characterId: "narrator" };
      if (/^(?:我|主角)$/i.test(t) && protagonist && protagonist.id) return { characterId: protagonist.id };
      for (let i = 0; i < cast.length; i++) {
        if (cast[i].name === t) return { characterId: cast[i].id };
      }
      const loose = findCastIdBySpeakerTitle(t, cast);
      if (loose) return { characterId: loose };
      if (!acceptableEphemeralStorySpeakerTitle(t)) return { characterId: "narrator" };
      const key = normalizeEphemeralSpeakerKey(t);
      if (!key) return { characterId: "narrator" };
      return {
        characterId: ephemeralNpcCharacterIdFromTitle(t),
        speakerName: displayNameFromEphemeralBlockTitle(t),
      };
    }
    const lines = src.split(/\n/);
    let out = parseTurnByCharacterBlocksStrict(lines, resolveLineSpeaker);
    if (out.length) return out;
    out = parseTurnByCharacterBlocksNameColon(lines, cast, protagonist, resolveLineSpeaker);
    if (out.length) return out;
    return parseTurnByFallbackNarrator(src);
  }

  /** 模型未写「行动：」时，常见为 1. / 一、 / - 开头的多行选项 */
  function extractLooseChoiceLines(sectionText) {
    const extra = [];
    String(sectionText || "")
      .split("\n")
      .map(cleanStoryLine)
      .filter(Boolean)
      .forEach(function (line) {
        if (/^行动[：:]/i.test(line)) return;
        if (/^提示[：:]/i.test(line)) return;
        if (/^选择支/i.test(line)) return;
        let m = line.match(/^(?:\(?(\d{1,2})\)?)[\.．、:：)\]]\s*(.+)$/);
        if (m) {
          extra.push({ line: m[2] ? m[2].trim() : "", hint: "" });
          return;
        }
        m = line.match(/^([一二三四五六七八九十])[\.．、:：]\s*(.+)$/);
        if (m) {
          extra.push({ line: m[2].trim(), hint: "" });
          return;
        }
        m = line.match(/^([①②③④⑤⑥⑦⑧⑨⑩])\s*(.+)$/);
        if (m) {
          extra.push({ line: m[2].trim(), hint: "" });
          return;
        }
        m = line.match(/^([A-Da-d])[\.．、:：)\]]\s*(.+)$/);
        if (m) {
          extra.push({ line: m[2].trim(), hint: "" });
          return;
        }
        m = line.match(/^[-*•·]\s*(.+)$/);
        if (m) {
          extra.push({ line: m[1].trim(), hint: "" });
          return;
        }
      });
    return extra;
  }

  function normalizeChoiceLineLength(raw) {
    const txt = cleanStoryLine(raw)
      .replace(/[。！？!?；;，,、]+$/g, "")
      .trim();
    if (!txt) return "";
    // 不在前端硬截断，避免出现“半句话”；长度由提示词约束给模型。
    return txt;
  }

  function isPlaceholderLikeChoiceLine(text) {
    const t = cleanStoryLine(text)
      .replace(/^[「“"'`]+|[」”"'`]+$/g, "")
      .trim();
    if (!t) return true;
    if (/^(?:\.{2,}|…{2,}|。{2,}|·{2,}|—{2,}|_{2,}|-{2,}|~{2,})$/.test(t)) return true;
    if (/^(?:待定|略|暂无|无|同上|稍后补充|这里略去)$/.test(t)) return true;
    return false;
  }

  function parseStoryChoices(rawSection, fullRaw) {
    const results = [];
    const pushChoice = function (line, hint) {
      let action = cleanStoryLine(line);
      action = action
        .replace(/^(?:\(?\d{1,2}\)?|[一二三四五六七八九十]|[①②③④⑤⑥⑦⑧⑨⑩]|[A-Da-d])[\.．、:：)\]]\s*/, "")
        .trim();
      action = normalizeChoiceLineLength(action);
      const tip = cleanStoryLine(hint || "");
      if (!action || isPlaceholderLikeChoiceLine(action)) return;
      results.push({
        line: action,
        hint: tip || "选择此项",
      });
    };
    const appendToLastChoice = function (line) {
      if (!results.length) return false;
      const extra = cleanStoryLine(line);
      if (!extra) return false;
      const last = results[results.length - 1];
      const sep = /[A-Za-z0-9]$/.test(last.line) && /^[A-Za-z0-9]/.test(extra) ? " " : "";
      last.line = normalizeChoiceLineLength(String(last.line || "") + sep + extra);
      return true;
    };
    const looksLikeChoiceStart = function (line) {
      const s = String(line || "").trim();
      if (!s) return false;
      if (/^行动[：:]/i.test(s)) return true;
      if (/^(?:\(?\d{1,2}\)?|[一二三四五六七八九十]|[①②③④⑤⑥⑦⑧⑨⑩]|[A-Da-d])[\.．、:：)\]]\s*/.test(s))
        return true;
      if (/^[-*•·]\s+/.test(s)) return true;
      return false;
    };
    const looksLikeContinuation = function (line) {
      if (!results.length) return false;
      const s = cleanStoryLine(line);
      if (!s || looksLikeChoiceStart(s) || /^(?:提示|hint|选择支)[:：]/i.test(s)) return false;
      const lastLine = String(results[results.length - 1].line || "");
      if (!lastLine) return false;
      if (/[，、：:（(“"‘'《<]$/.test(lastLine)) return true;
      if (lastLine.length <= 8) return true;
      if (/^[，。！？!?；;：:、）)》>]/.test(s)) return true;
      return false;
    };

    const section = String(rawSection || "");
    section.split("\n").forEach(function (rawLine) {
      const line = cleanStoryLine(rawLine);
      if (!line) return;
      // 支持更多自然格式
      const m1 = line.match(/行动[：:]\s*([^|｜；;]+?)\s*(?:[|｜]|[；;])\s*提示[：:]\s*(.+)$/i);
      if (m1) { pushChoice(m1[1], m1[2]); return; }

      const m2 = line.match(/行动[：:]\s*(.+)$/i);
      if (m2) { pushChoice(m2[1], ""); return; }

      const hintOnly = line.match(/^(?:提示|hint)[:：]\s*(.+)$/i);
      if (hintOnly) {
        if (results.length) {
          results[results.length - 1].hint = cleanStoryLine(hintOnly[1]) || "选择此项";
        }
        return;
      }

      if (/^(?:选择支|可选行动|行动选项|玩家选项|玩家抉择|分支选项|选项)[:：]?/i.test(line)) return;
      if (looksLikeContinuation(rawLine) || looksLikeContinuation(line)) {
        appendToLastChoice(line);
        return;
      }
      pushChoice(line, "");
    });

    if (results.length < 3) {
      extractLooseChoiceLines(section || fullRaw).forEach(function (it) {
        pushChoice(it.line, it.hint);
      });
    }

    const dedup = [];
    const seen = new Set();
    results.forEach(function (it) {
      const key = it.line + "\n" + it.hint;
      if (seen.has(key)) return;
      seen.add(key);
      dedup.push(it);
    });
    return dedup;
  }

  function normalizeChoiceForCompare(text) {
    return String(text || "")
      .toLowerCase()
      .replace(/[「」“”"'`]/g, "")
      .replace(/[，。！？!?,、；;：:\s]/g, "");
  }

  function stripTrailingChoiceIndexDecor(line) {
    let s = String(line || "").trim();
    s = s.replace(/[（(]\s*\d{1,2}\s*[)）]\s*$/g, "").trim();
    s = s.replace(/[\[［]\s*\d{1,2}\s*[\]］]\s*$/g, "").trim();
    return s;
  }

  /**
   * 将模型写在一行内的多条玩家选项拆开（弯引号两段对白粘连、半角 \" 分段、或「对白」后接无引号动作）。
   * 用于缓解多选项被压成单个按钮的问题。
   */
  function expandMergedChoiceLine(raw) {
    const s0 = String(raw || "").trim();
    if (!s0) return [];
    let pieces = [];

    if (/"/.test(s0)) {
      const re = /"([^"]*)"/g;
      let m;
      let lastIdx = 0;
      const quoted = [];
      while ((m = re.exec(s0)) !== null) {
        quoted.push("\u201c" + String(m[1] || "").trim() + "\u201d");
        lastIdx = re.lastIndex;
      }
      const tail = s0.slice(lastIdx).trim();
      const cand = quoted.concat(tail ? [tail] : []);
      if (cand.length >= 2) {
        pieces = cand;
      }
    }

    if (!pieces.length && /[\u201C\u201D“”]/.test(s0)) {
      const curly = s0
        .split(/(?<=[\u201D”])\s*(?=[\u201C“])/g)
        .map(function (t) {
          return String(t || "").trim();
        })
        .filter(Boolean);
      if (curly.length >= 2) {
        pieces = curly;
      }
    }

    if (!pieces.length) {
      pieces = [s0];
    }

    const out = [];
    pieces.forEach(function (seg) {
      const s = String(seg || "").trim();
      if (!s) return;

      const curlyDialogueThenAction = s.match(
        /^([\u201C“][\s\S]*?[\u201D”])\s+([^“\s\u201C][\s\S]*)$/
      );
      if (curlyDialogueThenAction && String(curlyDialogueThenAction[2] || "").trim()) {
        out.push(curlyDialogueThenAction[1].trim());
        out.push(curlyDialogueThenAction[2].trim());
        return;
      }

      const straightDialogueThenAction = s.match(/^"([^"]*)"\s+([^"\s][\s\S]*)$/);
      if (straightDialogueThenAction && String(straightDialogueThenAction[2] || "").trim()) {
        out.push(
          "\u201c" + String(straightDialogueThenAction[1] || "").trim() + "\u201d"
        );
        out.push(straightDialogueThenAction[2].trim());
        return;
      }

      out.push(s);
    });

    return out.filter(Boolean);
  }

  /** 去重、过滤无效选项。数量由模型决定（最少 2 条）。 */
  function sanitizeStoryChoices(choices) {
    const out = [];
    const seen = new Set();
    (Array.isArray(choices) ? choices : []).forEach(function (c) {
      const hintBase = String((c && c.hint) || "").trim() || "选择此项";
      const expanded = expandMergedChoiceLine((c && c.line) || "");
      const linesToAdd =
        expanded.length > 0 ? expanded : [String((c && c.line) || "").trim()].filter(Boolean);
      linesToAdd.forEach(function (oneLine) {
        let line = normalizeChoiceLineLength(oneLine);
        const hint = hintBase;
        line = stripTrailingChoiceIndexDecor(cleanStoryLine(line));
        if (!line || isPlaceholderLikeChoiceLine(line)) return;
        const key = normalizeChoiceForCompare(line);
        if (!key || seen.has(key)) return;
        seen.add(key);
        out.push({ line: line, hint: hint });
      });
    });
    return out;
  }

  function extractTrailingNumberedOrBulletList(src) {
    const lines = String(src || "").replace(/\r/g, "").split("\n");
    const picked = [];
    for (let i = lines.length - 1; i >= 0; i--) {
      const L = cleanStoryLine(lines[i]);
      if (!L) {
        if (picked.length) break;
        continue;
      }
      if (/^[-*_]{3,}$/.test(L)) {
        if (picked.length) break;
        continue;
      }
      const looksNum =
        /^(?:\(?\d{1,2}\)?[\.．、:：)\]]|[一二三四五六七八九十][\.．、:：])\s+.+/u.test(L) ||
        /^[①②③④⑤⑥⑦⑧⑨⑩]\s*.+/u.test(L);
      const looksBullet =
        /^[-•·]\s+.+/u.test(L) ||
        (/^\*\s+.+/u.test(L) &&
          !/^(\*\*|__)\s*[^*]+(?:\*\*|__)\s*(?:\*|_|$)?/u.test(L));
      if (!looksNum && !looksBullet) {
        if (picked.length) break;
        continue;
      }
      picked.unshift(lines[i]);
      if (picked.length > 18) break;
    }
    return picked.length >= 2 ? picked.join("\n").trim() : "";
  }

  function pushUniqueStoryChoiceSection(list, s) {
    const t = String(s || "").trim();
    if (!t) return;
    if (list.indexOf(t) >= 0) return;
    list.push(t);
  }

  /** 多种常见「选项」区标题样式（Gemini / Markdown / 分割线）。依次尝试直至解析出 ≥2 条。 */
  function collectStoryChoiceSectionCandidates(src) {
    const out = [];
    const s = sliceStoryRawBeforeTurnDigestHeader(String(src || ""));
    const patterns = [
      /(?:^|\n)\s*【\s*(?:选项|选择支)\s*】\s*(?:\n|$)/i,
      /\n#{1,6}\s*\*{0,3}\s*(?:※\s*)?(?:选项|玩家选项|PLAYER\s*CHOICES?|玩家抉择|分支选项)\*{0,3}\s*[：:]?\s*\n/i,
      /\n\*{1,3}\s*(?:选项|玩家选项)\s*\*{0,3}\s*[：:]?\s*\n/i,
      /\n(?:-{3,}|\*{3,}|_{3,})\s*\n/,
      /\n(?:可选行动|玩家(?:可选)?行动|你选择|玩家请选择)\s*[：:]?\s*\n/i,
    ];
    for (let p = 0; p < patterns.length; p++) {
      const m = s.match(patterns[p]);
      if (m && typeof m.index === "number") {
        pushUniqueStoryChoiceSection(out, s.slice(m.index + m[0].length));
      }
    }
    pushUniqueStoryChoiceSection(out, extractTrailingNumberedOrBulletList(s));
    return out;
  }

  function parseChoicesBlock(raw) {
    const src = preprocessStoryPlayModelRaw(String(raw || ""));
    if (!src) return [];
    const candidates = collectStoryChoiceSectionCandidates(src);
    for (let ci = 0; ci < candidates.length; ci++) {
      const parsed = sanitizeStoryChoices(parseStoryChoices(candidates[ci], src));
      if (parsed.length >= 2) return parsed;
    }
    return sanitizeStoryChoices(parseStoryChoices("", src));
  }

  /** 解析「1. xxx 2. yyy」同级写在一段内的编号列表（用于去掉正文末尾重复的选项预览）。 */
  function splitInlineNumberedList(tail) {
    const items = [];
    const s = String(tail || "").trim();
    if (!s) return items;
    const re = /(\d{1,2})\s*[\.．、:：]\s*/g;
    const positions = [];
    let m;
    while ((m = re.exec(s)) !== null) {
      positions.push({ idx: m.index, len: m[0].length, num: m[1] });
    }
    if (!positions.length) return items;
    for (let i = 0; i < positions.length; i++) {
      const start = positions[i].idx + positions[i].len;
      const end = i + 1 < positions.length ? positions[i + 1].idx : s.length;
      items.push({ num: positions[i].num, text: s.slice(start, end).trim() });
    }
    return items;
  }

  /**
   * 去掉正文末尾与已解析选项一致的编号列表（同一行内「…。 1. … 2. …」也会删掉）。
   */
  function stripTrailingInlineNumberedChoicesFromText(text, choices) {
    const raw = String(text || "").replace(/\r\n/g, "\n").trim();
    if (!raw || !choices || choices.length < 2) return text;
    const wantLines = choices
      .map(function (c) {
        return String((c && c.line) || "").trim();
      })
      .filter(Boolean);
    if (wantLines.length < 2) return text;
    const wantNorms = wantLines.map(normalizeChoiceForCompare);

    const reStart = /(^|[\s\u3000\n])(\d{1,2})\s*[\.．、:：]\s*/g;
    let bestCut = -1;
    let mm;
    while ((mm = reStart.exec(raw)) !== null) {
      const from = mm.index + mm[1].length;
      const tail = raw.slice(from).trim();
      const items = splitInlineNumberedList(tail);
      if (items.length < wantLines.length) continue;
      const sliceItems = items.slice(-wantLines.length);
      let ok = true;
      for (let i = 0; i < wantLines.length; i++) {
        const sn = normalizeChoiceForCompare(sliceItems[i].text);
        const wn = wantNorms[i];
        if (sn === wn) continue;
        const shorter = sn.length <= wn.length ? sn : wn;
        const longer = sn.length > wn.length ? sn : wn;
        if (shorter.length >= 8 && longer.indexOf(shorter) !== -1) continue;
        ok = false;
        break;
      }
      if (ok) bestCut = from;
    }
    if (bestCut < 0) return text;
    return raw.slice(0, bestCut).trimEnd();
  }

  /**
   * 模型常在【选项】区之前把选项又写进正文（甚至挂在角色名下）。
   * 在已解析出文末选项的前提下，从各说话块中剔除：编号/项目符号行、无编号但与选项文案重合的短行，以及文末重复的编号列表。
   */
  function stripEmbeddedChoicePreviewFromStoryLines(lines, choices) {
    if (!Array.isArray(lines) || !lines.length) return lines;
    if (!Array.isArray(choices) || choices.length < 2) return lines;
    const choiceLines = choices.map(function (c) {
      return String((c && c.line) || "").trim();
    });
    const choiceNorms = choiceLines
      .map(function (t) {
        return normalizeChoiceForCompare(t);
      })
      .filter(function (s) {
        return s.length >= 4;
      });
    if (!choiceNorms.length) return lines;

    const maxChoiceRawChars = Math.max.apply(
      null,
      choiceLines
        .map(function (t) {
          return t.length;
        })
        .concat([0])
    );

    function normMatchesChoice(restNorm, minSubstrLen) {
      const ms = minSubstrLen == null ? 10 : minSubstrLen;
      if (!restNorm || restNorm.length < 4) return false;
      for (let i = 0; i < choiceNorms.length; i++) {
        const ch = choiceNorms[i];
        if (!ch || ch.length < 4) continue;
        if (restNorm === ch) return true;
        const shorter = restNorm.length <= ch.length ? restNorm : ch;
        const longer = restNorm.length > ch.length ? restNorm : ch;
        if (shorter.length >= ms && longer.indexOf(shorter) !== -1) return true;
      }
      return false;
    }

    function lineLooksLikeEmbeddedChoiceRow(rawLine) {
      const row = cleanStoryLine(String(rawLine || ""));
      if (!row) return false;
      if (/^选项\s*\d{0,2}\s*[\.．、:：]\s*\S/.test(row)) return true;
      if (/^选项\s*[：:]\s*\S/.test(row)) return true;
      const mNum = row.match(/^\d{1,2}\s*[\.．、:：]\s*(.+)$/);
      if (mNum && normMatchesChoice(normalizeChoiceForCompare(mNum[1]), 8)) return true;
      const mCn = row.match(/^[（(]?\s*[一二三四五六七八九十]+\s*[）)]?\s*[\.．、:：]\s*(.+)$/);
      if (mCn && normMatchesChoice(normalizeChoiceForCompare(mCn[1]), 8)) return true;
      const mBul = row.match(/^[•·▸▹\-*＊]\s*(.+)$/);
      if (mBul && normMatchesChoice(normalizeChoiceForCompare(mBul[1]), 8)) return true;
      const bare = normalizeChoiceForCompare(row);
      if (
        bare.length >= 6 &&
        row.length <= maxChoiceRawChars + 28 &&
        normMatchesChoice(bare, 10)
      )
        return true;
      return false;
    }

    function stripTrailingChoiceLikeLines(rows) {
      const out = rows.slice();
      while (out.length) {
        const trimmed = cleanStoryLine(String(out[out.length - 1] || "")).trim();
        if (!trimmed) {
          out.pop();
          continue;
        }
        if (!lineLooksLikeEmbeddedChoiceRow(trimmed)) break;
        out.pop();
      }
      return out;
    }

    function cleanBlockText(text) {
      const raw = String(text || "").replace(/\r\n/g, "\n");
      const keptRows = [];
      const rows = raw.split("\n");
      for (let ri = 0; ri < rows.length; ri++) {
        if (!lineLooksLikeEmbeddedChoiceRow(rows[ri])) keptRows.push(rows[ri]);
      }
      const trimmedRows = stripTrailingChoiceLikeLines(keptRows);
      let out = trimmedRows.join("\n").replace(/\n{3,}/g, "\n\n").trim();
      const paras = out.split(/\n\s*\n+/);
      const keptParas = paras.filter(function (p) {
        const pt = cleanStoryLine(p).trim();
        if (!pt) return false;
        if (lineLooksLikeEmbeddedChoiceRow(pt)) return false;
        if (!/\n/.test(pt)) {
          const pn = normalizeChoiceForCompare(pt);
          if (
            pt.length <= maxChoiceRawChars + 28 &&
            pn.length >= 6 &&
            normMatchesChoice(pn, 10)
          )
            return false;
        }
        return true;
      });
      let joined = keptParas.join("\n\n").trim();
      joined = stripTrailingInlineNumberedChoicesFromText(joined, choices);
      return joined;
    }

    return lines
      .map(function (ln) {
        const o = {
          characterId: ln.characterId,
          text: cleanBlockText(String((ln && ln.text) || "")),
          id: ln.id,
        };
        if (ln && String(ln.speakerName || "").trim()) o.speakerName = String(ln.speakerName).trim();
        return o;
      })
      .filter(function (ln) {
        return String((ln && ln.text) || "").trim();
      });
  }

  function isPlotStoryParticipant(plot, characterId) {
    if (!characterId || characterId === "narrator") return false;
    if (characterId === plot.protagonistId) return true;
    const sup = plot.supportingIds || [];
    return Array.isArray(sup) && sup.indexOf(characterId) >= 0;
  }

  /** 旁白展示与入库清洗：去掉模型输出的章节标题、「旁白」行首标记（支持多行、每行独立；含「旁白：」「旁白 ␠」「旁白正文」） */
  function stripNarratorDisplayText(text) {
    let s = String(text || "")
      .replace(/\r\n/g, "\n")
      .replace(/\r/g, "\n")
      .trim();
    if (!s) return "";
    s = s.replace(/^(?:续写内容|剧情续写|剧情内容|正文)\s*[：:]\s*/i, "").trim();
    const lines = s.split("\n");
    const out = lines.map(function (line) {
      let t = String(line || "").trim();
      t = t.replace(/^[（(]\s*(?:旁白|narrator)\s*[)）]\s*/i, "").trim();
      return stripLeadingNarratorMarkerOneLine(t);
    });
    return out.join("\n").replace(/\n{3,}/g, "\n\n").trim();
  }

  /** 一整行里没有汉字、字母或数字且全是标点（或空白）则为「标点孤立行」（需并进邻行或在段级合并）。 */
  function storyLineLooksLikeOnlyPunctuationMarks(trimmedLine) {
    const t = String(trimmedLine || "").trim();
    if (!t) return false;
    if (/[0-9A-Za-z\u4e00-\u9fff]/.test(t)) return false;
    return /^[\s\p{P}]+$/u.test(t);
  }

  /** 把「独占一行的零散标点」贴回上一行行末（避免单列一个「。」）；无上一行则丢弃该行。 */
  function mergeStandaloneMarkLinesIntoAdjacent(text) {
    const raw = String(text || "").replace(/\r\n/g, "\n");
    if (!raw.includes("\n")) {
      const lone = raw.trim();
      if (!lone.length) return raw;
      if (storyLineLooksLikeOnlyPunctuationMarks(lone)) return "";
      return raw;
    }
    const lines = raw.split("\n");
    const out = [];
    for (let li = 0; li < lines.length; li++) {
      const line = lines[li];
      const trimmed = String(line || "").trim();
      if (storyLineLooksLikeOnlyPunctuationMarks(trimmed)) {
        if (!out.length) continue;
        const prev = String(out[out.length - 1] || "");
        if (/^[。．]+$/.test(trimmed) && lineEndsWithDialogueClosing(prev)) continue;
        out[out.length - 1] = prev.replace(/\s+$/u, "") + trimmed;
        continue;
      }
      out.push(line);
    }
    return out.join("\n");
  }

  /** stripStandalonePeriodOnlyLines 现改为合并零散标点行，名称保留以兼容旧调用。 */
  function stripStandalonePeriodOnlyLines(text) {
    return mergeStandaloneMarkLinesIntoAdjacent(text);
  }

  /** 引号内已以「。」结尾时，去掉紧挨在闭引号后的重复句号（模型常见输出；避免单独 rendered 成多一行「。」） */
  function collapseDuplicatePeriodAfterClosingQuote(s) {
    return String(s || "").replace(
      /(。)([\u300d\u201d"])\s*([。．])(?=\s|$|[\r\n\u4e00-\u9fff「“])/gu,
      "$1$2"
    );
  }

  /** 上一行行末是否为对白闭引（弯引号角引与半角直引号）；用于判断是否丢弃下一行孤立句号 */
  function lineEndsWithDialogueClosing(prevLine) {
    const t = String(prevLine || "").replace(/\s+$/u, "");
    if (!t) return false;
    return /[\u300d\u201d"]$/u.test(t);
  }

  /**
   * 闭引号行之后单独占一行的「。」（仅句末点号）常为模型冗余；与用户「引号后不再保留句号」一致，整行删除。
   * 单换行在 pre-wrap 下也会把该句号提成单独一行。
   */
  function stripOrphanSentencePeriodLinesAfterClosingQuote(text) {
    const raw = String(text || "").replace(/\r\n/g, "\n");
    if (!raw.includes("\n")) return raw;
    const lines = raw.split("\n");
    const out = [];
    for (let li = 0; li < lines.length; li++) {
      const line = lines[li];
      const trimmed = line.trim();
      const onlyCnPeriod = /^[。．]+$/.test(trimmed);
      if (onlyCnPeriod && out.length && lineEndsWithDialogueClosing(out[out.length - 1])) {
        continue;
      }
      out.push(line);
    }
    return out.join("\n");
  }

  /** 整块「段落」里没有正文只有标点时并入上一段；或由多个孤立标点构成的极短伪段也并入。 */
  function mergeOrphanPunctuationOnlyParagraphs(paras) {
    const out = [];
    for (let i = 0; i < paras.length; i++) {
      const p = String(paras[i] || "").trim();
      if (!p) continue;
      const onlyMarks =
        !/[0-9A-Za-z\u4e00-\u9fff]/u.test(p) && /^[\s\p{P}]{1,12}$/u.test(p.trim());
      if ((/^[。．，,！？!?；：…、]+$/.test(p) || onlyMarks) && out.length) {
        const prev = String(out[out.length - 1] || "");
        if (/^[。．]+$/.test(p) && lineEndsWithDialogueClosing(prev)) {
          continue;
        }
        out[out.length - 1] = out[out.length - 1] + p;
        continue;
      }
      out.push(p);
    }
    return out;
  }

  /**
   * 从字符串末尾向前吞掉「句末类标点」连续串，若长度≥2 则压成单一收束标点。
   */
  function squashTrailingRepeatedSentenceEndingMarksLoop(innerNoCloseQuote) {
    let result = String(innerNoCloseQuote || "");
    let guard = 0;
    while (guard++ < 32) {
      let i = result.length - 1;
      while (i >= 0 && /\s/.test(result.charAt(i))) i--;
      let j = i;
      while (j >= 0 && /[。.．!?！?\u3001,，…⋯、；;：:]/.test(result.charAt(j))) j--;
      const runPlain = result
        .slice(j + 1, i + 1)
        .replace(/\s+/g, "");
      const arr = Array.from(runPlain);
      if (arr.length <= 1) break;
      let keep = arr[arr.length - 1];
      if (
        arr.every(function (c) {
          return c === arr[0];
        })
      ) {
        keep = arr[0];
      } else {
        keep =
          arr.find(function (c) {
            return /[!！]/.test(c);
          }) ||
          arr.find(function (c) {
            return /[?？]/.test(c);
          }) ||
          arr.find(function (c) {
            return /[。.．]/.test(c);
          }) ||
          arr.find(function (c) {
            return /[…⋯]/.test(c);
          }) ||
          arr.find(function (c) {
            return /[,，、]/.test(c);
          }) ||
          arr[arr.length - 1];
      }
      const headSlice = result.slice(0, j + 1);
      const nextTry = collapseDuplicatePeriodAfterClosingQuote(headSlice + keep);
      if (nextTry === result) break;
      result = nextTry;
    }
    return result;
  }

  /**
   * 去掉行尾连续的句末类标点，只留一个；末尾可跟闭引号「」” 等（先剥闭引再压缩，再贴回）。
   */
  function collapseTrailingDuplicateSentenceMarksOnLine(lineSegment) {
    const origLine = String(lineSegment || "").replace(/\r/g, "");
    const padMatch = origLine.match(/\s*$/);
    const rightPad = padMatch ? padMatch[0] : "";
    const span = origLine.length - rightPad.length;
    let body = origLine.slice(0, span).replace(/\s+$/u, "");
    if (!body.length) return origLine;

    let closeTail = "";
    const closerRe = /^[」』）)\]\u301d\u201d"']$/;
    for (;;) {
      const parts = Array.from(body);
      const last = parts.length ? parts[parts.length - 1] : "";
      if (!last || !closerRe.test(last)) break;
      closeTail = last + closeTail;
      body = parts.slice(0, -1).join("").replace(/\s+$/u, "");
    }

    let core = squashTrailingRepeatedSentenceEndingMarksLoop(body);
    core = collapseDuplicatePeriodAfterClosingQuote(core);
    return core + closeTail + rightPad;
  }

  function applySentenceMarkCollapseAcrossLinesInParagraph(blob) {
    return String(blob || "")
      .replace(/\r/g, "\n")
      .split("\n")
      .map(collapseTrailingDuplicateSentenceMarksOnLine)
      .join("\n");
  }

  function isOpeningQuoteCharForParagraphStart(ch) {
    if (!ch) return false;
    return (
      ch === "\u300c" ||
      ch === "\u201c" ||
      ch === "\u2018" ||
      ch === '"' ||
      ch === "'"
    );
  }

  function stripLeadingPunctuationExceptOpeningQuotes(para) {
    let s = String(para || "").replace(/\r\n/g, "\n").trim();
    if (!s) return "";
    s = s.replace(/^[\uFEFF\u200B-\u200D\u2060]+/, "");
    while (s.length) {
      const cp = s.codePointAt(0);
      if (cp === undefined) break;
      const ch = String.fromCodePoint(cp);
      if (isOpeningQuoteCharForParagraphStart(ch)) break;
      if (!/^[\p{P}\p{S}]/u.test(ch)) break;
      s = s.slice(ch.length).replace(/^[ \t\u00a0\u3000]+/, "");
    }
    return s.trim();
  }

  /**
   * 软换行（单 \\n）下的行首若以句读/符号起笔且非开引号，显示时剥掉；整行只剩标点的行直接丢弃。
   * 解决 pre-wrap 下「。」单独占行或「。他」折行等错版；仅影响渲染管线，不改库存原文。
   */
  function sanitizeStorySoftNewlineLineStartsForDisplay(text) {
    const raw = String(text || "").replace(/\r/g, "\n");
    const lines = raw.split("\n");
    const out = [];
    for (let li = 0; li < lines.length; li++) {
      const line = lines[li];
      const trimmedOrig = String(line || "").trim();
      if (!trimmedOrig) {
        out.push(line);
        continue;
      }
      const m = line.match(/^([\t \u3000]*)([\s\S]*)$/);
      const indent = m ? m[1] : "";
      let body = m ? m[2] : line;
      body = stripLeadingPunctuationExceptOpeningQuotes(body);
      const merged = indent + body;
      if (!merged.trim()) continue;
      out.push(merged);
    }
    return out.join("\n");
  }

  /**
   * 段落首不得以逗号、句号等句读起笔（允许的段首标点仅为引号：“‘ 与半角 "'）；
   * 合并「单独成行仅含句读」的段落，避免模型把句号甩成新行。
   */
  function normalizeStoryParagraphLeadingPunctuation(text) {
    let raw = String(text || "").replace(/\r\n/g, "\n").trim();
    if (!raw) return "";
    raw = sanitizeStorySoftNewlineLineStartsForDisplay(raw).trim();
    if (!raw) return "";
    raw = stripStandalonePeriodOnlyLines(raw).trim();
    if (!raw) return "";
    raw = stripOrphanSentencePeriodLinesAfterClosingQuote(raw);
    const paras = raw
      .split(/\n\s*\n+/)
      .map(function (seg) {
        return String(seg || "").trim();
      })
      .filter(Boolean);
    return mergeOrphanPunctuationOnlyParagraphs(paras)
      .map(stripLeadingPunctuationExceptOpeningQuotes)
      .map(applySentenceMarkCollapseAcrossLinesInParagraph)
      .filter(Boolean)
      .join("\n\n");
  }

  /**
   * 展示管尾巴：fixColon / 句号折叠之后偶发残留段首/行首句读；再剥一层并与保存口径一致。
   */
  function finalizeStoryPlainLeadingHygiene(text) {
    let s = String(text || "").replace(/\r/g, "\n");
    const lines = s.split("\n");
    const linesOut = [];
    for (let li = 0; li < lines.length; li++) {
      const line = lines[li];
      const trimmedOrig = String(line || "").trim();
      if (!trimmedOrig) {
        linesOut.push(line);
        continue;
      }
      const m = line.match(/^([\t \u3000]*)([\s\S]*)$/);
      const indent = m ? m[1] : "";
      let body = m ? m[2] : line;
      body = body.replace(/^[\uFEFF\u200B-\u200D\u2060]+/, "");
      body = stripLeadingPunctuationExceptOpeningQuotes(body);
      linesOut.push(indent + body);
    }
    s = linesOut.join("\n").trim();
    const paras = s.split(/\n\s*\n+/).map(function (seg) {
      const t = String(seg || "").trim();
      if (!t) return "";
      return stripLeadingPunctuationExceptOpeningQuotes(t);
    });
    return paras.filter(Boolean).join("\n\n");
  }

  /**
   * 「…」内侧规范化：若已为成对白弯引号则只剥外层直角引号，不再外包一层（避免「“…”」→““…””）。
   */
  function normalizeCornerBracketPairInner(innerRaw) {
    let t = String(innerRaw || "").replace(/\r/g, "").trim();
    if (!t) return "";

    while (t.startsWith("\u300c") && t.endsWith("\u300d")) {
      const next = t.slice(1, -1).trim();
      if (!next || next.length >= t.length) break;
      t = next;
    }

    if (t.startsWith("\u201c") && t.endsWith("\u201d")) {
      const mid = t.slice(1, -1);
      if (mid.indexOf("\u201c") === -1 && mid.indexOf("\u201d") === -1) {
        return "\u201c" + mid.trim() + "\u201d";
      }
    }

    if (t.length >= 2 && t.charAt(0) === '"' && t.charAt(t.length - 1) === '"') {
      return "\u201c" + t.slice(1, -1).trim() + "\u201d";
    }

    return "\u201c" + t + "\u201d";
  }

  /**
   * 展示层：将成对直角引号「…」转为弯引号对白；未配对「保留原样。
   */
  function normalizeCornerBracketsToCurlyQuotes(raw) {
    const s = String(raw || "");
    let out = "";
    let i = 0;
    while (i < s.length) {
      const ch = s[i];
      if (ch === "\u300c") {
        let j = i + 1;
        while (j < s.length && s[j] !== "\u300d") j++;
        if (j < s.length) {
          const converted = normalizeCornerBracketPairInner(s.slice(i + 1, j));
          if (converted) out += converted;
          i = j + 1;
          continue;
        }
      }
      out += ch;
      i++;
    }
    return out;
  }

  /** 收敛历史输出或异常叠加产生的连续双层弯引号 ““…”” → “…” */
  function collapseDoubleCurlyQuoteWrappers(s) {
    let t = String(s || "");
    for (let guard = 0; guard < 24; guard++) {
      const next = t.replace(/\u201c\u201c([\s\S]*?)\u201d\u201d/g, function (_w, mid) {
        return "\u201c" + String(mid || "").trim() + "\u201d";
      });
      if (next === t) break;
      t = next;
    }
    return t;
  }

  /** 卡片/分享图正文：与 renderStoryInlineMarkup 相同的纯文本规范化（段首句读、孤立标点行等）；保留双星号、双下划线粗体标记供渲染。 */
  function normalizeStoryPlainTextForLayout(raw) {
    const src = String(raw || "").replace(/\r\n/g, "\n").trim();
    if (!src) return "";
    const quoted = collapseDoubleCurlyQuoteWrappers(normalizeCornerBracketsToCurlyQuotes(src)).trim();
    if (!quoted) return "";
    const body = collapseDuplicatePeriodAfterClosingQuote(
      fixColonPeriodBeforeCurlyQuote(normalizeStoryParagraphLeadingPunctuation(quoted))
    );
    return finalizeStoryPlainLeadingHygiene(body);
  }

  /** 将 **粗体** 与 __粗体__ 转为 &lt;strong&gt;，其余转义；支持自定义字体下 font-synthesis 加粗。 */
  function escapeHtmlWithInlineBold(text) {
    const s = String(text || "");
    if (!s) return "";
    if (s.indexOf("**") < 0 && s.indexOf("__") < 0) return escapeHtml(s);
    function splitByDelimiter(str, delim) {
      const L = delim.length;
      const chunks = [];
      let i = 0;
      while (i < str.length) {
        const a = str.indexOf(delim, i);
        if (a < 0) {
          chunks.push({ bold: false, t: str.slice(i) });
          break;
        }
        if (a > i) chunks.push({ bold: false, t: str.slice(i, a) });
        const b = str.indexOf(delim, a + L);
        if (b < 0) {
          chunks.push({ bold: false, t: str.slice(a) });
          break;
        }
        chunks.push({ bold: true, t: str.slice(a + L, b) });
        i = b + L;
      }
      return chunks;
    }
    function expandNonBoldFragment(frag) {
      if (frag.indexOf("__") < 0) return escapeHtml(frag);
      return splitByDelimiter(frag, "__")
        .map(function (seg) {
          return seg.bold ? "<strong>" + escapeHtml(seg.t) + "</strong>" : escapeHtml(seg.t);
        })
        .join("");
    }
    return splitByDelimiter(s, "**")
      .map(function (seg) {
        if (seg.bold) return "<strong>" + escapeHtml(seg.t) + "</strong>";
        return expandNonBoldFragment(seg.t);
      })
      .join("");
  }

  function renderStoryInlineMarkup(text) {
    const plain = normalizeStoryPlainTextForLayout(String(text || ""));
    if (!plain) return "";
    const dialoguePunctRe = /[，。！？；：…!?]/;

    function quoteInnerFromFull(qfull) {
      const q = String(qfull || "");
      if (/^「/.test(q) && /」$/.test(q)) return q.slice(1, -1).trim();
      if (/^“/.test(q) && /”$/.test(q)) return q.slice(1, -1).trim();
      if (/^"/.test(q) && /"$/.test(q)) return q.slice(1, -1).trim();
      return q.trim();
    }

    function splitParagraphByQuotes(paragraphText) {
      const text = String(paragraphText || "");
      const pieces = [];
      let i = 0;
      while (i < text.length) {
        const ch = text[i];
        if (ch !== "「" && ch !== "“" && ch !== '"') {
          let j = i + 1;
          while (j < text.length && text[j] !== "「" && text[j] !== "“" && text[j] !== '"') j++;
          pieces.push({ kind: "plain", text: text.slice(i, j) });
          i = j;
          continue;
        }
        const closeCh = ch === "「" ? "」" : ch === "“" ? "”" : '"';
        let j = i + 1;
        while (j < text.length && text[j] !== closeCh) j++;
        if (j >= text.length) {
          pieces.push({ kind: "plain", text: text.slice(i) });
          break;
        }
        const qfull = text.slice(i, j + 1);
        const inner = quoteInnerFromFull(qfull);
        if (dialoguePunctRe.test(inner)) pieces.push({ kind: "dialogue", text: qfull });
        else pieces.push({ kind: "term", text: qfull });
        i = j + 1;
      }
      return pieces;
    }

    function renderNarrativePara(textLine) {
      const parts = splitParagraphByQuotes(textLine);
      let html = "";
      parts.forEach(function (p) {
        if (p.kind === "plain") {
          const esc = escapeHtmlWithInlineBold(p.text);
          if (esc) html += '<em class="story-narr">' + esc + "</em>";
        } else if (p.kind === "term") {
          html += '<span class="story-inline-term">' + escapeHtmlWithInlineBold(p.text) + "</span>";
        }
      });
      const trimmed = html.trim();
      if (!trimmed) return "";
      return '<p class="story-para">' + html + "</p>";
    }

    const paragraphs = plain
      .split(/\n\s*\n+/)
      .map(function (seg) {
        return String(seg || "").trim();
      })
      .filter(Boolean);
    const rendered = [];
    paragraphs.forEach(function (para) {
      const parts = splitParagraphByQuotes(para);
      let buffer = "";
      parts.forEach(function (p) {
        if (p.kind === "dialogue") {
          const narrHtml = renderNarrativePara(buffer);
          if (narrHtml) rendered.push(narrHtml);
          buffer = "";
          rendered.push(
            '<p class="story-dialogue"><span class="story-dialogue__body">' +
              escapeHtmlWithInlineBold(p.text) +
              "</span></p>"
          );
        } else {
          buffer += p.text;
        }
      });
      const tailHtml = renderNarrativePara(buffer);
      if (tailHtml) rendered.push(tailHtml);
    });
    return rendered.join("");
  }

  function storyLineHasHighlightOrThought(plot, lineObj) {
    if (!plot || !lineObj || lineObj.id == null || String(lineObj.id) === "") return false;
    const lid = String(lineObj.id || "");
    return (
      (plot.storyHighlights || []).some(function (h) {
        return h && String(h.lineId || "") === lid;
      }) ||
      (plot.storyThoughts || []).some(function (t) {
        return t && String(t.lineId || "") === lid;
      })
    );
  }

  function storyTurnLineShowsParticipantBubble(plot, lineObj) {
    const isNarratorLine = !lineObj.characterId || lineObj.characterId === "narrator";
    if (isNarratorLine) return false;
    if (isEphemeralStoryNpcId(lineObj.characterId)) return true;
    return isPlotStoryParticipant(plot, lineObj.characterId);
  }

  function storyTurnLineEditing(plot, turnIndex, lineIndex) {
    return (
      storyLineEditState &&
      storyLineEditState.plotId === plot.id &&
      storyLineEditState.turnIndex === turnIndex &&
      storyLineEditState.lineIndex === lineIndex
    );
  }

  /** 该行是否为紧邻上一条角色气泡后的「氛围/旁白尾」（已并入上卡展示，非独立旁白段） */
  function isStoryAmbienceOfPriorParticipant(turnLines, lineIdx, plot, turnIndex) {
    if (lineIdx <= 0) return false;
    const prevPartIdx = lineIdx - 1;
    if (!storyTurnLineShowsParticipantBubble(plot, turnLines[prevPartIdx])) return false;
    const amb = gatherTrailingAmbiencePack(turnLines, prevPartIdx, plot, turnIndex);
    return amb.indices.indexOf(lineIdx) >= 0;
  }

  /** 旁白 pack 起始行：向前合并连续旁白，但不跨入上一张角色卡的氛围尾 */
  function findNarrOnlyPackStart(turnLines, lineIndex, plot, turnIndex) {
    let start = lineIndex;
    while (start > 0) {
      const prevIdx = start - 1;
      if (isStoryAmbienceOfPriorParticipant(turnLines, prevIdx, plot, turnIndex)) break;
      const prevLine = turnLines[prevIdx];
      if (storyTurnLineShowsParticipantBubble(plot, prevLine)) break;
      if (storyLineHasHighlightOrThought(plot, prevLine)) break;
      if (storyTurnLineEditing(plot, turnIndex, prevIdx)) break;
      const nt = stripNarratorDisplayText(String(prevLine.text || "")).trim();
      if (!nt) break;
      start = prevIdx;
    }
    return start;
  }

  function applyStoryTurnChoicesStrip(text, turn) {
    let out = String(text || "");
    if (turn && turn.choices && turn.choices.length >= 2) {
      out = stripTrailingInlineNumberedChoicesFromText(out, turn.choices).trim();
    }
    return out;
  }

  function buildNarrOnlyPackMergedText(turnLines, indices, turn) {
    const narrParts = indices
      .map(function (idx) {
        return stripNarratorDisplayText(String(turnLines[idx].text || ""));
      })
      .filter(function (t) {
        return String(t || "").trim();
      });
    return applyStoryTurnChoicesStrip(narrParts.join("\n\n"), turn);
  }

  /**
   * 角色气泡展示 pack：同角色连续气泡 + 其后可并行的氛围/旁白尾，供渲染/编辑/复制统一使用。
   */
  function gatherParticipantDisplayPack(turnLines, startIdx, plot, turnIndex) {
    const line = turnLines[startIdx];
    if (!line || !storyTurnLineShowsParticipantBubble(plot, line)) return null;
    let endIdx = startIdx;
    while (endIdx + 1 < turnLines.length) {
      const candLine = turnLines[endIdx + 1];
      if (!storyTurnLineShowsParticipantBubble(plot, candLine) || candLine.characterId !== line.characterId)
        break;
      if (storyTurnLineEditing(plot, turnIndex, endIdx + 1)) break;
      if (storyLineHasHighlightOrThought(plot, candLine)) break;
      endIdx++;
    }
    const amb = gatherTrailingAmbiencePack(turnLines, endIdx, plot, turnIndex);
    const participantIndices = [];
    for (let i = startIdx; i <= endIdx; i++) participantIndices.push(i);
    const allIndices = participantIndices.concat(amb.indices);
    const mergedParts = allIndices.map(function (idx) {
      return stripNarratorDisplayText(String(turnLines[idx].text || "")).trim();
    });
    return {
      startIdx: startIdx,
      endIdx: endIdx,
      participantIndices: participantIndices,
      ambienceIndices: amb.indices,
      allIndices: allIndices,
      resumeAt: amb.resumeAt,
      mergedText: mergedParts.filter(Boolean).join("\n\n"),
    };
  }

  function storyFeedPackLinesCanConsolidate(plot, turnLines, pack) {
    if (!pack || !Array.isArray(pack.allIndices) || pack.allIndices.length <= 1) return false;
    for (let i = 1; i < pack.allIndices.length; i++) {
      const line = turnLines[pack.allIndices[i]];
      if (line && storyLineHasHighlightOrThought(plot, line)) return false;
    }
    return true;
  }

  function consolidateStoryFeedPackOnSave(plot, turnIndex, pack, newText) {
    const turn = plot.playTurns && plot.playTurns[turnIndex];
    if (!turn || !pack || !Array.isArray(turn.lines)) return false;
    const lines = turn.lines;
    const primaryIdx = pack.startIdx != null ? pack.startIdx : pack.allIndices[0];
    const primaryLine = lines[primaryIdx];
    if (!primaryLine) return false;
    primaryLine.text = normalizeStoryPlainTextForLayout(newText);
    if (!storyFeedPackLinesCanConsolidate(plot, lines, pack)) {
      invalidateTurnInternalDigestFrom(plot, turnIndex);
      return true;
    }
    const removeIdx = pack.allIndices.slice(1).sort(function (a, b) {
      return b - a;
    });
    removeIdx.forEach(function (idx) {
      lines.splice(idx, 1);
    });
    invalidateTurnInternalDigestFrom(plot, turnIndex);
    return true;
  }

  function getStoryFeedLineDisplayText(plot, turnIndex, lineIndex) {
    const ctx = getLineContext(plot.id, turnIndex, lineIndex);
    if (!ctx || !ctx.line) return "";
    const turnLines = ctx.turn.lines || [];
    const line = ctx.line;
    if (storyTurnLineShowsParticipantBubble(plot, line)) {
      const pack = gatherParticipantDisplayPack(turnLines, lineIndex, plot, turnIndex);
      if (pack && String(pack.mergedText || "").trim()) return String(pack.mergedText).trim();
    } else {
      const packStart = findNarrOnlyPackStart(turnLines, lineIndex, plot, turnIndex);
      const narrPack = gatherConsecutiveNarrOnlyPack(turnLines, packStart, plot, turnIndex);
      if (narrPack.indices.indexOf(lineIndex) >= 0) {
        const merged = buildNarrOnlyPackMergedText(turnLines, narrPack.indices, ctx.turn);
        if (String(merged || "").trim()) return String(merged).trim();
      }
    }
    const raw = String(line.text || "").trim();
    if (storyTurnLineShowsParticipantBubble(plot, line)) return stripNarratorDisplayText(raw).trim() || raw;
    return stripNarratorDisplayText(raw).trim() || raw;
  }

  /**
   * 从 afterIdx 所指行之后开始，收集随其后的连续「非角色气泡」行（旁白/环境等），
   * 遇下一条角色气泡、正在编辑或有摘抄/想法标记即停止。用于并入上一条角色卡显示。
   */
  function gatherTrailingAmbiencePack(turnLines, afterIdx, plot, turnIndex) {
    const indices = [];
    let k = afterIdx + 1;
    while (k < turnLines.length) {
      const L = turnLines[k];
      if (storyTurnLineShowsParticipantBubble(plot, L)) break;
      if (storyTurnLineEditing(plot, turnIndex, k)) break;
      if (storyLineHasHighlightOrThought(plot, L)) break;
      const nt = stripNarratorDisplayText(String(L.text || "")).trim();
      if (nt) indices.push(k);
      k++;
    }
    return { indices: indices, resumeAt: k };
  }

  /**
   * 从 startIdx 起连续多条「非角色气泡」（旁白/环境等）合并为一块显示；规则与 gatherTrailingAmbiencePack 一致。
   */
  function gatherConsecutiveNarrOnlyPack(turnLines, startIdx, plot, turnIndex) {
    const indices = [];
    let k = startIdx;
    while (k < turnLines.length) {
      const L = turnLines[k];
      if (storyTurnLineShowsParticipantBubble(plot, L)) break;
      if (storyTurnLineEditing(plot, turnIndex, k)) break;
      if (storyLineHasHighlightOrThought(plot, L)) break;
      const nt = stripNarratorDisplayText(String(L.text || "")).trim();
      if (nt) indices.push(k);
      k++;
    }
    return { indices: indices, resumeAt: k };
  }

  function appendAmbienceTailToStoryMsg(msgRow, plot, turnLines, ambienceIndices, turnIndex) {
    if (!ambienceIndices.length) return;
    const texts = ambienceIndices.map(function (idx) {
      return stripNarratorDisplayText(String(turnLines[idx].text || ""));
    }).filter(function (t) {
      return String(t || "").trim();
    });
    if (!texts.length) return;
    const combined = texts.join("\n\n");
    const firstIdx = ambienceIndices[0];
    const firstLine = turnLines[firstIdx];
    const tail = document.createElement("div");
    tail.className =
      "story-msg__ambience story-feed-narr story-feed-narr--rp story-line-clickable";
    tail.innerHTML = renderStoryInlineMarkup(combined);
    applyStoryLineDecorations(tail, plot, String(firstLine.id || ""));
    msgRow.appendChild(tail);
    /** 氛围尾接在角色气泡后：不单独挂 line-id，按压/选区归属同一 story-feed-segment */
  }

  /** 剧情条：头像与昵称在上，正文在下全宽平铺。 */
  function buildStoryPlayParticipantShell(isMe, displayChar, ch, extraClasses, speakMeta) {
    const row = document.createElement("div");
    row.className =
      "story-msg story-msg--" + (isMe ? "me" : "npc") + (extraClasses ? " " + extraClasses : "");
    const innerRow = document.createElement("div");
    innerRow.className = "story-msg__row";
    const aside = document.createElement("div");
    aside.className = "story-msg__aside";
    const av = document.createElement("div");
    av.className = "avatar";
    fillAvatarElement(av, displayChar);
    if (speakMeta && !isMe) {
      av.classList.add("story-msg__avatar--speakable");
      av.setAttribute("role", "button");
      av.setAttribute("tabindex", "0");
      av.setAttribute("aria-label", "点击朗读对白");
      av.setAttribute("title", "点击朗读");
      av.setAttribute("data-story-speak-plot-id", speakMeta.plotId);
      av.setAttribute("data-story-speak-turn-index", String(speakMeta.turnIndex));
      av.setAttribute("data-story-speak-line-index", String(speakMeta.lineIndex));
      const asideTop = document.createElement("div");
      asideTop.className = "story-msg__aside-top";
      asideTop.appendChild(av);
      const voiceWave = document.createElement("div");
      voiceWave.className = "story-msg__voice-wave";
      voiceWave.hidden = true;
      voiceWave.setAttribute("aria-hidden", "true");
      voiceWave.innerHTML = "<span></span><span></span><span></span>";
      asideTop.appendChild(voiceWave);
      aside.appendChild(asideTop);
    } else {
      aside.appendChild(av);
    }
    const name = document.createElement("div");
    name.className = "story-msg__name";
    name.textContent = displayChar ? displayChar.name : ch ? ch.name : "未知";
    aside.appendChild(name);
    const body = document.createElement("div");
    body.className = "story-msg__body";
    innerRow.appendChild(aside);
    innerRow.appendChild(body);
    row.appendChild(innerRow);
    return { row: row, body: body };
  }


  function buildStoryPlayTurnGroupDom(p, turnIndex) {
    const turn = (p.playTurns || [])[turnIndex];
    if (!turn) return null;
    const pid = p.protagonistId;
    const turnGroup = document.createElement("section");
    turnGroup.className = "story-turn-group";
        turnGroup.id = "story-play-turn-" + String(turnIndex);
        turnGroup.setAttribute("data-turn-index", String(turnIndex));
        const turnActionText =
          turn && turn.triggerPlayerAction && String(turn.triggerPlayerAction.line || "").trim()
            ? String(turn.triggerPlayerAction.line || "").trim()
            : "";
        if (turnActionText) {
          const actionHint = document.createElement("div");
          actionHint.className = "story-turn-action-inline";
          actionHint.textContent = "<" + turnActionText + ">";
          turnGroup.appendChild(actionHint);
        }
        const turnLines = turn.lines || [];
        let lineIndex = 0;
        while (lineIndex < turnLines.length) {
          const line = turnLines[lineIndex];
          const showBubble = storyTurnLineShowsParticipantBubble(p, line);
          const rawText = line.text || "";
          const isEditing =
            storyLineEditState &&
            storyLineEditState.plotId === p.id &&
            storyLineEditState.turnIndex === turnIndex &&
            storyLineEditState.lineIndex === lineIndex;
          if (!showBubble) {
            if (isStoryAmbienceOfPriorParticipant(turnLines, lineIndex, p, turnIndex)) {
              lineIndex++;
              continue;
            }
            const narrText = stripNarratorDisplayText(rawText);
            if (!isEditing && !narrText) {
              lineIndex++;
              continue;
            }
            if (isEditing) {
              const narrPackStart = findNarrOnlyPackStart(turnLines, lineIndex, p, turnIndex);
              const narrEditFirstIdx =
                narrPackStart <= lineIndex &&
                gatherConsecutiveNarrOnlyPack(turnLines, narrPackStart, p, turnIndex).indices.indexOf(
                  lineIndex
                ) >= 0
                  ? narrPackStart
                  : lineIndex;
              const narrEditPack = gatherConsecutiveNarrOnlyPack(turnLines, narrEditFirstIdx, p, turnIndex);
              const narrEditFirstLine = turnLines[narrEditFirstIdx];
              const wrap = document.createElement("div");
              wrap.className = "story-line-edit-inline-wrap";
              wrap.setAttribute("data-story-line-id", String(narrEditFirstLine.id || ""));
              markStoryFeedSegment(wrap);
              const editable = document.createElement("div");
              editable.className = "story-feed-narr story-feed-narr--rp story-line-editable-inline";
              editable.setAttribute("role", "textbox");
              editable.setAttribute("aria-label", "编辑剧情正文");
              editable.setAttribute("contenteditable", "true");
              editable.setAttribute("spellcheck", "false");
              let narrEditSrc = buildNarrOnlyPackMergedText(turnLines, narrEditPack.indices, turn);
              if (!String(narrEditSrc || "").trim()) narrEditSrc = narrText;
              editable.innerHTML = renderStoryInlineMarkup(narrEditSrc || narrText || rawText);
              applyStoryLineDecorations(editable, p, String(narrEditFirstLine.id || ""));
              const actions = document.createElement("div");
              actions.className = "story-line-edit-actions";
              const btnSave = document.createElement("button");
              btnSave.type = "button";
              btnSave.className = "btn btn--primary btn--pill story-line-edit-btn story-line-edit-btn--small";
              btnSave.textContent = "保存";
              const btnCancel = document.createElement("button");
              btnCancel.type = "button";
              btnCancel.className = "btn btn--secondary btn--pill story-line-edit-btn story-line-edit-btn--small";
              btnCancel.textContent = "取消";
              bindStoryLineEditSaveCancel(btnSave, btnCancel, editable, p, turnIndex, narrEditFirstIdx, {
                startIdx: narrEditFirstIdx,
                allIndices: narrEditPack.indices,
              });
              actions.appendChild(btnSave);
              actions.appendChild(btnCancel);
              wrap.appendChild(editable);
              wrap.appendChild(actions);
              turnGroup.appendChild(wrap);
              requestAnimationFrame(function () {
                focusEditableToEnd(editable);
              });
              lineIndex = narrEditPack.resumeAt;
              continue;
            }
            var narrRun = gatherConsecutiveNarrOnlyPack(turnLines, lineIndex, p, turnIndex);
            if (!narrRun.indices.length) {
              lineIndex = narrRun.resumeAt;
              continue;
            }
            let narrMerged = buildNarrOnlyPackMergedText(turnLines, narrRun.indices, turn);
            if (!String(narrMerged || "").trim()) {
              lineIndex = narrRun.resumeAt;
              continue;
            }
            const narrFirstIdx = narrRun.indices[0];
            const narrFirstLine = turnLines[narrFirstIdx];
            const narr = document.createElement("div");
            narr.className =
              "story-feed-narr story-feed-narr--rp" +
              (p.playSealed ? " story-feed-narr--readonly" : " story-line-clickable");
            narr.setAttribute("data-story-line-id", String(narrFirstLine.id || ""));
            markStoryFeedSegment(narr);
            narr.innerHTML = renderStoryInlineMarkup(narrMerged);
            applyStoryLineDecorations(narr, p, String(narrFirstLine.id || ""));
            if (!p.playSealed) {
              setStoryPlayLinePressMeta(narr, p, turnIndex, narrFirstIdx);
            }
            turnGroup.appendChild(narr);
            lineIndex = narrRun.resumeAt;
            continue;
          }
          const ch = getCharById(line.characterId);
          const displayChar = getStoryLineCharacterView(p, line);
          const isMe = line.characterId === pid;
          if (isEditing) {
            const editPack = gatherParticipantDisplayPack(turnLines, lineIndex, p, turnIndex);
            let editMergedText = editPack
              ? editPack.mergedText
              : stripNarratorDisplayText(rawText);
            editMergedText = applyStoryTurnChoicesStrip(editMergedText, turn);
            const shell = buildStoryPlayParticipantShell(
              isMe,
              displayChar,
              ch,
              "story-line-edit-outer",
              storySpeakMetaForLine(p, turnIndex, lineIndex, isMe, editMergedText || rawText)
            );
            const row = shell.row;
            row.setAttribute("data-story-line-id", String(line.id || ""));
            markStoryFeedSegment(row);
            if (!p.playSealed) {
              setStoryPlayLinePressMeta(row, p, turnIndex, lineIndex);
            }
            const col = document.createElement("div");
            col.className = "story-line-edit-msg-col";
            const editable = document.createElement("div");
            editable.className = "story-msg__text story-msg__text--rp story-line-editable-inline";
            editable.setAttribute("role", "textbox");
            editable.setAttribute("aria-label", "编辑角色台词");
            editable.setAttribute("contenteditable", "true");
            editable.setAttribute("spellcheck", "false");
            editable.innerHTML = renderStoryInlineMarkup(editMergedText || rawText);
            applyStoryLineDecorations(editable, p, String(line.id || ""));
            const actions = document.createElement("div");
            actions.className = "story-line-edit-actions";
            const btnSave = document.createElement("button");
            btnSave.type = "button";
            btnSave.className = "btn btn--primary btn--pill story-line-edit-btn story-line-edit-btn--small";
            btnSave.textContent = "保存";
            const btnCancel = document.createElement("button");
            btnCancel.type = "button";
            btnCancel.className = "btn btn--secondary btn--pill story-line-edit-btn story-line-edit-btn--small";
            btnCancel.textContent = "取消";
            bindStoryLineEditSaveCancel(
              btnSave,
              btnCancel,
              editable,
              p,
              turnIndex,
              lineIndex,
              editPack
            );
            actions.appendChild(btnSave);
            actions.appendChild(btnCancel);
            col.appendChild(editable);
            col.appendChild(actions);
            shell.body.appendChild(col);
            turnGroup.appendChild(row);
            requestAnimationFrame(function () {
              focusEditableToEnd(editable);
            });
            lineIndex = editPack ? editPack.resumeAt : lineIndex + 1;
            continue;
          }
          if (
            !storyTurnLineEditing(p, turnIndex, lineIndex) &&
            !storyLineHasHighlightOrThought(p, line)
          ) {
            var partPack = gatherParticipantDisplayPack(turnLines, lineIndex, p, turnIndex);
            if (
              partPack &&
              String(partPack.mergedText || "").trim() &&
              (partPack.participantIndices.length > 1 || partPack.ambienceIndices.length > 0)
            ) {
              var mergedParticipantText = applyStoryTurnChoicesStrip(partPack.mergedText, turn);
              var shellM = buildStoryPlayParticipantShell(
                isMe,
                displayChar,
                ch,
                p.playSealed ? "story-msg--readonly" : "story-line-clickable",
                storySpeakMetaForLine(p, turnIndex, lineIndex, isMe, mergedParticipantText)
              );
              var mergeRow = shellM.row;
              mergeRow.setAttribute("data-story-line-id", String(line.id || ""));
              markStoryFeedSegment(mergeRow);
              var mergeTxt = document.createElement("div");
              mergeTxt.className = "story-msg__text story-msg__text--rp";
              var bubbleOnlyParts = partPack.participantIndices.map(function (idx) {
                return stripNarratorDisplayText(String(turnLines[idx].text || "")).trim();
              });
              var bubbleOnlyText = applyStoryTurnChoicesStrip(
                bubbleOnlyParts.filter(Boolean).join("\n\n"),
                turn
              );
              mergeTxt.innerHTML = renderStoryInlineMarkup(bubbleOnlyText);
              applyStoryLineDecorations(mergeTxt, p, String(line.id || ""));
              shellM.body.appendChild(mergeTxt);
              if (!p.playSealed) {
                setStoryPlayLinePressMeta(mergeRow, p, turnIndex, lineIndex);
              }
              if (partPack.ambienceIndices.length) {
                appendAmbienceTailToStoryMsg(
                  mergeRow,
                  p,
                  turnLines,
                  partPack.ambienceIndices,
                  turnIndex
                );
              }
              turnGroup.appendChild(mergeRow);
              lineIndex = partPack.resumeAt;
              continue;
            }
          }
          var bubbleDisplayText = rawText;
          if (turn.choices && turn.choices.length >= 2) {
            bubbleDisplayText = stripTrailingInlineNumberedChoicesFromText(bubbleDisplayText, turn.choices).trim();
          }
          const shellN = buildStoryPlayParticipantShell(
            isMe,
            displayChar,
            ch,
            p.playSealed ? "story-msg--readonly" : "story-line-clickable",
            storySpeakMetaForLine(p, turnIndex, lineIndex, isMe, bubbleDisplayText || rawText)
          );
          const row = shellN.row;
          row.setAttribute("data-story-line-id", String(line.id || ""));
          markStoryFeedSegment(row);
          const txt = document.createElement("div");
          txt.className = "story-msg__text story-msg__text--rp";
          txt.innerHTML = renderStoryInlineMarkup(stripNarratorDisplayText(bubbleDisplayText || rawText));
          applyStoryLineDecorations(txt, p, String(line.id || ""));
          shellN.body.appendChild(txt);
          if (!p.playSealed) {
            setStoryPlayLinePressMeta(row, p, turnIndex, lineIndex);
          }
          var ambSingle = gatherTrailingAmbiencePack(turnLines, lineIndex, p, turnIndex);
          if (ambSingle.indices.length) {
            appendAmbienceTailToStoryMsg(row, p, turnLines, ambSingle.indices, turnIndex);
          }
          turnGroup.appendChild(row);
          lineIndex = ambSingle.resumeAt;
          continue;
        }
        if (turn.streaming && turn.streamPreviewLine) {
          const pline = turn.streamPreviewLine;
          const previewBubble = storyTurnLineShowsParticipantBubble(p, pline);
          const previewText = String(pline.text || "");
          if (previewBubble) {
            const pCh = getCharById(pline.characterId);
            const pDisplayChar = getStoryLineCharacterView(p, pline);
            const pIsMe = pline.characterId === pid;
            const shellP = buildStoryPlayParticipantShell(
              pIsMe,
              pDisplayChar,
              pCh,
              "story-play-stream-preview"
            );
            const pRow = shellP.row;
            markStoryFeedSegment(pRow);
            const pTxt = document.createElement("div");
            pTxt.className = "story-msg__text story-msg__text--rp";
            pTxt.innerHTML = renderStoryInlineMarkup(stripNarratorDisplayText(previewText));
            shellP.body.appendChild(pTxt);
            turnGroup.appendChild(pRow);
          } else {
            const pNarr = document.createElement("div");
            pNarr.className = "story-feed-narr story-feed-narr--rp story-play-stream-preview";
            markStoryFeedSegment(pNarr);
            pNarr.innerHTML = renderStoryInlineMarkup(stripNarratorDisplayText(previewText));
            turnGroup.appendChild(pNarr);
          }
        }

    return turnGroup.children.length ? turnGroup : null;
  }
  function renderStoryPlay(p) {
    const introEl = document.getElementById("story-play-intro");
    if (!introEl) return;
    ensurePlotExtendedState(p);
    if (storyLineEditState && storyLineEditState.plotId === p.id) {
      const ectx = getLineContext(p.id, storyLineEditState.turnIndex, storyLineEditState.lineIndex);
      if (!ectx) {
        storyLineEditState = null;
        hideStorySelectionBubble();
      }
    }
    const feedEarly = document.getElementById("story-play-feed");
    const turnsEarly = p.playTurns || [];
    const streamPatchOnlyIntro =
      !!p.playTurnInFlight &&
      turnsEarly.length > 0 &&
      turnsEarly[turnsEarly.length - 1].streaming &&
      feedEarly &&
      feedEarly.childElementCount > 0 &&
      !storyLineEditState;
    if (!streamPatchOnlyIntro) applyStoryBackground(p);
    const identityBlocks = getEffectiveIdentityBlocks(p);
    const era = String(identityBlocks.eraBlock || "").trim();
    const idSelf = String(identityBlocks.identitySelfBlock || "").trim();
    const idOthers = String(identityBlocks.identityOthersBlock || "").trim();
    if (!streamPatchOnlyIntro) {
    introEl.innerHTML = "";
    const eraParts = era ? splitSetupDisplayParagraphs(era) : [];
    if (eraParts.length === 0) {
      const b1 = document.createElement("div");
      b1.className = "story-intro-block story-intro-block--empty";
      b1.textContent = "时代与场景将由 API 生成…";
      introEl.appendChild(b1);
    } else {
      eraParts.forEach(function (chunk) {
        const blk = document.createElement("div");
        blk.className = "story-intro-block";
        blk.textContent = chunk;
        introEl.appendChild(blk);
      });
    }
    const selfChunks = splitStoryIdentitiesForBlocks(idSelf, p);
    if (selfChunks.length === 0) {
      const b2 = document.createElement("div");
      b2.className = "story-intro-block story-intro-block--empty";
      b2.textContent = "我的形象将由 API 生成…";
      introEl.appendChild(b2);
    } else {
      selfChunks.forEach(function (chunk) {
        const blk = document.createElement("div");
        blk.className = "story-intro-block";
        blk.textContent = chunk;
        introEl.appendChild(blk);
      });
    }
    const othersChunks = splitStoryIdentitiesForBlocks(idOthers, p);
    if (othersChunks.length === 0) {
      const b3 = document.createElement("div");
      b3.className = "story-intro-block story-intro-block--empty";
      b3.textContent = "其他角色将由 API 生成…";
      introEl.appendChild(b3);
    } else {
      othersChunks.forEach(function (chunk) {
        const blk = document.createElement("div");
        blk.className = "story-intro-block";
        blk.textContent = chunk;
        introEl.appendChild(blk);
      });
    }
    }

    const feed = document.getElementById("story-play-feed");
    if (feed) {
      ensureStoryLineIds(p);
      const turnsForFeed = p.playTurns || [];
      const streamPatchOnly =
        !!p.playTurnInFlight &&
        turnsForFeed.length > 0 &&
        turnsForFeed[turnsForFeed.length - 1].streaming &&
        feed.childElementCount > 0 &&
        !storyLineEditState;
      if (streamPatchOnly) {
        const ti = turnsForFeed.length - 1;
        const newGroup = buildStoryPlayTurnGroupDom(p, ti);
        const existing = document.getElementById("story-play-turn-" + ti);
        if (newGroup) {
          if (existing) existing.replaceWith(newGroup);
          else feed.appendChild(newGroup);
        } else if (existing) existing.remove();
      } else {
        feed.innerHTML = "";
        turnsForFeed.forEach(function (_turn, turnIndex) {
          const turnGroup = buildStoryPlayTurnGroupDom(p, turnIndex);
          if (turnGroup) feed.appendChild(turnGroup);
        });
      }
    }

    const playPanelEl = document.getElementById("story-panel-play");
    if (playPanelEl) playPanelEl.classList.toggle("story-panel--sealed-readonly", !!p.playSealed);
    const layerStoryEl = els.layerStory();
    if (layerStoryEl) layerStoryEl.classList.toggle("layer-story--sealed-play", !!p.playSealed);
    const searchToolBtn = els.storySearchBtn();
    const summaryBookBtn = els.storySummaryBook();
    if (searchToolBtn && playPanelEl && !playPanelEl.hidden) searchToolBtn.hidden = !!p.playSealed;
    if (summaryBookBtn && playPanelEl && !playPanelEl.hidden) summaryBookBtn.hidden = !!p.playSealed;
    const composerEl = document.querySelector("#story-panel-play .story-composer");
    if (composerEl) composerEl.hidden = !!p.playSealed;

    const choicesWrap = document.getElementById("story-play-choices");
    if (!choicesWrap) return;
    if (p.playSealed) {
      choicesWrap.hidden = true;
      choicesWrap.innerHTML = "";
      updateStoryScrollNav();
      return;
    }

    const isLoadingTurn =
      !!p.playTurnInFlight || !!p.playChoiceExpandInFlight || !!p.playChoicesRegenerateInFlight;
    const turnsForStream = p.playTurns || [];
    const streamTurn =
      p.playTurnInFlight && turnsForStream.length ? turnsForStream[turnsForStream.length - 1] : null;
    const streamHasVisibleLines =
      !!(
        streamTurn &&
        streamTurn.streaming &&
        ((streamTurn.lines && streamTurn.lines.length) || streamTurn.streamPreviewLine)
      );
    const showChoicesLoading = isLoadingTurn && !streamHasVisibleLines;
    choicesWrap.classList.toggle("story-play-choices--loading", isLoadingTurn);
    const sendBtn = document.getElementById("story-composer-send");
    if (sendBtn) sendBtn.disabled = isLoadingTurn;
    const apiBtn = document.getElementById("story-composer-api");
    if (apiBtn) apiBtn.disabled = isLoadingTurn;
    const input = document.getElementById("story-composer-input");
    if (input) input.disabled = isLoadingTurn;
    choicesWrap.innerHTML = "";

    if (showChoicesLoading) {
      choicesWrap.hidden = false;
      const prog = document.createElement("div");
      prog.className = "story-progress-indicator";
      prog.setAttribute("role", "status");
      prog.textContent = p.playChoicesRegenerateInFlight ? "正在重新生成选项…" : "正在推动剧情…";
      choicesWrap.appendChild(prog);
    } else if (isLoadingTurn && streamHasVisibleLines) {
      choicesWrap.hidden = false;
      const prog = document.createElement("div");
      prog.className = "story-progress-indicator";
      prog.setAttribute("role", "status");
      prog.textContent = "正在续写…";
      choicesWrap.appendChild(prog);
    } else {
      const plotRef = p;
      const turns = p.playTurns || [];
      const last = turns.length ? turns[turns.length - 1] : null;
      const chs = last && Array.isArray(last.choices) ? last.choices : [];
      const lastStoryLines = last && Array.isArray(last.lines) ? last.lines : [];
      const hasTurnStory = lastStoryLines.some(function (ln) {
        return ln && String(ln.text || "").trim();
      });
      if (chs.length) {
        choicesWrap.hidden = false;
        if (!hasTurnStory) {
          const warnHdr = document.createElement("div");
          warnHdr.className = "story-choices__label";
          warnHdr.textContent = "本回合正文未载入";
          choicesWrap.appendChild(warnHdr);
          const warnBody = document.createElement("div");
          warnBody.className = "story-progress-indicator";
          warnBody.setAttribute("role", "alert");
          warnBody.textContent =
            "仅有选项、没有剧情气泡，多为解析失败或旧数据异常。可点击下方按钮移除本回合，或重新进入剧情再试。";
          choicesWrap.appendChild(warnBody);
          const rm = document.createElement("button");
          rm.type = "button";
          rm.className = "btn story-footer-btn";
          rm.style.marginTop = "10px";
          rm.textContent = "移除本条空回合";
          rm.addEventListener("click", function () {
            const t = plotRef.playTurns || [];
            if (t.length && t[t.length - 1] === last) {
              t.pop();
              flushPersistNarrative();
              renderStoryPlay(plotRef);
              showToast("已移除该回合", "success");
            }
          });
          choicesWrap.appendChild(rm);
        } else {
          const hdr = document.createElement("div");
          hdr.className = "story-choices__label";
          hdr.textContent = "选择一项";
          choicesWrap.appendChild(hdr);
          chs.forEach(function (c, idx) {
            const btn = document.createElement("button");
            btn.type = "button";
            btn.className = "story-choice-row";
            const lineEl = document.createElement("div");
            lineEl.className = "story-choice-row__line";
            lineEl.textContent = (c && c.line) || "";
            btn.title = (c && c.hint) || "";
            btn.appendChild(lineEl);
            btn.addEventListener("click", function () {
              submitPlayerTurn(plotRef, { type: "choice", index: idx });
            });
            choicesWrap.appendChild(btn);
          });
          const actionRow = document.createElement("div");
          actionRow.className = "story-play-choice-actions";
          const svgRedoTurn =
            '<svg class="icon-linear" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M23 4v6h-6"/><path d="M1 20v-6h6"/><path d="M3.51 9a9 9 0 0114.85-3.36L23 10"/><path d="M1 14l4.64 4.36A9 9 0 0020.49 15"/></svg>';
          const svgRedoChoices =
            '<svg class="icon-linear" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="3" y="3" width="18" height="18" rx="2.5"/><circle cx="8.75" cy="8.75" r="1.65" fill="currentColor" stroke="none"/><circle cx="15.25" cy="15.25" r="1.65" fill="currentColor" stroke="none"/><circle cx="12" cy="12" r="1.65" fill="currentColor" stroke="none"/></svg>';
          const svgAutoAdvance =
            '<svg class="icon-linear" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 3.5l1.65 4.85 4.85 1.65-4.85 1.65L12 16.5l-1.65-4.85L5.5 10l4.85-1.65L12 3.5z"/><path d="M5 16.5l.75 2.25L8 19.5l-2.25.75L5 22.5l-.75-2.25L2 19.5l2.25-.75L5 16.5z"/></svg>';
          const btnRedoTurn = document.createElement("button");
          btnRedoTurn.type = "button";
          btnRedoTurn.className = "story-choice-action-btn";
          btnRedoTurn.setAttribute("aria-label", "重生成本轮剧情与选项");
          btnRedoTurn.title = "重生成本轮剧情与选项";
          btnRedoTurn.innerHTML = svgRedoTurn;
          btnRedoTurn.addEventListener("click", function () {
            void regenerateLastStoryTurn(plotRef);
          });
          const btnRedoChoicesOnly = document.createElement("button");
          btnRedoChoicesOnly.type = "button";
          btnRedoChoicesOnly.className = "story-choice-action-btn";
          btnRedoChoicesOnly.setAttribute("aria-label", "仅重新生成选项");
          btnRedoChoicesOnly.title = "仅重新生成选项";
          btnRedoChoicesOnly.innerHTML = svgRedoChoices;
          btnRedoChoicesOnly.addEventListener("click", function () {
            void regenerateLastTurnChoices(plotRef);
          });
          const btnAutoAdvance = document.createElement("button");
          btnAutoAdvance.type = "button";
          btnAutoAdvance.className = "story-choice-action-btn";
          btnAutoAdvance.setAttribute("aria-label", "自动推进一轮剧情");
          btnAutoAdvance.title = "自动推进一轮剧情";
          btnAutoAdvance.innerHTML = svgAutoAdvance;
          btnAutoAdvance.addEventListener("click", function () {
            plotRef.pendingPlayerTurnAction = null;
            void requestNextStoryTurn(plotRef);
          });
          actionRow.appendChild(btnRedoTurn);
          actionRow.appendChild(btnRedoChoicesOnly);
          actionRow.appendChild(btnAutoAdvance);
          choicesWrap.appendChild(actionRow);
        }
      } else {
        choicesWrap.hidden = true;
      }
    }
    updateStoryScrollNav();
  }

  function updateStoryScrollNav() {
    const scrollEl = document.getElementById("story-play-scroll");
    const nav = document.getElementById("story-scroll-nav");
    const btnLatest = document.getElementById("story-scroll-latest");
    const playPanel = document.getElementById("story-panel-play");
    if (!scrollEl || !nav || !btnLatest) return;
    if (!playPanel || playPanel.hidden) {
      nav.hidden = true;
      btnLatest.hidden = true;
      return;
    }
    const remains = scrollEl.scrollHeight - scrollEl.scrollTop - scrollEl.clientHeight;
    const notAtBottom = remains > 24;
    btnLatest.hidden = !notAtBottom;
    nav.hidden = btnLatest.hidden;
  }

  function scrollStoryPlayToLatest(smooth) {
    const scrollEl = document.getElementById("story-play-scroll");
    if (!scrollEl) return;
    scrollEl.scrollTo({ top: scrollEl.scrollHeight, behavior: smooth ? "smooth" : "auto" });
    updateStoryScrollNav();
  }

  /** AI 新回合落地后：将本回合首条剧情滚至剧情滚动区顶部附近，便于立刻看到新生成内容 */
  function scrollStoryPlayNewTurnToTop(plot, firstLineId) {
    const scrollEl = document.getElementById("story-play-scroll");
    const playPanel = document.getElementById("story-panel-play");
    if (!scrollEl || !playPanel || playPanel.hidden) return;
    if (!plot || String(lastStoryPlotId || "") !== String(plot.id || "")) return;
    let target = null;
    const lid = String(firstLineId || "").trim();
    if (lid) {
      try {
        target = scrollEl.querySelector(
          '[data-story-line-id="' + lid.replace(/\\/g, "\\\\").replace(/"/g, '\\"') + '"]'
        );
      } catch (_) {
        target = null;
      }
    }
    if (!target) {
      const turns = plot.playTurns || [];
      const ti = turns.length - 1;
      if (ti >= 0) target = document.getElementById("story-play-turn-" + String(ti));
    }
    if (!target) return;
    const pad = 8;
    const rel =
      target.getBoundingClientRect().top - scrollEl.getBoundingClientRect().top + scrollEl.scrollTop;
    scrollEl.scrollTop = Math.max(0, rel - pad);
    updateStoryScrollNav();
  }

  /** 由回合气泡拼成可供模型参照的剧情节选（选项重生时用） */
  function buildSceneTextFromTurnLines(lines) {
    return (lines || [])
      .map(function (line) {
        return storyLineHistoryPrefix(line) + String(line.text || "");
      })
      .join("\n");
  }

  /** 删掉最后一回合并按入库时的触发动作重新生成正文+选项（首轮无触发则空头档继续生成） */
  async function regenerateLastStoryTurn(plot) {
    if (!plot || plot.playSealed || plot.playTurnInFlight || plot.playChoicesRegenerateInFlight || plot.playChoiceExpandInFlight)
      return;
    const turns = plot.playTurns || [];
    if (!turns.length) {
      showToast("暂无回合可重生", "info", 2200);
      return;
    }
    const last = turns[turns.length - 1];
    const trig = last.triggerPlayerAction || null;
    turns.pop();
    plot.pendingPlayerTurnAction = trig
      ? {
          type: String(trig.type || "text"),
          line: cleanStoryLine(trig.line || ""),
          hint: cleanStoryLine(trig.hint || ""),
        }
      : null;
    flushPersistNarrative();
    renderStoryPlay(plot);
    await requestNextStoryTurn(plot);
  }

  /** 保留最后一回合正文，仅重新请求选项 */
  async function regenerateLastTurnChoices(plot) {
    if (!plot || plot.playSealed || plot.playTurnInFlight || plot.playChoicesRegenerateInFlight || plot.playChoiceExpandInFlight)
      return;
    const turns = plot.playTurns || [];
    const last = turns.length ? turns[turns.length - 1] : null;
    if (!last || !Array.isArray(last.lines)) {
      showToast("没有可依据的正文", "info", 2200);
      return;
    }
    const hasStory = last.lines.some(function (ln) {
      return ln && String(ln.text || "").trim();
    });
    if (!hasStory) {
      showToast("本回合尚无剧情正文", "info", 2200);
      return;
    }
    plot.playChoicesRegenerateInFlight = true;
    storyAiWakeLockAcquire();
    renderStoryPlay(plot);
    try {
      const scene = buildSceneTextFromTurnLines(last.lines);
      const snippet = scene.trim().slice(-2400);
      const rescueProtag = getCharById(plot.protagonistId);
      const rescuePovLine = normalizeNarrativePov(plot && plot.pov ? plot.pov : "第三人称");
      const rescuePovConstraint = buildPovHardConstraint(
        rescuePovLine,
        rescueProtag && rescueProtag.name ? rescueProtag.name : ""
      );
      const rescueRaw = await callChatCompletion(
        [
          {
            role: "system",
            content:
              "根据剧情结尾补玩家可选行动。" +
              rescuePovConstraint +
              " 每条只写动作或对白，不要写主视角姓名；勿以配角作主语起句。每行恰好一条独立选择：禁止把多句对白或「对白+动作」写在同一行。只输出多行中文短句，每行一条；至少两条；不要序号、标题或解释。",
          },
          {
            role: "user",
            content:
              "叙事视角：" +
              rescuePovLine +
              "\n\n剧情节选：\n" +
              snippet +
              "\n\n请输出选项（每行仅一条独立选择，至少两条）：",
          },
        ],
        0.72,
        1040,
        { skipGenPaw: true }
      );
      const rescueParsed = sanitizeStoryChoices(parseStoryChoices(rtxt, rtxt));
      if (!Array.isArray(rescueParsed) || rescueParsed.length < 2) {
        throw new Error("未能生成足够选项");
      }
      last.choices = rescueParsed.slice();
      plot.lastGeneratedAt = Date.now();
      showToast("已重新生成选项", "success");
      flushPersistNarrative();
    } catch (err) {
      console.error("重新生成选项失败:", err);
      showToast(err && err.message ? err.message : "重新生成选项失败", "error", 3800);
    } finally {
      plot.playChoicesRegenerateInFlight = false;
      storyAiWakeLockRelease();
      renderStoryPlay(plot);
      flushPersistNarrative();
    }
  }

  /** 续写失败时把本条「自由输入」原样写回剧情底部输入框（选项点击不产生草稿）。 */
  function restoreStoryComposerInputAfterPlayFailureFromPendingSnap(snap) {
    if (!snap || String(snap.type || "") !== "text") return;
    const draft =
      typeof snap.composerRestoreDraft === "string"
        ? snap.composerRestoreDraft
        : String(snap.line || "");
    const el = document.getElementById("story-composer-input");
    if (!el) return;
    el.value = draft;
    try {
      el.focus();
      const n = draft.length;
      if (typeof el.setSelectionRange === "function") el.setSelectionRange(n, n);
    } catch (_) {}
  }

  function getStoryPlayStreamBodyText(raw) {
    const processed = preprocessStoryPlayModelRaw(String(raw || ""));
    return sliceStoryRawBeforeChoicesHeader(sliceStoryRawBeforeTurnDigestHeader(processed));
  }

  function listStoryPlayBlockHeaderPositions(body) {
    const src = String(body || "");
    const positions = [];
    const re = /(?:^|\n)\s*【\s*([^】]{1,40})\s*】/g;
    let m;
    while ((m = re.exec(src))) {
      const title = String(m[1] || "").trim();
      if (/^(?:选项|选择支)$/i.test(title)) break;
      positions.push(m.index);
    }
    return positions;
  }

  /** 流式进行中：最后一个【块】尚未收束，故 completed = headers - 1 */
  function countCompletedStoryBlocksInStream(raw, streamDone) {
    const body = getStoryPlayStreamBodyText(raw);
    const positions = listStoryPlayBlockHeaderPositions(body);
    if (!positions.length) return 0;
    if (streamDone) return positions.length;
    return Math.max(0, positions.length - 1);
  }

  function sliceStoryPlayRawToBlockCount(body, blockCount) {
    const src = String(body || "");
    const positions = listStoryPlayBlockHeaderPositions(src);
    if (!positions.length || blockCount <= 0) return "";
    if (blockCount >= positions.length) return src.trim();
    return src.slice(0, positions[blockCount]).trim();
  }

  function mapParsedStoryLinesToTurnLines(parsed) {
    return (parsed || []).map(function (line) {
      const o = {
        id: line && line.id ? line.id : uid("ln"),
        characterId: line ? line.characterId : "",
        text: normalizeStoryPlainTextForLayout(
          stripNarratorDisplayText(String(line && line.text ? line.text : ""))
        ),
      };
      if (line && String(line.speakerName || "").trim()) o.speakerName = String(line.speakerName).trim();
      return o;
    });
  }

  function parseStoryPlayBodyLinesUpTo(raw, protagonist, supporting, blockCount, streamDone) {
    const body = getStoryPlayStreamBodyText(raw);
    if (!body) return [];
    const total = listStoryPlayBlockHeaderPositions(body).length;
    const take = streamDone ? total : Math.min(blockCount, total);
    if (take <= 0) return [];
    const sliced = sliceStoryPlayRawToBlockCount(body, take);
    if (!sliced) return [];
    return parseTurnByCharacterBlocks(sliced, protagonist, supporting);
  }

  function getLastOpenStoryBlockTitle(raw) {
    const body = getStoryPlayStreamBodyText(raw);
    const re = /(?:^|\n)\s*【\s*([^】]{1,40})\s*】/g;
    let last = "旁白";
    let m;
    while ((m = re.exec(body))) {
      const t = String(m[1] || "").trim();
      if (!/^(?:选项|选择支)$/i.test(t)) last = t;
    }
    return last;
  }

  function extractStoryPlayStreamDraftText(raw) {
    const body = getStoryPlayStreamBodyText(raw);
    if (!body || !listStoryPlayBlockHeaderPositions(body).length) return "";
    const positions = listStoryPlayBlockHeaderPositions(body);
    const start = positions[positions.length - 1];
    const tail = body.slice(start);
    const m = tail.match(/^【\s*[^】]{1,40}\s*】\s*\n?([\s\S]*)$/);
    return m ? String(m[1] || "").trim() : "";
  }

  function buildStoryStreamPreviewLine(raw, draftText, protagonist, supporting) {
    const draft = String(draftText || "").trim();
    if (!draft) return null;
    const body = getStoryPlayStreamBodyText(raw);
    if (!body || !listStoryPlayBlockHeaderPositions(body).length) return null;
    const title = getLastOpenStoryBlockTitle(raw);
    const wrapped = "【" + title + "】\n" + draft;
    const parsed = parseTurnByCharacterBlocks(wrapped, protagonist, supporting);
    if (!parsed.length) return null;
    const mapped = mapParsedStoryLinesToTurnLines(parsed);
    if (!mapped.length) return null;
    mapped[0].id = "stream-preview";
    mapped[0].isStreamPreview = true;
    return mapped[0];
  }

  var storyPlayStreamUiRaf = 0;
  var storyPlayStreamUiLastAt = 0;
  var storyScrollNavRaf = 0;
  var storyPlayScrolling = false;
  var storyPlayScrollEndTimer = 0;
  const STORY_STREAM_UI_MIN_MS = 100;

  function scheduleUpdateStoryScrollNav() {
    if (storyScrollNavRaf) return;
    storyScrollNavRaf = requestAnimationFrame(function () {
      storyScrollNavRaf = 0;
      updateStoryScrollNav();
    });
  }

  function markStoryPlayScrolling() {
    storyPlayScrolling = true;
    if (storyPlayScrollEndTimer) clearTimeout(storyPlayScrollEndTimer);
    storyPlayScrollEndTimer = setTimeout(function () {
      storyPlayScrollEndTimer = 0;
      storyPlayScrolling = false;
    }, 120);
  }

  function scheduleStoryPlayStreamUi(plot, turnIndex, protagonist, supporting, streamText, streamDone) {
    if (storyPlayStreamUiRaf) return;
    storyPlayStreamUiRaf = requestAnimationFrame(function () {
      storyPlayStreamUiRaf = 0;
      const now = Date.now();
      if (!streamDone && now - storyPlayStreamUiLastAt < STORY_STREAM_UI_MIN_MS) {
        scheduleStoryPlayStreamUi(plot, turnIndex, protagonist, supporting, streamText, streamDone);
        return;
      }
      storyPlayStreamUiLastAt = now;
      const turns = plot.playTurns || [];
      const turn = turns[turnIndex];
      if (!turn || !turn.streaming) return;
      const completed = countCompletedStoryBlocksInStream(streamText, !!streamDone);
      const parsed = parseStoryPlayBodyLinesUpTo(streamText, protagonist, supporting, completed, !!streamDone);
      turn.lines = mapParsedStoryLinesToTurnLines(parsed);
      if (!streamDone) {
        const draft = extractStoryPlayStreamDraftText(streamText);
        turn.streamPreviewLine = buildStoryStreamPreviewLine(streamText, draft, protagonist, supporting);
      } else {
        turn.streamPreviewLine = null;
      }
      renderStoryPlay(plot);
    });
  }

  function finalizeStoryPlayTurnFromRaw(plot, turn, rawResp, protagonist, supporting, pendingPlayerTurnAction) {
    const rawProcessed = preprocessStoryPlayModelRaw(rawResp);
    const rawForPlayParse = sliceStoryRawBeforeTurnDigestHeader(rawProcessed);
    const bodyBeforeChoiceHeader = sliceStoryRawBeforeChoicesHeader(rawForPlayParse);
    const parseSource = bodyBeforeChoiceHeader.length >= 16 ? bodyBeforeChoiceHeader : rawForPlayParse;
    let lines = parseTurnByCharacterBlocks(parseSource, protagonist, supporting);
    let choices = parseChoicesBlock(rawForPlayParse);
    if (Array.isArray(lines) && lines.length && Array.isArray(choices) && choices.length >= 2) {
      const stripped = stripEmbeddedChoicePreviewFromStoryLines(lines, choices);
      if (stripped.length) lines = stripped;
    }
    const linesWithIds = mapParsedStoryLinesToTurnLines(lines);
    if (!linesWithIds.length) throw new Error("剧情生成失败，请点重生成或换模型重试。");
    if (!Array.isArray(choices) || choices.length < 2) {
      throw new Error("生成失败（缺少有效选项），请点重生成或换模型重试。");
    }
    const triggerSnap =
      pendingPlayerTurnAction && String(pendingPlayerTurnAction.line || "").trim()
        ? {
            type: String(pendingPlayerTurnAction.type || "text"),
            line: pendingPlayerTurnAction.line,
            hint: pendingPlayerTurnAction.hint || "",
          }
        : null;
    turn.lines = linesWithIds;
    turn.choices = choices.slice();
    turn.triggerPlayerAction = triggerSnap;
    turn.internalDigest = "";
    turn.streaming = false;
    turn.streamPreviewLine = null;
    plot.lastGeneratedAt = Date.now();
    syncPhoneStoryDateAnchor(plot);
    return linesWithIds[0] && linesWithIds[0].id ? String(linesWithIds[0].id) : "";
  }

  async function requestNextStoryTurn(plot) {
    if (!plot || plot.playTurnInFlight || plot.playChoicesRegenerateInFlight) return;
    ensurePlotExtendedState(plot);
    if (plot.playSealed) return;
    const ppt0 = plot.pendingPlayerTurnAction;
    const pendingPlayerTurnAction = ppt0
      ? {
          type: String(ppt0.type || "text"),
          line: cleanStoryLine(ppt0.line || ""),
          hint: cleanStoryLine(ppt0.hint || ""),
          composerRestoreDraft:
            typeof ppt0.composerRestoreDraft === "string" ? ppt0.composerRestoreDraft : String(ppt0.line || ""),
        }
      : null;
    plot.playTurnInFlight = true;
    storyAiWakeLockAcquire();
    renderStoryPlay(plot);
    const protagonist = getCharById(plot.protagonistId);
    const supporting = (plot.supportingIds || [])
      .map(function (id) {
        return getCharById(id);
      })
      .filter(Boolean);
    const supportingMain = supporting.filter(function (c) {
      return String(c.categoryId || "").trim() !== CHAR_CATEGORY_EXTRA_ID;
    });
    const supportingExtra = supporting.filter(function (c) {
      return String(c.categoryId || "").trim() === CHAR_CATEGORY_EXTRA_ID;
    });
    const wbs = getWorldBooksForPlot(plot);

    const recentTurns = (plot.playTurns || []).slice(-STORY_PLAY_REF_TURN_LIMIT);
    const history = buildStoryPlayRecentHistoryText(plot);
    const latestPlayerAction = (function () {
      const turns = recentTurns;
      for (let ti = turns.length - 1; ti >= 0; ti--) {
        const t = turns[ti];
        const ls = Array.isArray(t && t.lines) ? t.lines : [];
        for (let li = ls.length - 1; li >= 0; li--) {
          const ln = ls[li];
          if (!ln || ln.characterId !== plot.protagonistId) continue;
          const txt = String(ln.text || "").trim();
          if (txt) return txt;
        }
      }
      return "";
    })();

    const wlim2 =
      plot && typeof plot.wordLimit === "number" && Number.isFinite(plot.wordLimit) ? plot.wordLimit : DEFAULT_STORY_WORD_LIMIT;
    const povLine2 = normalizeNarrativePov(plot && plot.pov ? plot.pov : "第三人称");
    const povConstraintPlay = buildPovHardConstraint(povLine2, protagonist && protagonist.name ? protagonist.name : "");
    const dominantRoster = []
      .concat(protagonist && protagonist.name ? [protagonist.name] : [])
      .concat(
        supportingMain.map(function (c) {
          return c.name;
        })
      )
      .filter(Boolean)
      .join("，");
    const extraRoster = supportingExtra
      .map(function (c) {
        return c.name;
      })
      .filter(Boolean)
      .join("，");
    let playApiCfg = null;
    const playApiPickId = pickAvailableApiId();
    if (playApiPickId && apiConfigs && apiConfigs.length) {
      playApiCfg =
        apiConfigs.find(function (a) {
          return a.id === playApiPickId;
        }) || null;
    }
    const playModelLc = String(playApiCfg && playApiCfg.model ? playApiCfg.model : "").toLowerCase();
    const isGeminiPlay = playModelLc.indexOf("gemini") !== -1;
    const storyPlayChoicePovHint =
      povLine2 === "第二人称"
        ? "【选项】每条用「你」或省略主语的短指令；不要写主角全名。"
        : povLine2 === "第一人称"
          ? "【选项】每条用「我」或省略主语的短指令；不要写主角全名。"
          : "【选项】勿以主角全名起句；用「他/她」或动词开头的短句。";

    const storyPlayTurnBlockBudgetLine =
      "· 【块数·随本轮目标字数】" +
      (wlim2 >= 14000
        ? "本轮在多角色交替推进的前提下，合计大约 16～26 枚「说话块」甚至更多；**块多主要指换人换视点，不是把同一人拆成许多碎块**。"
        : wlim2 >= 9000
          ? "本轮合计大约 12～20 枚说话块；优先靠多角色轮换来切块，避免同一角色连续多个【同名】标题。"
          : wlim2 >= 5500
            ? "本轮合计大约 10～16 枚说话块；同一角色同一场戏尽量只用一条【名】块写完。"
            : "本轮大约 7～14 枚说话块即可（同场多角色时倾向区间中上沿）；同一角色莫为「短块」而机械拆条。") +
      "\n" +
      "· 【单块形态·忌模板化】每个【角色】块内应像小说一段：对白、动作、神态可混写；**对白一律用中文弯引号 “…” 标示（也可用半角 \"…\"），不要用直角引号 「…」当对白符号。**忌几乎每轮都写成「先单独抬一句对白、再单独接一大段描写」的固定套路。要有意变化：纯对白连播、纯动作无对白、对白嵌在叙事里、短氛围段等都要出现，勿雷同。\n" +
      "· 【换人节奏】叙述上尽量轮番【角色甲】-【角色乙】-【旁白】交替；**同一角色若仍处同一场戏、同一口气，请写进同一个【名】块**，不要在相邻行重复【同名】切碎。只有换人、时间跳切或段落明显收束时再新开块。\n" +
      "· 【多角色露脸·非强制】同场若花名册里有多名主要角色在场，在篇幅与节拍允许时**尽量**让两人及以上各自有独立【名】块（可很短：一句对白、一个反应或小动作即可），比整轮单角色独角戏更丰富；若玩家指令或场面逻辑只需一人推进，则不必为凑人数硬插。\n" +
      STORY_PLAY_CONTINUITY_GUIDE;

    const systemPrompt =
      "你是中文互动剧情续写助手。输出剧情说话块与文末「【选项】」；不要开场寒暄；不要用代码围栏（三面反引号）包住全文。\n\n" +
      "【玩家指令优先】当用户消息含「务必优先·玩家指令」时，该段所列点选选项或输入文字为本回合最高约束：后续场面、对白与因果链条必须与之相符，禁止忽略、禁止改写成相反走向，禁止仅用一句话带过再写无关支线。\n" +
      "【选项区唯一】禁止在正文里（在文末「【选项】」「【选择支】」或「## 选项」等标题出现之前）再写「选项 1.」「选项1.」「2.」等分支罗列或与文末选项雷同的预告；玩家可点选的行动只准许在文末选项区出现一次。\n\n" +
      "【输出形态·程序依此解析】\n" +
      storyPlayTurnBlockBudgetLine +
      "· 「说话块」按**说话者/视点**切换：换人或换【旁白】时用单独一行的【角色名】/【旁白】/【我】（仅第一人称主角）起头；**优先**使用下方花名册中的姓名；剧情需要的店员、路人等**未建档角色**也可用【显示名】起块，界面会以首字头像与昵称展示。亦可用「姓名：」同一行起段，或与花名册一致的全名单独占一行（下一行起接对白或描写；勿加括号或 Markdown 装饰）。**同一说话者同一场戏不要为每一句对白再起新的【名】行。**\n" +
      "· 【标点】段落开头不要直接使用逗号、句号、冒号等句读——若该段第一句是对白，则用弯引号 “ 起笔。**对白不要使用 「」 作为起止符号。**不要将单个标点单独占成一行；段末不要使用两个连续句号/问号/叹号等（如。。、？？），也不要写成「：。」。\n" +
      "· 结尾留下玩家可介入的局面；最后一格尽量用配角或【旁白】收束。\n" +
      "· 文末单独一行「【选项】」或「【选择支】」，或用 Markdown 「## 选项」等小标题接引；后跟至少两行可选行动。\n" +
      "可加 1. / - 前缀；一行一条，勿把两段对白挤在同一行。\n" +
      "· **输出顺序固定**：剧情说话块 → 【选项】与选项行。\n\n" +
      storyPlayChoicePovHint +
      "\n\n" +
      "【篇幅】约 " +
      wlim2 +
      " 汉字；多用对话与小动作推进，少用纯景物长描与重复上一轮、记忆、总结中已写过的信息；篇幅内可分摊给多名角色各写一小段，不必一人包揽。\n\n" +
      "【戏份】" +
      "侧重：" +
      (dominantRoster || "无") +
      "；配角/NPC：" +
      (extraRoster || "无") +
      "（主线仍以侧重名单为主；同场有多名侧重角色时**宜**交替给戏份，非侧重仍少写、点名或必要时再出场）。\n\n" +
      "【人称】" +
      povConstraintPlay +
      "\n\n" +
      "【文风】" +
      STORY_PLAY_PROSE_BRIEF +
      "\n" +
      STORY_PERSONA_PRIORITY_GUIDE +
      "\n\n（若在 Gemini 等平台输出：仍可混用简短 Markdown，但须保留清晰的【】块分界与文末选项区。）";
    const identityBlocks = getEffectiveIdentityBlocks(plot);
    const hasPriorPlay = (plot.playTurns || []).length > 0;
    const eraBlock = buildStoryPlayIdentityFieldForPrompt(identityBlocks.eraBlock || "未设定", hasPriorPlay);
    const identitySelfBlock = buildStoryPlayIdentityFieldForPrompt(
      identityBlocks.identitySelfBlock || "未设定",
      hasPriorPlay
    );
    const identityOthersBlock = buildStoryPlayIdentityFieldForPrompt(
      identityBlocks.identityOthersBlock || "未设定",
      hasPriorPlay
    );
    const openingBlock = String((plot.playIntro && plot.playIntro.opening) || plot.storyStart || "").trim() || "未设定";
    const roleOverrideBlock = identityBlocks.roleOverrideBlock || "";
    const summaryBlock = buildPlotSummariesPromptBlockForPlay(plot);
    const roleLibraryBlock = buildPlayRoleLibraryPromptBlock(protagonist, supporting);
    const memoryContext = buildPlotMemoryContextBlob([
      plot.theme,
      summaryBlock,
      pendingPlayerTurnAction && pendingPlayerTurnAction.line ? pendingPlayerTurnAction.line : "",
      pendingPlayerTurnAction && pendingPlayerTurnAction.hint ? pendingPlayerTurnAction.hint : "",
      latestPlayerAction,
      eraBlock,
      openingBlock,
      history,
    ]);
    const memoryBlock = buildPlotMemoriesPrompt(plot, memoryContext);
    const rosterNames = []
      .concat(protagonist && protagonist.name ? [protagonist.name] : [])
      .concat(
        supporting.map(function (c) {
          return c.name;
        })
      )
      .filter(Boolean)
      .join("，");
    const wbBlockPlay = formatWorldBooksPromptBlockForPlay(wbs);
    const includeRoleLibrary =
      roleLibraryBlock && !isPlayRoleLibraryRedundantWithIdentities(roleLibraryBlock, identitySelfBlock, identityOthersBlock);
    const playerActionPriorityLead =
      pendingPlayerTurnAction && String(pendingPlayerTurnAction.line || "").trim()
        ? "【务必优先·玩家指令】\n" +
          "本回合续写必须以下列玩家选择或输入为因果与场面发展的主轴；请贯穿落实其意图，不得背离；可用叙事技巧改写呈现，但结果走向须一致。\n" +
          (String(pendingPlayerTurnAction.type || "") === "choice"
            ? "（来源：玩家点击的预设选项——请落实正文与对白，并兼顾「提示」中的设计意图。）\n"
            : "（来源：剧情框内玩家发送的自由文字——请直接承接其内容与语气。）\n") +
          "玩家本次行动：\n" +
          String(pendingPlayerTurnAction.line || "").trim() +
          (pendingPlayerTurnAction.hint ? "\n提示：\n" + String(pendingPlayerTurnAction.hint || "").trim() : "") +
          "\n\n"
        : "";
    const userPrompt =
      (wbBlockPlay ? wbBlockPlay + "\n" : "") +
      playerActionPriorityLead +
      "题材方向：" +
      (String(plot.theme || "").trim() || "无特定题材") +
      "\n\n【当前剧情设定】\n" +
      "时代与场景：\n" + eraBlock +
      "\n\n我的形象：\n" + identitySelfBlock +
      "\n\n其他角色：\n" + identityOthersBlock +
      "\n\n故事开端：\n" + buildStoryPlayOpeningPromptBlock(openingBlock, hasPriorPlay) +
      "\n\n花名册（主要角色须优先使用其中姓名；未在册的客串也可用【姓名】起块）：" + (rosterNames || "无") +
      (includeRoleLibrary ? "\n\n【角色库·外貌与性格（仅作扮演参考）】\n" + roleLibraryBlock : "") +
      (pendingPlayerTurnAction && String(pendingPlayerTurnAction.line || "").trim()
        ? "\n\n（玩家指令全文见上文【务必优先·玩家指令】；叙事中勿机械复述提示词原句，须语义一致落实。）"
        : "") +
      (latestPlayerAction ? "\n\n上一手玩家行动（仅供连续性参考）：\n" + latestPlayerAction : "") +
      (roleOverrideBlock ? "\n\n当前角色形象覆盖：\n" + roleOverrideBlock : "") +
      (hasPriorPlay ? "\n\n" + STORY_PLAY_CONTEXT_REF_GUIDE : "") +
      "\n\n【必读·最近剧情】（仅最近 " +
      STORY_PLAY_REF_TURN_LIMIT +
      " 轮；**最高优先**，须从最后一轮收束处无缝续写；末轮为完整正文、更早轮次为首尾摘录；同层冲突时以本段为准）：\n" +
      (history || "故事刚开始。") +
      (memoryBlock
        ? "\n\n【必读·记忆】（最多 " +
          PLOT_MEMORY_PROMPT_MAX +
          " 条；均为已发生要点，须长期遵守并在本轮呼应其后果，勿复述重演；不得遗漏或违背）：\n" +
          memoryBlock
        : "") +
      (summaryBlock
        ? "\n\n【必读·阶段总结】（均为已发生过去式；主线滚动摘要，或已保存最近 " +
          STORY_PLAY_SUMMARY_REF_LIMIT +
          " 条；补充更早背景，勿复述已有情节，须在其基础上向前推进；细节冲突时以「最近剧情」为准）：\n" +
          summaryBlock
        : hasPriorPlay
          ? "\n\n【必读·阶段总结】（暂无总结；请严格依据上方「最近剧情」承接，勿与已写正文矛盾。）"
          : "");

    const apiSystemPrompt = truncateCharsWithEllipsis(systemPrompt, STORY_PLAY_API_SYSTEM_MAX_CHARS);
    const apiUserPrompt = capStoryPlayUserPromptForApi(userPrompt);

    if (
      pendingPlayerTurnAction &&
      String(pendingPlayerTurnAction.type || "text") === "text"
    ) {
      const compIn = document.getElementById("story-composer-input");
      if (compIn) compIn.value = "";
    }

    let scrollToNewTurnFirstLineId = "";
    let streamTurnIndex = -1;
    const playGenOpts = beginGenCall("story-play", { plot: plot });
    let storyTurnGenOk = false;
    try {
      showToast("AI 正在续写剧情…", "info");
      const playTemperature = isGeminiPlay ? 0.56 : 0.72;
      if (!playApiCfg) throw new Error("未配置 API，请先在设置中添加 API 配置。");
      if (!plot.playTurns) plot.playTurns = [];
      const streamingTurn = {
        id: uid("turn"),
        lines: [],
        choices: [],
        triggerPlayerAction:
          pendingPlayerTurnAction && String(pendingPlayerTurnAction.line || "").trim()
            ? {
                type: String(pendingPlayerTurnAction.type || "text"),
                line: pendingPlayerTurnAction.line,
                hint: pendingPlayerTurnAction.hint || "",
              }
            : null,
        internalDigest: "",
        streaming: true,
        streamPreviewLine: null,
      };
      plot.playTurns.push(streamingTurn);
      streamTurnIndex = plot.playTurns.length - 1;
      renderStoryPlay(plot);

      const apiMessages = [
        { role: "system", content: apiSystemPrompt },
        { role: "user", content: apiUserPrompt },
      ];
      const rawResp = await callStoryPlayChatCompletion(
        playApiCfg,
        apiMessages,
        playTemperature,
        storyPlayMaxTokens(plot),
        {
          onStreamProgress: function (_delta, fullText) {
            scheduleStoryPlayStreamUi(plot, streamTurnIndex, protagonist, supporting, fullText, false);
          },
        }
      );
      if (storyPlayStreamUiRaf) {
        cancelAnimationFrame(storyPlayStreamUiRaf);
        storyPlayStreamUiRaf = 0;
      }
      scheduleStoryPlayStreamUi(plot, streamTurnIndex, protagonist, supporting, rawResp, true);
      scrollToNewTurnFirstLineId = finalizeStoryPlayTurnFromRaw(
        plot,
        streamingTurn,
        rawResp,
        protagonist,
        supporting,
        pendingPlayerTurnAction
      );
      storyTurnGenOk = true;
      flushPersistNarrative();
    } catch (err) {
      console.error("剧情续写失败:", err);
      if (
        streamTurnIndex >= 0 &&
        plot.playTurns &&
        plot.playTurns[streamTurnIndex] &&
        plot.playTurns[streamTurnIndex].streaming
      ) {
        plot.playTurns.splice(streamTurnIndex, 1);
      }
      showToast("续写失败：" + (err && err.message ? err.message : "请重试或换用其他模型"), "error", 4000);
      restoreStoryComposerInputAfterPlayFailureFromPendingSnap(pendingPlayerTurnAction);
    } finally {
      plot.pendingPlayerTurnAction = null;
      plot.playTurnInFlight = false;
      storyAiWakeLockRelease();
      renderStoryPlay(plot);
      if (storyTurnGenOk && playGenOpts.genReady) stashGenReadyNotice(playGenOpts.genReady);
      clearGenCallContext();
      if (storyTurnGenOk) {
        setTimeout(function () {
          showToast("剧情续写完成", "success");
        }, 0);
      }
      flushPersistNarrative();
      const lineIdForScrollTop = scrollToNewTurnFirstLineId;
      requestAnimationFrame(function () {
        if (lineIdForScrollTop) scrollStoryPlayNewTurnToTop(plot, lineIdForScrollTop);
        updateStoryScrollNav();
      });
    }
  }

  async function submitPlayerTurn(plot, payload) {
    if (!plot || plot.playTurnInFlight || plot.playChoiceExpandInFlight || plot.playChoicesRegenerateInFlight) return;
    ensurePlotExtendedState(plot);
    if (plot.playSealed) return;
    let pending = null;
    if (payload.type === "text") {
      const raw =
        typeof payload.rawComposerText === "string"
          ? payload.rawComposerText
          : String(payload.text || "");
      const textInput = raw.trim();
      if (textInput)
        pending = {
          type: "text",
          line: textInput,
          hint: "",
          composerRestoreDraft: raw,
        };
    } else if (payload.type === "choice") {
      const turns = plot.playTurns || [];
      const last = turns.length ? turns[turns.length - 1] : null;
      const c = last && last.choices && last.choices[payload.index];
      if (c && String(c.line || "").trim()) {
        pending = { type: "choice", line: String(c.line || "").trim(), hint: String(c.hint || "").trim() };
      }
    }
    if (!pending) return;
    plot.pendingPlayerTurnAction = pending;
    if (!plot.playTurns) plot.playTurns = [];
    void requestNextStoryTurn(plot);
    scrollStoryPlayToLatest(false);
    flushPersistNarrative();
  }

  /** 底部输入框发送：与点选项一样走 submitPlayerTurn → requestNextStoryTurn */
  function submitStoryComposer() {
    const playPanel = document.getElementById("story-panel-play");
    if (!playPanel || playPanel.hidden) {
      showToast("请在「剧情」正文界面（已进入剧情）再发送。", "info", 3200);
      return;
    }
    const input = document.getElementById("story-composer-input");
    const rawInput = String((input && input.value) || "");
    const text = rawInput.trim();
    if (!text) {
      showToast("请先输入要执行的行动或台词", "info", 2200);
      return;
    }
    let p = getPlayModeStoryPlotFromRoute();
    if (!p) p = getCurrentStoryPlot();
    if (!p) {
      showToast("未找到当前剧情，请从剧情列表重新进入。", "error", 3200);
      return;
    }
    ensurePlotExtendedState(p);
    if (p.playSealed) {
      showToast("当前剧情已封笔，仅供查看。", "info", 2800);
      return;
    }
    if (!p.storyEntered) {
      showToast("请先点击「进入剧情」，再在此处发送自定义内容。", "info", 3500);
      return;
    }
    if (!p.protagonistId) {
      showToast("当前剧情未设置主视角角色", "error", 2800);
      return;
    }
    if (p.playTurnInFlight || p.playChoiceExpandInFlight || p.playChoicesRegenerateInFlight) {
      showToast("上一段还在生成中，请稍候再试。", "info", 2600);
      return;
    }
    lastStoryPlotId = p.id;
    avatarActionPlotId = p.id;
    submitPlayerTurn(p, { type: "text", rawComposerText: rawInput });
  }

  function openStoryLayer(plot, modeOpt, opts) {
    opts = opts || {};
    closeStoryLineActionSheet();
    closeAvatarActionSheet();
    ensurePlotSummaryState(plot);
    ensurePlotExtendedState(plot);
    lastStoryPlotId = plot.id;
    avatarActionPlotId = plot.id;
    els.storyTitle().textContent = plot.title;
    renderStorySummaryTags(plot);
    const mode = resolveStoryMode(plot, modeOpt);
    showStorySub(mode);
    if (mode === "setup") {
      setStorySetupEditing(false);
      renderStorySetup(plot);
    } else {
      renderStoryPlay(plot);
      fillStoryComposerAvatar(plot);
      if (shouldAutoRequestFirstStoryTurn(plot)) void requestNextStoryTurn(plot);
    }
    els.layerStory().hidden = false;
    if (!opts.skipHashSet) {
      const want = "#/story/" + plot.id + "/" + mode;
      if ((location.hash || "") !== want) location.hash = want;
    }
    if (mode === "play") {
      requestAnimationFrame(function () {
        requestAnimationFrame(function () {
          scrollStoryPlayToLatest(false);
        });
      });
    }
  }

  function closeStoryLayer(targetTab) {
    closeStoryLineActionSheet();
    storyLineEditState = null;
    hideStorySelectionBubble();
    closeAvatarActionSheet();
    closeStorySummariesModal();
    closeStorySearchModal();
    closeStoryPhoneModal();
    closeStoryFanworkModal();
    closeStoryApiSettingsModal();
    closePlotMyOverrideModal();
    closePlotRoleOverrideModal();
    closePlotWbBindModal();
    closePlotMemoriesModal();
    closePlotMemoryEditModal();
    storySetupEditing = false;
    const panel = document.getElementById("story-panel-setup");
    if (panel) panel.classList.remove("story-setup--editing");
    els.layerStory().hidden = true;
    overviewSubView = null;
    if (targetTab && MAIN_TAB_IDS.includes(targetTab)) {
      location.hash = "#/tab/" + targetTab;
    } else {
      location.hash = "#/tab/" + activeTab;
    }
    applyHash();
    syncOverviewSubViewUi();
    renderDynamic();
  }

  function isNewApiFormComplete(form) {
    if (!form) return false;
    const nameEl = form.querySelector('[name="name"]');
    const endpointEl = form.querySelector('[name="endpoint"]');
    const n = nameEl && nameEl.value != null ? String(nameEl.value).trim() : "";
    const u = endpointEl && endpointEl.value != null ? String(endpointEl.value).trim() : "";
    return n !== "" && u !== "";
  }

  /** 当前屏幕上可交互的「新建 API」表单（设置页或剧情弹层里可见的一份） */
  function getVisibleNewApiForm() {
    for (const form of document.querySelectorAll(".js-form-new-api")) {
      const block = form.closest(".js-add-api-block");
      if (!block) continue;
      if (block.hidden || block.hasAttribute("hidden")) continue;
      if (typeof form.checkVisibility === "function") {
        if (form.checkVisibility({ opacityProperty: true, visibilityProperty: true })) return form;
      } else {
        const r = form.getBoundingClientRect();
        if (r.width > 0 && r.height > 0) return form;
      }
    }
    return null;
  }

  function dismissIncompleteNewApiIfOutsideClick(e) {
    if (!showSettingsAdd) return;
    const t = e.target;
    if (!(t instanceof Element)) return;
    if (t.closest(".js-add-api-block")) return;
    if (t.closest(".js-settings-reveal-add")) return;
    if (t.closest("#story-composer-api")) return;
    if (t.closest("#api-heart-float")) return;
    const form = getVisibleNewApiForm();
    if (!form) return;
    if (isNewApiFormComplete(form)) return;
    showSettingsAdd = false;
    renderDynamic();
  }

  function buildApiSettingsSectionHtml(opts) {
    opts = opts || {};
    const omitPanelHead = !!opts.omitPanelHead;
    const plugSvg =
      '<svg class="icon-linear" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75"><path d="M12 22v-5"/><path d="M9 8V2"/><path d="M15 8V2"/><path d="M18 8v5a6 6 0 01-12 0V8h12z"/></svg>';

    let html = '<section class="settings-panel">';
    if (!omitPanelHead) {
      html +=
        '<div class="settings-panel__head"><span class="settings-panel__icon">' +
        plugSvg +
        '</span><div><h3 class="settings-panel__title">API 与模型</h3></div></div>';
    }
    html += '<div class="settings-panel__body">';
    html +=
      '<p class="field__hint api-pool-hint">可同时启用最多 2 个 API；请求进行中会自动切换至另一个，仅配置 1 个则全局共用。</p>';
    apiConfigs.forEach(function (a) {
      html += renderApiCard(a);
    });

    html +=
      (showSettingsAdd
        ? ""
        : '<p class="settings-add-hint"><button type="button" class="text-link js-settings-reveal-add">＋ 添加新 API 配置</button></p>') +
      '<div class="add-api-block js-add-api-block"' +
      (showSettingsAdd ? "" : " hidden") +
      '><form class="form-stack js-form-new-api">' +
      '<label class="field"><span class="field__label">配置名称</span><input class="field__input" name="name" placeholder="例：我的 GPT 配置" required /></label>' +
      '<label class="field"><span class="field__label">API 站点地址</span><input class="field__input" name="endpoint" placeholder="https://..." required /></label>' +
      '<label class="field"><span class="field__label">API Key</span><input class="field__input" name="key" type="password" placeholder="sk-..." /></label>' +
      '<button type="submit" class="btn btn--primary btn--block btn--pill">保存配置</button></form></div>';

    html += "</div></section>";
    return html;
  }

  function getVisualRefImages(refKey) {
    const ref =
      refKey === "daily" ? visualImageSettings.dailyRef : visualImageSettings.appearanceRef;
    const urls = ref && ref.imageDataUrls;
    if (!Array.isArray(urls)) return [];
    return urls.filter(function (u) {
      return typeof u === "string" && u.trim();
    });
  }

  function buildVisualMultiRefSectionHtml(opts) {
    const refKey = opts.refKey;
    const sectionTitle = opts.sectionTitle;
    const slotLabel = opts.slotLabel || "参考";
    const inputId = refKey === "daily" ? "visual-daily-file" : "visual-appearance-file";
    const pickAttr = refKey === "daily" ? "data-visual-daily-pick" : "data-visual-appearance-pick";
    const images = getVisualRefImages(refKey);
    const count = images.length;
    const max = VISUAL_REF_IMAGE_MAX;
    const atMax = count >= max;
    const refObj =
      refKey === "daily" ? visualImageSettings.dailyRef : visualImageSettings.appearanceRef;
    const angleMeta = refKey === "appearance" ? getAppearanceRefAngleMeta() : [];
    const prompt = (refObj && refObj.prompt) || "";
    const celebrity =
      refKey === "appearance"
        ? String((refObj && refObj.celebrityLookalike) || "").trim()
        : "";
    const plusSvg =
      '<svg class="icon-linear visual-image-pick-icon" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" aria-hidden="true"><path d="M12 5v14M5 12h14"/></svg>';
    const thumbCells = [];
    for (let i = 0; i < max; i++) {
      const url = images[i] || "";
      if (url) {
        const thumbLabel =
          refKey === "appearance" && angleMeta[i] && angleMeta[i].angleLabel
            ? angleMeta[i].angleLabel
            : slotLabel + " " + (i + 1);
        thumbCells.push(
          '<div class="visual-image-appearance-thumb visual-image-appearance-thumb--filled">' +
          '<img class="visual-image-appearance-thumb__img" src="' +
          escapeHtml(url) +
          '" alt="" />' +
          '<button type="button" class="icon-btn visual-image-ref-card__remove" data-visual-ref-remove="' +
          refKey +
          '" data-visual-ref-index="' +
          i +
          '" aria-label="移除第 ' +
          (i + 1) +
          ' 张参考图"><svg class="icon-linear" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M18 6L6 18M6 6l12 12"/></svg></button>' +
          '<span class="visual-image-appearance-thumb__label">' +
          escapeHtml(thumbLabel) +
          "</span></div>"
        );
      } else {
        thumbCells.push(
          '<button type="button" class="visual-image-appearance-thumb visual-image-appearance-thumb--empty" ' +
          pickAttr +
          ' aria-label="上传' +
          escapeHtml(slotLabel) +
          " " +
          (i + 1) +
          '">' +
          plusSvg +
          '<span class="visual-image-appearance-thumb__placeholder">' +
          escapeHtml(slotLabel) +
          " " +
          (i + 1) +
          "</span></button>"
        );
      }
    }
    return (
      '<p class="settings-section-title">' +
      escapeHtml(sectionTitle) +
      "</p>" +
      '<div class="visual-image-upload-block">' +
      '<div class="visual-image-upload-block__head">' +
      '<span class="visual-image-upload-block__title">参考图片</span>' +
      '<span class="visual-image-upload-block__badge">' +
      count +
      "/" +
      max +
      "</span></div>" +
      '<div class="visual-image-appearance-thumbs" aria-label="' +
      escapeHtml(sectionTitle) +
      "，最多 " +
      max +
      ' 张">' +
      thumbCells.join("") +
      "</div>" +
      '<input type="file" accept="image/*" id="' +
      inputId +
      '" hidden multiple /></div>' +
      (refKey === "appearance"
        ? '<p class="visual-image-upload-block__hint">上传 1～3 张同一人物不同角度（如正脸、侧脸、他拍）。仅 1 张时生成会固定该角度；多张时按场景描述自动选用对应参考图。</p>'
        : "") +
      '<div class="visual-image-ref-fields">' +
      '<label class="field visual-image-ref-fields__prompt">' +
      '<span class="field__label">参考描述提示词</span>' +
      '<textarea class="field__input field__textarea visual-image-ref-card__prompt" data-visual-ref-prompt="' +
      refKey +
      '" rows="4" placeholder="参考图描述提示词（可编辑）">' +
      escapeHtml(prompt) +
      "</textarea></label>" +
      (refKey === "appearance"
        ? '<label class="field visual-image-ref-fields__celebrity">' +
          '<span class="field__label">额外气质参考（可选）</span>' +
          '<input class="field__input" type="text" data-visual-ref-celebrity="appearance" placeholder="留空则仅以上传照片为准" value="' +
          escapeHtml(celebrity) +
          '" autocomplete="off" />' +
          "</label>"
        : "") +
      "</div>"
    );
  }

  function buildVisualAppearanceRefSectionHtml() {
    return buildVisualMultiRefSectionHtml({
      refKey: "appearance",
      sectionTitle: "外貌参考（自拍/人像）",
      slotLabel: "角度",
    });
  }

  function buildVisualDailyRefSectionHtml() {
    return buildVisualMultiRefSectionHtml({
      refKey: "daily",
      sectionTitle: "日常参考（打卡/环境）",
      slotLabel: "参考",
    });
  }

  function buildVisualImageSettingsSectionHtml() {
    const plugSvg =
      '<svg class="icon-linear" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75"><path d="M12 22v-5"/><path d="M9 8V2"/><path d="M15 8V2"/><path d="M18 8v5a6 6 0 01-12 0V8h12z"/></svg>';
    const styleOpts = VISUAL_IMAGE_STYLES.map(function (s) {
      return (
        '<option value="' +
        escapeHtml(s.id) +
        '"' +
        (visualImageSettings.style === s.id ? " selected" : "") +
        ">" +
        escapeHtml(s.label) +
        "</option>"
      );
    }).join("");
    const visualModels = getVisualModelOptions();
    const visualModelOpts = visualModels
      .map(function (m) {
        return (
          '<option value="' +
          escapeHtml(m) +
          '"' +
          (visualImageSettings.api.model === m ? " selected" : "") +
          ">" +
          escapeHtml(m) +
          "</option>"
        );
      })
      .join("");
    const visualRefreshLabel = visualImageModelsRefreshing ? "刷新中…" : "刷新模型列表";
    const visualTestLabel = visualImageModelTesting ? "测试中…" : "测试模型可用性";
    const visualBtnsDisabled =
      visualImageModelsRefreshing || visualImageModelTesting ? " disabled" : "";
    let html =
      '<section class="settings-panel settings-panel--visual-image">' +
      '<div class="settings-panel__head"><h3 class="settings-panel__title">图片生成</h3></div>' +
      '<div class="settings-panel__body tts-settings-compact">' +
      '<div class="visual-image-enable-card' +
      (visualImageSettings.enabled ? " visual-image-enable-card--on" : "") +
      '">' +
      '<div class="visual-image-enable-card__main">' +
      '<span class="visual-image-enable-card__icon" aria-hidden="true">' +
      '<svg class="icon-linear" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75"><rect x="3" y="5" width="18" height="14" rx="2"/><circle cx="8.5" cy="10.5" r="1.5"/><path d="M21 16l-5.5-5.5L5 19"/></svg>' +
      "</span>" +
      '<div class="visual-image-enable-card__text">' +
      '<span class="visual-image-enable-card__title">启用聊天发图</span>' +
      "</div></div>" +
      '<button type="button" class="story-summaries-switch' +
      (visualImageSettings.enabled ? " story-summaries-switch--on" : "") +
      '" id="visual-image-enabled-toggle" role="switch" aria-checked="' +
      (visualImageSettings.enabled ? "true" : "false") +
      '" aria-label="启用聊天发图"><span class="story-summaries-switch__track" aria-hidden="true"><span class="story-summaries-switch__thumb"></span></span></button>' +
      "</div>" +
      '<label class="field"><span class="field__label">画风选择</span>' +
      '<select class="field__input" id="visual-image-style-select" aria-label="画风选择">' +
      styleOpts +
      "</select></label>" +
      buildVisualAppearanceRefSectionHtml() +
      buildVisualDailyRefSectionHtml() +
      "</div></section>" +
      '<section class="settings-panel settings-panel--visual-api">' +
      '<div class="settings-panel__head"><span class="settings-panel__icon">' +
      plugSvg +
      '</span><div><h3 class="settings-panel__title">生图 API</h3></div></div>' +
      '<div class="settings-panel__body tts-settings-compact">' +
      '' +
      '<article class="api-card glass-surface visual-api-card">' +
      '<div class="tts-settings-compact__grid call-settings-grid">' +
      '<label class="field call-settings-grid__full"><span class="field__label">API 站点地址</span>' +
      '<input class="field__input" id="visual-api-endpoint" type="url" placeholder="https://api.example.com/v1" value="' +
      escapeHtml(visualImageSettings.api.endpoint || "") +
      '" autocomplete="off" /></label>' +
      '<label class="field call-settings-grid__full"><span class="field__label">API Key</span>' +
      '<input class="field__input" id="visual-api-key" type="password" placeholder="sk-..." value="' +
      escapeHtml(visualImageSettings.api.apiKey || "") +
      '" autocomplete="off" /></label></div>' +
      '<div class="api-card__btns">' +
      '<button type="button" class="btn-refresh visual-api-refresh"' +
      visualBtnsDisabled +
      '><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75"><path d="M23 4v6h-6M1 20v-6h6"/><path d="M3.51 9a9 9 0 0114.85-3.36L23 10M1 14l4.64 4.36A9 9 0 0020.49 15"/></svg>' +
      escapeHtml(visualRefreshLabel) +
      "</button>" +
      '<button type="button" class="btn-refresh visual-api-test" aria-label="测试模型可用性"' +
      visualBtnsDisabled +
      '><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75"><path d="M22 11.08V12a10 10 0 11-5.93-9.14"/><path d="M22 4L12 14.01l-3-3"/></svg>' +
      escapeHtml(visualTestLabel) +
      "</button></div>" +
      '<div class="model-select-wrap"><select class="model-select" id="visual-api-model" aria-label="生图模型">' +
      visualModelOpts +
      "</select></div></article>" +
      '' +
      '<div class="tts-settings-compact__actions">' +
      '<button type="button" class="btn btn--primary btn--pill" id="visual-image-settings-save-btn">保存生图设置</button>' +
      "</div></div></section>";
    return html;
  }

  function collectVisualImageSettingsFromForm(rootEl) {
    if (!rootEl) return;
    const styleSel = rootEl.querySelector("#visual-image-style-select");
    const appearancePrompt = rootEl.querySelector('[data-visual-ref-prompt="appearance"]');
    const dailyPrompt = rootEl.querySelector('[data-visual-ref-prompt="daily"]');
    const appearanceCelebrity = rootEl.querySelector('[data-visual-ref-celebrity="appearance"]');
    const endpoint = rootEl.querySelector("#visual-api-endpoint");
    const apiKey = rootEl.querySelector("#visual-api-key");
    const model = rootEl.querySelector("#visual-api-model");
    if (styleSel) visualImageSettings.style = styleSel.value || "realism";
    if (appearancePrompt) visualImageSettings.appearanceRef.prompt = String(appearancePrompt.value || "").trim();
    if (dailyPrompt) visualImageSettings.dailyRef.prompt = String(dailyPrompt.value || "").trim();
    if (appearanceCelebrity) {
      visualImageSettings.appearanceRef.celebrityLookalike = String(appearanceCelebrity.value || "").trim();
    }
    if (endpoint) visualImageSettings.api.endpoint = String(endpoint.value || "").trim();
    if (apiKey) visualImageSettings.api.apiKey = String(apiKey.value || "").trim();
    if (model) visualImageSettings.api.model = String(model.value || "").trim();
  }

  function bindVisualMultiRefFileInput(rootEl, refKey) {
    const inputId = refKey === "daily" ? "visual-daily-file" : "visual-appearance-file";
    const pickAttr = refKey === "daily" ? "data-visual-daily-pick" : "data-visual-appearance-pick";
    const label = refKey === "daily" ? "日常" : "外貌";
    const input = rootEl.querySelector("#" + inputId);
    if (!input) return;
    input.addEventListener("change", function () {
      const files = input.files ? Array.from(input.files) : [];
      input.value = "";
      if (!files.length) return;
      const remaining = VISUAL_REF_IMAGE_MAX - getVisualRefImages(refKey).length;
      if (remaining <= 0) {
        showToast("最多上传 " + VISUAL_REF_IMAGE_MAX + " 张" + label + "参考图", "warning");
        return;
      }
      const batch = files.slice(0, remaining);
      if (files.length > remaining) {
        showToast("仅添加前 " + remaining + " 张，已达上限 " + VISUAL_REF_IMAGE_MAX + " 张", "info");
      }
      collectVisualImageSettingsFromForm(rootEl);
      void Promise.all(
        batch.map(function (file) {
          return readImageAsCompressedDataURL(file, 960, 520000);
        })
      )
        .then(function (dataUrls) {
          const urls = getVisualRefImages(refKey);
          dataUrls.forEach(function (dataUrl) {
            if (urls.length < VISUAL_REF_IMAGE_MAX) urls.push(dataUrl);
          });
          const ref =
            refKey === "daily" ? visualImageSettings.dailyRef : visualImageSettings.appearanceRef;
          ref.imageDataUrls = urls.slice(0, VISUAL_REF_IMAGE_MAX);
          invalidateVisualRefVisionCache(refKey);
          persistVisualImageSettings();
          renderDynamic();
          showToast("已添加 " + dataUrls.length + " 张参考图", "success");
        })
        .catch(function () {
          showToast("图片过大或格式不支持", "warning");
        });
    });
    rootEl.querySelectorAll("[" + pickAttr + "]").forEach(function (btn) {
      btn.addEventListener("click", function () {
        if (getVisualRefImages(refKey).length >= VISUAL_REF_IMAGE_MAX) {
          showToast("最多上传 " + VISUAL_REF_IMAGE_MAX + " 张" + label + "参考图", "warning");
          return;
        }
        input.click();
      });
    });
  }

  function bindVisualImageSettingsHandlers(rootEl) {
    if (!rootEl) return;
    const enabledToggle = rootEl.querySelector("#visual-image-enabled-toggle");
    if (enabledToggle) {
      enabledToggle.addEventListener("click", function () {
        visualImageSettings.enabled = !visualImageSettings.enabled;
        persistVisualImageSettings();
        renderDynamic();
      });
    }
    const styleSel = rootEl.querySelector("#visual-image-style-select");
    if (styleSel) {
      styleSel.addEventListener("change", function () {
        visualImageSettings.style = styleSel.value || "realism";
        persistVisualImageSettings();
      });
    }
    rootEl.querySelectorAll("[data-visual-ref-prompt]").forEach(function (ta) {
      ta.addEventListener("blur", function () {
        collectVisualImageSettingsFromForm(rootEl);
        persistVisualImageSettings();
      });
    });
    rootEl.querySelectorAll("[data-visual-ref-celebrity]").forEach(function (input) {
      input.addEventListener("blur", function () {
        collectVisualImageSettingsFromForm(rootEl);
        persistVisualImageSettings();
      });
    });
    rootEl.querySelectorAll("[data-visual-ref-remove]").forEach(function (btn) {
      btn.addEventListener("click", function () {
        const key = btn.getAttribute("data-visual-ref-remove");
        const idx = parseInt(btn.getAttribute("data-visual-ref-index") || "", 10);
        if ((key === "appearance" || key === "daily") && !Number.isNaN(idx)) {
          const urls = getVisualRefImages(key);
          if (idx >= 0 && idx < urls.length) {
            urls.splice(idx, 1);
            const ref =
              key === "daily" ? visualImageSettings.dailyRef : visualImageSettings.appearanceRef;
            ref.imageDataUrls = urls;
            invalidateVisualRefVisionCache(key);
          }
        }
        collectVisualImageSettingsFromForm(rootEl);
        persistVisualImageSettings();
        renderDynamic();
      });
    });
    bindVisualMultiRefFileInput(rootEl, "appearance");
    bindVisualMultiRefFileInput(rootEl, "daily");
    const visualModelSel = rootEl.querySelector("#visual-api-model");
    if (visualModelSel) {
      visualModelSel.addEventListener("change", function () {
        visualImageSettings.api.model = String(visualModelSel.value || "").trim();
        persistVisualImageSettings();
      });
    }
    const visualRefreshBtn = rootEl.querySelector(".visual-api-refresh");
    if (visualRefreshBtn) {
      visualRefreshBtn.addEventListener("click", function () {
        if (visualImageModelsRefreshing || visualImageModelTesting) return;
        collectVisualImageSettingsFromForm(rootEl);
        const cfg = visualImageApiCfgFromSettings();
        visualImageModelsRefreshing = true;
        renderDynamic();
        void fetchModelsForConfig(cfg)
          .then(function (models) {
            visualImageSettings.api.availableModels = models;
            if (!models.includes(visualImageSettings.api.model)) {
              visualImageSettings.api.model = models[0] || visualImageSettings.api.model;
            }
            persistVisualImageSettings();
            showToast("生图模型列表已更新，共 " + models.length + " 个", "success");
          })
          .catch(function (err) {
            return alertModelListFetchFailed(err);
          })
          .finally(function () {
            visualImageModelsRefreshing = false;
            renderDynamic();
          });
      });
    }
    const visualTestBtn = rootEl.querySelector(".visual-api-test");
    if (visualTestBtn) {
      visualTestBtn.addEventListener("click", function () {
        if (visualImageModelTesting || visualImageModelsRefreshing) return;
        collectVisualImageSettingsFromForm(rootEl);
        const cfg = visualImageApiCfgFromSettings();
        const modelSel = rootEl.querySelector("#visual-api-model");
        const modelId =
          modelSel && modelSel.value != null ? String(modelSel.value).trim() : cfg.model;
        visualImageModelTesting = true;
        renderDynamic();
        showToast("正在测试生图，GPT 模型可能需要 1～3 分钟，请耐心等待…", "info", 8000);
        void testVisualImageModelAvailability(cfg, modelId)
          .then(function () {
            showToast("生图模型「" + modelId + "」可用", "success");
          })
          .catch(function (err) {
            showToast("测试失败：" + (err && err.message ? err.message : String(err)), "error", 5200);
          })
          .finally(function () {
            visualImageModelTesting = false;
            renderDynamic();
          });
      });
    }
    const saveBtn = rootEl.querySelector("#visual-image-settings-save-btn");
    if (saveBtn) {
      saveBtn.addEventListener("click", function () {
        collectVisualImageSettingsFromForm(rootEl);
        persistVisualImageSettings();
        showToast("生图设置已保存", "success");
      });
    }
  }

  function collectTtsSettingsFromForm(rootEl) {
    if (!rootEl) return;
    const apiKey = rootEl.querySelector("#minimax-api-key");
    const groupId = rootEl.querySelector("#minimax-group-id");
    const region = rootEl.querySelector("#minimax-region-select");
    const baseUrl = rootEl.querySelector("#minimax-base-url");
    const voiceId = rootEl.querySelector("#minimax-voice-id");
    const model = rootEl.querySelector("#minimax-model-select");
    const voicePrompt = rootEl.querySelector("#minimax-voice-prompt");
    if (apiKey) ttsSettings.apiKey = String(apiKey.value || "").trim();
    if (groupId) ttsSettings.groupId = String(groupId.value || "").trim();
    if (region) ttsSettings.region = region.value || "cn";
    if (baseUrl) ttsSettings.baseUrl = String(baseUrl.value || "").trim();
    if (voiceId) ttsSettings.voiceId = String(voiceId.value || "").trim();
    if (model) ttsSettings.model = model.value || "speech-2.8-hd";
    if (voicePrompt) ttsSettings.voicePrompt = String(voicePrompt.value || "").trim();
  }

  function buildTtsSettingsSectionHtml() {
    const regionOpts = MINIMAX_REGIONS.map(function (r) {
      const shortLabel = r.id === "intl" ? "国际" : "国内";
      return (
        '<option value="' +
        escapeHtml(r.id) +
        '"' +
        (ttsSettings.region === r.id ? " selected" : "") +
        ">" +
        escapeHtml(shortLabel) +
        "</option>"
      );
    }).join("");
    const modelOpts = MINIMAX_TTS_MODELS.map(function (m) {
      let shortLabel = m.id;
      if (m.id === "speech-2.8-hd") shortLabel = "2.8-HD";
      else if (m.id === "speech-2.8-turbo") shortLabel = "2.8-Turbo";
      else if (m.id === "speech-02-hd") shortLabel = "HD";
      else if (m.id === "speech-02-turbo") shortLabel = "Turbo";
      else if (m.id === "speech-01-hd") shortLabel = "01-HD";
      else if (m.id === "speech-01-turbo") shortLabel = "01-Turbo";
      return (
        '<option value="' +
        escapeHtml(m.id) +
        '"' +
        (ttsSettings.model === m.id ? " selected" : "") +
        ">" +
        escapeHtml(shortLabel) +
        "</option>"
      );
    }).join("");
    const shownVoiceId = String(ttsSettings.voiceId || ttsSettings.clonedVoiceId || "").trim();
    return (
      '<section class="settings-panel settings-panel--tts">' +
      '<div class="settings-panel__head"><h3 class="settings-panel__title">剧情朗读</h3></div>' +
      '<div class="settings-panel__body tts-settings-compact">' +
      '<div class="tts-settings-compact__grid">' +
      '<input class="field__input" id="minimax-api-key" type="password" placeholder="订阅 Key 或按量 API Key" value="' +
      escapeHtml(ttsSettings.apiKey || "") +
      '" autocomplete="off" />' +
      '<input class="field__input" id="minimax-group-id" type="text" placeholder="Group ID" value="' +
      escapeHtml(ttsSettings.groupId || "") +
      '" autocomplete="off" />' +
      '<select class="field__input" id="minimax-region-select" aria-label="MiniMax 版本">' +
      regionOpts +
      "</select>" +
      '<input class="field__input" id="minimax-base-url" type="url" placeholder="Base URL" value="' +
      escapeHtml(ttsSettings.baseUrl || "") +
      '" />' +
      '<input class="field__input" id="minimax-voice-id" type="text" placeholder="音色 ID" value="' +
      escapeHtml(shownVoiceId) +
      '" autocomplete="off" />' +
      '<select class="field__input" id="minimax-model-select" aria-label="语音模型">' +
      modelOpts +
      "</select>" +
      "</div>" +
      '<textarea class="field__input field__textarea tts-settings-compact__prompt" id="minimax-voice-prompt" rows="3" placeholder="语气补充（可选）">' +
      escapeHtml(ttsSettings.voicePrompt || "") +
      "</textarea>" +
      '<div class="tts-settings-compact__actions">' +
      '<button type="button" class="btn btn--primary btn--pill" id="minimax-voice-save-btn">保存</button>' +
      '<button type="button" class="btn btn--secondary btn--pill" id="minimax-voice-preview-btn">试听</button>' +
      "</div></div></section>"
    );
  }

  function bindTtsSettingsHandlers(rootEl) {
    if (!rootEl) return;
    if (!ttsSettings.enabled) {
      ttsSettings.enabled = true;
      persistTtsSettings();
    }
    const regionSel = rootEl.querySelector("#minimax-region-select");
    if (regionSel) {
      regionSel.addEventListener("change", function () {
        ttsSettings.region = regionSel.value || "cn";
        persistTtsSettings();
      });
    }
    const saveBtn = rootEl.querySelector("#minimax-voice-save-btn");
    if (saveBtn) {
      saveBtn.addEventListener("click", function () {
        collectTtsSettingsFromForm(rootEl);
        if (!ttsSettings.apiKey) {
          showToast("请先填写 API Key。", "warning");
          return;
        }
        if (!resolveGlobalMinimaxVoiceId()) {
          showToast("请填写音色 ID。", "warning");
          return;
        }
        persistTtsSettings();
        showToast("已保存", "success");
      });
    }
    const previewBtn = rootEl.querySelector("#minimax-voice-preview-btn");
    if (previewBtn) {
      previewBtn.addEventListener("click", function () {
        collectTtsSettingsFromForm(rootEl);
        persistTtsSettings();
        void previewMinimaxVoice(previewBtn);
      });
    }
    rootEl
      .querySelectorAll(
        "#minimax-api-key, #minimax-group-id, #minimax-base-url, #minimax-voice-id, #minimax-voice-prompt"
      )
      .forEach(function (el) {
        el.addEventListener("change", function () {
          collectTtsSettingsFromForm(rootEl);
          persistTtsSettings();
        });
      });
    rootEl.querySelectorAll("#minimax-region-select, #minimax-model-select").forEach(function (el) {
      el.addEventListener("change", function () {
        collectTtsSettingsFromForm(rootEl);
        persistTtsSettings();
      });
    });
  }


  function bindApiSettingsHandlers(rootEl) {
    if (!rootEl) return;
    rootEl.querySelectorAll(".api-enable-check").forEach(function (cb) {
      cb.addEventListener("change", function (e) {
        e.stopPropagation();
        const id = String(cb.dataset.id || "").trim();
        if (cb.checked) {
          const checkedCount = rootEl.querySelectorAll(".api-enable-check:checked").length;
          if (checkedCount > 2) {
            rootEl.querySelectorAll(".api-enable-check:checked").forEach(function (other) {
              const oid = String(other.dataset.id || "").trim();
              if (oid && oid !== activeApiId && oid !== id) other.checked = false;
            });
          }
        } else if (!rootEl.querySelectorAll(".api-enable-check:checked").length) {
          cb.checked = true;
          return;
        }
        syncApiSelectionFromChecks(rootEl);
        persistApiConfigs();
        renderDynamic();
      });
    });

    rootEl.querySelectorAll(".api-edit").forEach((btn) => {
      btn.addEventListener("click", (e) => {
        e.stopPropagation();
        openApiModal(btn.dataset.id);
      });
    });
    rootEl.querySelectorAll(".api-del").forEach((btn) => {
      btn.addEventListener("click", async (e) => {
        e.stopPropagation();
        if (!(await showConfirm("确定删除此配置？"))) return;
        apiConfigs = apiConfigs.filter((a) => a.id !== btn.dataset.id);
        if (activeApiId === btn.dataset.id) activeApiId = apiConfigs[0]?.id || "";
        if (secondaryApiId === btn.dataset.id) secondaryApiId = "";
        persistApiConfigs();
        renderDynamic();
      });
    });
    rootEl.querySelectorAll(".api-refresh").forEach((btn) => {
      btn.addEventListener("click", async (e) => {
        e.stopPropagation();
        if (modelsRefreshing) return;
        const cfg = apiConfigs.find((a) => a.id === btn.dataset.id);
        if (!cfg) return;
        modelsRefreshing = true;
        btn.textContent = "刷新中…";
        try {
          const models = await fetchModelsForConfig(cfg);
          cfg.availableModels = models;
          if (!models.includes(cfg.model)) cfg.model = models[0] || cfg.model;
          persistApiConfigs();
          showToast("模型列表已更新，共 " + models.length + " 个", "success");
        } catch (err) {
          await alertModelListFetchFailed(err);
        } finally {
          modelsRefreshing = false;
          renderDynamic();
        }
      });
    });
    rootEl.querySelectorAll(".api-test").forEach((btn) => {
      btn.addEventListener("click", async (e) => {
        e.stopPropagation();
        if (modelTesting || modelsRefreshing) return;
        const cfg = apiConfigs.find((a) => a.id === btn.dataset.id);
        if (!cfg) return;
        const card = btn.closest(".api-card");
        const sel = card && card.querySelector(".api-model");
        const modelId = sel && sel.value != null ? sel.value : cfg.model;
        modelTesting = true;
        btn.textContent = "测试中…";
        try {
          await testModelAvailabilityForConfig(cfg, modelId);
          showToast("模型「" + modelId + "」可用", "success");
        } catch (err) {
          showToast("测试失败：" + (err && err.message ? err.message : String(err)), "error", 5200);
        } finally {
          modelTesting = false;
          renderDynamic();
        }
      });
    });
    rootEl.querySelectorAll(".api-model").forEach((sel) => {
      sel.addEventListener("change", (e) => {
        e.stopPropagation();
        const cfg = apiConfigs.find((a) => a.id === sel.dataset.id);
        if (cfg) cfg.model = sel.value;
        persistApiConfigs();
      });
    });

    const formNew = rootEl.querySelector(".js-form-new-api");
    if (formNew) {
      formNew.addEventListener("submit", (ev) => {
        ev.preventDefault();
        const fd = new FormData(formNew);
        const nid = uid("a");
        apiConfigs.push({
          id: nid,
          name: fd.get("name").trim(),
          endpoint: fd.get("endpoint").trim(),
          key: fd.get("key") || "sk-placeholder",
          model: "gpt-4o-mini",
        });
        showSettingsAdd = false;
        persistApiConfigs();
        renderDynamic();
      });
    }

    const revealAdd = rootEl.querySelector(".js-settings-reveal-add");
    if (revealAdd) {
      revealAdd.addEventListener("click", () => {
        showSettingsAdd = true;
        renderDynamic();
      });
    }
  }

  function renderStoryApiSettingsModalContent() {
    const mount = document.getElementById("story-api-settings-mount");
    if (!mount) return;
    mount.innerHTML = buildApiSettingsSectionHtml({ omitPanelHead: true });
    bindApiSettingsHandlers(mount);
    enhanceCustomSelectsIn(mount);
    document.querySelectorAll(".js-add-api-block").forEach((block) => {
      block.hidden = !showSettingsAdd;
    });
  }

  function openStoryApiSettingsModal() {
    const modal = document.getElementById("modal-story-api");
    if (!modal) return;
    renderStoryApiSettingsModalContent();
    modal.hidden = false;
  }

  function closeStoryApiSettingsModal() {
    const modal = document.getElementById("modal-story-api");
    if (modal) modal.hidden = true;
    if (showSettingsAdd) {
      showSettingsAdd = false;
      renderDynamic();
    }
  }

  function loadApiHeartFloatPosition(btn) {
    if (!btn) return;
    try {
      const raw = localStorage.getItem(STORAGE_API_HEART_FLOAT_POS);
      if (!raw) return;
      const pos = JSON.parse(raw);
      if (!pos || typeof pos !== "object") return;
      const parent = btn.offsetParent || btn.parentElement;
      if (!parent) return;
      const rect = parent.getBoundingClientRect();
      const size = btn.offsetWidth || 22;
      const pad = 8;
      let left = typeof pos.left === "number" ? pos.left : NaN;
      let top = typeof pos.top === "number" ? pos.top : NaN;
      if (!Number.isFinite(left) || !Number.isFinite(top)) return;
      left = Math.max(pad, Math.min(left, rect.width - size - pad));
      top = Math.max(pad, Math.min(top, rect.height - size - pad));
      btn.style.left = left + "px";
      btn.style.top = top + "px";
      btn.style.right = "auto";
      btn.style.bottom = "auto";
    } catch (e) {}
  }

  function persistApiHeartFloatPosition(btn) {
    if (!btn) return;
    try {
      const left = parseFloat(btn.style.left);
      const top = parseFloat(btn.style.top);
      if (!Number.isFinite(left) || !Number.isFinite(top)) return;
      localStorage.setItem(STORAGE_API_HEART_FLOAT_POS, JSON.stringify({ left: left, top: top }));
    } catch (e) {}
  }

  function bindApiHeartFloat() {
    const btn = document.getElementById("api-heart-float");
    if (!btn || btn.dataset.bound === "1") return;
    btn.dataset.bound = "1";
    loadApiHeartFloatPosition(btn);

    const LONG_PRESS_MS = 420;
    const DRAG_THRESHOLD = 8;
    let pressTimer = 0;
    let dragging = false;
    let dragReady = false;
    let moved = false;
    let startX = 0;
    let startY = 0;
    let originLeft = 0;
    let originTop = 0;
    let activePointerId = null;

    function clearPressTimer() {
      if (pressTimer) {
        clearTimeout(pressTimer);
        pressTimer = 0;
      }
    }

    function getParentRect() {
      const parent = btn.offsetParent || btn.parentElement;
      return parent ? parent.getBoundingClientRect() : null;
    }

    function snapToPosition(clientX, clientY) {
      const rect = getParentRect();
      if (!rect) return;
      const size = btn.offsetWidth || 22;
      const pad = 8;
      let left = clientX - rect.left - size / 2;
      let top = clientY - rect.top - size / 2;
      left = Math.max(pad, Math.min(left, rect.width - size - pad));
      top = Math.max(pad, Math.min(top, rect.height - size - pad));
      btn.style.left = left + "px";
      btn.style.top = top + "px";
      btn.style.right = "auto";
      btn.style.bottom = "auto";
    }

    function onPointerDown(e) {
      if (e.button != null && e.button !== 0) return;
      activePointerId = e.pointerId;
      startX = e.clientX;
      startY = e.clientY;
      moved = false;
      dragging = false;
      dragReady = false;
      clearPressTimer();
      pressTimer = setTimeout(function () {
        dragReady = true;
        btn.classList.add("api-heart-float--dragging");
        try {
          btn.setPointerCapture(activePointerId);
        } catch (err) {}
        snapToPosition(startX, startY);
      }, LONG_PRESS_MS);
    }

    function onPointerMove(e) {
      if (activePointerId !== e.pointerId) return;
      const dx = e.clientX - startX;
      const dy = e.clientY - startY;
      if (!dragReady) {
        if (Math.hypot(dx, dy) >= DRAG_THRESHOLD) clearPressTimer();
        return;
      }
      moved = true;
      dragging = true;
      e.preventDefault();
      snapToPosition(e.clientX, e.clientY);
    }

    function onPointerUp(e) {
      if (activePointerId !== e.pointerId) return;
      clearPressTimer();
      btn.classList.remove("api-heart-float--dragging");
      try {
        btn.releasePointerCapture(e.pointerId);
      } catch (err) {}
      if (dragging || dragReady) {
        persistApiHeartFloatPosition(btn);
      } else if (!moved) {
        openStoryApiSettingsModal();
      }
      dragging = false;
      dragReady = false;
      moved = false;
      activePointerId = null;
    }

    btn.addEventListener("pointerdown", onPointerDown);
    btn.addEventListener("pointermove", onPointerMove);
    btn.addEventListener("pointerup", onPointerUp);
    btn.addEventListener("pointercancel", onPointerUp);
  }

