  function openApiModal(id) {
    apiModalEditingId = id;
    const a = apiConfigs.find((x) => x.id === id);
    if (!a) return;
    document.getElementById("api-modal-title").textContent = "编辑配置";
    document.getElementById("api-form-id").value = a.id;
    document.getElementById("api-form-name").value = a.name;
    document.getElementById("api-form-endpoint").value = a.endpoint;
    document.getElementById("api-form-key").value = a.key;
    els.modalApi().hidden = false;
  }

  function closeApiModal() {
    els.modalApi().hidden = true;
  }

  function renderDynamic() {
    var layerStory = els.layerStory();
    var storyOpen = !!(layerStory && !layerStory.hidden);
    if (activeTab === "overview" && !storyOpen) {
      renderAssistantHeader();
      syncOverviewSubViewUi();
      if (overviewSubView === "phone") renderPhoneScreen(els.phoneContentSlot());
      else if (overviewSubView === "fanwork") renderFanworkScreen(els.fanworkContentSlot());
      else if (overviewSubView === "knock") renderKnockScreen(els.knockContentSlot(), { scrollToEnd: true });
      else if (overviewSubView === "collect") renderCollectScreen(els.collectContentSlot());
      else if (overviewSubView === "todo") renderTaskTodoScreen(els.todoContentSlot());
      else if (overviewSubView === "radio") renderRadioScreen(els.radioContentSlot());
      else if (overviewSubView === "pass-note") renderPassNoteScreen(els.passNoteContentSlot());
      else if (overviewSubView === "you-dog") {
        markYouDogChatScrollToEndIfVisible();
        renderYouDogScreen(els.youDogContentSlot());
      } else if (overviewSubView === "grudge-book") renderGrudgeBookScreen(els.grudgeBookContentSlot());
    }
    if (els.modalAssistantProfile() && !els.modalAssistantProfile().hidden) {
      renderAssistantProfileModal();
    }

    if (activeTab === "worldbook" && !storyOpen) {
      renderWbFilters();
      renderWbList();
    } else if (activeTab === "plot" && !storyOpen) {
      renderPlotFilters();
      renderPlotList();
    } else if (activeTab === "characters" && !storyOpen) {
      renderCharFilters();
      renderCharList();
    } else if (activeTab === "settings" && !storyOpen) {
      renderSettings();
    }

    if (document.querySelector(".phone-home")) {
      updatePhoneHomeOwnerLabels();
      applyPhoneWallpaperStyles();
    }

    document.querySelectorAll(".js-add-api-block").forEach((block) => {
      block.hidden = !showSettingsAdd;
    });
    const modalStoryApi = document.getElementById("modal-story-api");
    if (modalStoryApi && !modalStoryApi.hidden) {
      renderStoryApiSettingsModalContent();
    }
    enhanceCustomSelectsVisible();
    schedulePersistNarrative();
  }

  /** 每次冷启动 / 刷新后固定进入点星主界面（工作台），不恢复上次 tab、子功能或剧情层。 */
  function resetToOverviewHomeOnPageLoad() {
    closeKnockSetupPortal();
    overviewSubView = null;
    try {
      location.replace("#/tab/overview");
    } catch (e) {
      location.hash = "#/tab/overview";
    }
  }

  function applyHash() {
    const h = location.hash || "#/tab/overview";
    if (h.startsWith("#/story/")) {
      const rest = h.slice("#/story/".length);
      const parts = rest.split("/").filter(Boolean);
      const pid = parts[0];
      const subRaw = parts[1];
      const p = plots.find((x) => x.id === pid);
      if (!p) {
        closeStoryLayer();
        return;
      }
      let sub = subRaw;
      if (sub !== "setup" && sub !== "play") {
        sub = p.storyEntered ? "play" : "setup";
        const fix = "#/story/" + pid + "/" + sub;
        if (h !== fix) {
          location.replace(fix);
          return;
        }
      }
      if (sub === "play" && !p.storyEntered) {
        location.replace("#/story/" + pid + "/setup");
        return;
      }
      openStoryLayer(p, sub, { skipHashSet: true });
      return;
    }
    if (h.startsWith("#/tab/")) {
      let t = h.replace("#/tab/", "").split("/")[0];
      if (LEGACY_OVERVIEW_SUB_TAB_IDS[t]) {
        if (t === "knock") {
          els.layerStory().hidden = true;
          activeTab = "overview";
          els.views().forEach((v) => v.classList.toggle("view--active", v.dataset.view === "overview"));
          els.navItems().forEach((btn) => btn.classList.toggle("is-active", btn.dataset.tab === "overview"));
          syncMainScrollMode();
          void openOverviewKnockView();
          return;
        }
        overviewSubView = LEGACY_OVERVIEW_SUB_TAB_IDS[t];
        t = "overview";
      } else if (t === "overview") {
        overviewSubView = null;
      }
      if (MAIN_TAB_IDS.includes(t)) {
        els.layerStory().hidden = true;
        if (t !== "overview") overviewSubView = null;
        activeTab = t;
        els.views().forEach((v) => v.classList.toggle("view--active", v.dataset.view === t));
        els.navItems().forEach((btn) => btn.classList.toggle("is-active", btn.dataset.tab === t));
        syncMainScrollMode();
        syncOverviewSubViewUi();
        renderDynamic();
      }
    }
  }

  function bindNav() {
    els.navItems().forEach((btn) => {
      btn.addEventListener("click", () => {
        setTab(btn.dataset.tab);
      });
    });
  }

  function persistEnvelopePhoto(dataUrl) {
    if (suppressUserDataPersistence) return;
    try {
      if (dataUrl) localStorage.setItem(STORAGE_ENVELOPE_PHOTO, dataUrl);
      else localStorage.removeItem(STORAGE_ENVELOPE_PHOTO);
    } catch (e) {
      if (e && (e.name === "QuotaExceededError" || e.code === 22)) {
        showToast("信封照片保存失败：本地存储空间不足。", "error");
      }
    }
  }

  function loadEnvelopePhoto() {
    try {
      return localStorage.getItem(STORAGE_ENVELOPE_PHOTO) || "";
    } catch (e) {
      return "";
    }
  }

  function applyEnvelopePhotoToDom() {
    const root = document.getElementById("view-overview");
    if (!root) return;
    const envelope = root.querySelector(".workbench-envelope");
    if (!envelope) return;
    const photoImg = envelope.querySelector(".envelope-photo");
    const hint = envelope.querySelector(".envelope-upload-hint");
    const dataUrl = loadEnvelopePhoto();
    if (photoImg && dataUrl) {
      photoImg.src = dataUrl;
      photoImg.hidden = false;
      if (hint) hint.style.display = "none";
    }
  }

  function bindOverviewWorkbenchActions() {
    const root = document.getElementById("view-overview");
    if (!root) return;
    let lastTapAt = 0;
    function onWorkbenchAction(e) {
      const chip = e.target.closest(".workbench-tools [data-assistant-action], .workbench-features [data-assistant-action]");
      if (!chip || !root.contains(chip)) return;
      const now = Date.now();
      if (now - lastTapAt < 320) return;
      lastTapAt = now;
      const action = String(chip.getAttribute("data-assistant-action") || "").trim();
      if (!action) return;
      if (e.cancelable) e.preventDefault();
      handleAssistantQuickAction(action);
    }
    root.addEventListener("click", onWorkbenchAction);
    root.addEventListener("touchend", onWorkbenchAction, { passive: false });

    // 信封照片上传
    const envelope = root.querySelector(".workbench-envelope");
    if (envelope) {
      const fileInput = envelope.querySelector(".envelope-file-input");
      const photoImg = envelope.querySelector(".envelope-photo");
      const hint = envelope.querySelector(".envelope-upload-hint");
      if (fileInput && photoImg) {
        fileInput.addEventListener("change", (e) => {
          const file = e.target.files && e.target.files[0];
          if (!file) return;
          const reader = new FileReader();
          reader.onload = (ev) => {
            const dataUrl = ev.target.result;
            photoImg.src = dataUrl;
            photoImg.hidden = false;
            if (hint) hint.style.display = "none";
            persistEnvelopePhoto(dataUrl);
          };
          reader.readAsDataURL(file);
        });
      }
      applyEnvelopePhotoToDom();
    }
  }

