      const btn = e.target.closest("[data-selection-action]");
      if (!btn) return;
      storySelectionSuppressClickUntil = 0;
      e.preventDefault();
      e.stopPropagation();
      void handleStorySelectionAction(String(btn.getAttribute("data-selection-action") || ""));
